        <div class="chapter">
<h2 class="nobreak" title="III King Henry the Sixth." id="idc">
<span class="smaller">THE THIRD PART OF</span>
KING HENRY THE SIXTH.</h2></div>

<h3 class="h3main" title="Dramatis Personæ.">
DRAMATIS PERSONÆ†.</h3>

<div class="dpbox">
<div class="right toppada"><small><a href="#idtoc" class="pginternal">toc</a></small></div>
<ul>
<li> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span></span> the Sixth.</li>
<li><span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">P<span>RINCE</span></span> <span class="smmaj">OF</span> <span class="smcaps">W<span>ALES</span>,</span> his son.</li>
<li><span class="smcaps">L<span>EWIS</span></span> <span class="smmaj">XI.</span> <span class="smcaps">K<span>ING</span></span> <span class="smmaj">OF</span> <span class="smcaps">F<span>RANCE</span></span>.</li>
<li><span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">S<span>OMERSET</span></span>.</li>
<li><span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">E<span>XETER</span></span>.</li>
<li><span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">O<span>XFORD</span></span>.</li>
<li><span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">N<span>ORTHUMBERLAND</span></span>.</li>
<li><span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">W<span>ESTMORELAND</span></span>.</li>
<li><span class="smcaps">L<span>ORD</span></span> <span class="smcaps">C<span>LIFFORD</span></span>.</li>
<li><span class="smcaps">R<span>ICHARD</span></span> <span class="smcaps">P<span>LANTAGENET</span>,</span> Duke of York.</li>
<li>his sons:
<ul><li><span class="smcaps">E<span>DWARD</span>,</span> Earl of March, afterwards King Edward IV.,</li>
<li><span class="smcaps">E<span>DMUND</span>,</span> Earl of Rutland,</li>
<li><span class="smcaps">G<span>EORGE</span>,</span> afterwards Duke of Clarence,</li>
<li><span class="smcaps">R<span>ICHARD</span>,</span> afterwards Duke of Gloucester,</li>
<li><span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span> <span class="smcaps">N<span>ORFOLK</span></span>.</li></ul></li>
<li><span class="smcaps">M<span>ARQUESS</span></span> <span class="smmaj">OF</span> <span class="smcaps">M<span>ONTAGUE</span>.</span>
<span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">W<span>ARWICK</span>.</span>
<span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span> <span class="smcaps">P<span>EMBROKE</span>.</span>
<span class="smcaps">L<span>ORD</span></span> <span class="smcaps">H<span>ASTINGS</span>.</span>
<span class="smcaps">L<span>ORD</span></span> <span class="smcaps">S<span>TAFFORD</span></span>.</li>
<li>uncles to the Duke of York.
<ul><li>     <span class="smcaps">S<span>IR</span></span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">M<span>ORTIMER</span></span>,</li>
<li>     <span class="smcaps">S<span>IR</span></span> <span class="smcaps">H<span>UGH</span></span> <span class="smcaps">M<span>ORTIMER</span></span>,</li>
<li> <span class="smcaps">H<span>ENRY</span>,</span> Earl of Richmond, a youth.</li></ul></li>
<li><span class="smcaps">L<span>ORD</span></span> <span class="smcaps">R<span>IVERS</span>,</span> brother to Lady Grey.</li>
<li><span class="smcaps">S<span>IR</span></span> <span class="smcaps">W<span>ILLIAM</span></span> <span class="smcaps">S<span>TANLEY</span></span>.</li>
<li><span class="smcaps">S<span>IR</span></span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">M<span>ONTGOMERY</span></span>.</li>
<li><span class="smcaps">S<span>IR</span></span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">S<span>OMERVILLE</span></span>.</li>
<li>Tutor to Rutland. Mayor of York.</li>
<li>Lieutenant of the Tower. A Nobleman.</li>
<li>Two Keepers. A Huntsman.</li>
<li>A Son that has killed his father.</li>
<li>A Father that has killed his son.</li>
<li><span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">M<span>ARGARET</span></span>.</li>
<li><span class="smcaps">L<span>ADY</span></span> <span class="smcaps">G<span>REY</span>,</span> afterwards Queen to Edward IV.</li>
<li><span class="smcaps">B<span>ONA</span>,</span> sister to the French Queen.</li></ul>
</div>

<div class="toppada">Soldiers, Attendants, Messengers, Watchmen, &amp;c.</div>

<div class="toppada"><span class="smcaps">S<span>CENE</span>:</span> <i>England and France.</i></div>

<p class="footnote"> <span class="fnline"> </span>
 † <span class="smcaps">D<span>RAMATIS</span></span>
 <span class="smcaps">P<span>ERSONÆ</span>.</span>
 First given, imperfectly, by Rowe.</p>

<h3 class="pgbrk" title="ACT I.">
THE THIRD PART OF
<span class="larger">KING HENRY VI.</span>
ACT I.</h3>

<h4 class="h4main"><span class="dnavigate">caa</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>London. The Parliament-house</i>.</h4>

<div class="sd-schg"><i>Alarum. Enter the</i> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">Y<span>ORK</span>,</span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">R<span>ICHARD</span>,</span> <span class="smcaps">N<span>ORFOLK</span>,</span> <span class="smcaps">M<span>ONTAGUE</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <i>and Soldiers</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa001" id="lnum-caa001">♦</a>
 <span class="sd-cn">War.</span>
  I wonder how the king escaped our hands.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 While we pursued the horsemen of the north,</div>
<div class="dverse">He slily stole away and left his men:</div>
<div class="dverse">Whereat the great Lord of Northumberland,</div>
<div class="dverse"><span class="lnum">5</span>
 Whose warlike ears could never brook retreat,</div>
<div class="dverse">Cheer’d up the drooping army; and himself,</div>
<div class="dverse">Lord Clifford and Lord Stafford, all a-breast,</div>
<div class="dverse">Charged our main battle’s front, and breaking in</div>
<div class="dverse">Were by the swords of common soldiers slain.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Edw.</span>
 Lord Stafford’s father, Duke of Buckingham,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa011" id="lnum-caa011">♦</a>
 Is either slain or wounded dangerously;</div>
<div class="dverse">I cleft his beaver with a downright blow:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa013" id="lnum-caa013">♦</a>
 That this is true, father, behold his blood.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa014" id="lnum-caa014">♦</a>
 <span class="sd-cn">Mont.</span>
  And, brother, here’s the Earl of Wiltshire’s blood,</div>
<div class="dverse"><span class="lnum">15</span>
 Whom I encounter’d as the battles join’d.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa016" id="lnum-caa016">♦</a>
 <span class="sd-cn">Rich.</span>
 Speak thou for me and tell them what I did.
 <span class="sd-verseend">[<i>Throwing down the Duke of Somerset’s head.</i></span></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Richard hath best deserved of all my sons.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa018" id="lnum-caa018">♦</a>
 But is your grace dead, my Lord of Somerset?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa019" id="lnum-caa019">♦</a>
 <span class="sd-cn">Norf.</span>
  Such hope have all the line of John of Gaunt!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa020" id="lnum-caa020">20</a>
 <span class="sd-cn">Rich.</span>
  Thus do I hope to shake King Henry’s head.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa021" id="lnum-caa021">♦</a>
 <span class="sd-cn">War.</span>
  And so do I. Victorious Prince of York,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa022" id="lnum-caa022">♦</a>
 Before I see thee seated in that throne</div>
<div class="dverse">Which now the house of Lancaster usurps,</div>
<div class="dverse">I vow by heaven these eyes shall never close.</div>
<div class="dverse"><span class="lnum">25</span>
 This is the palace of the fearful king,</div>
<div class="dverse">And this the regal seat: possess it, York;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa027" id="lnum-caa027">♦</a>
 For this is thine and not King Henry’s heirs’.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Assist me, then, sweet Warwick, and I will;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa029" id="lnum-caa029">♦</a>
 For hither we have broken in by force.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Norf.</span>
 We’ll all assist you; he that flies shall die.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Thanks, gentle Norfolk: stay by me, my lords;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa032" id="lnum-caa032">♦</a>
 And, soldiers, stay and lodge by me this night.
 <span class="sd-verseend">[<i>They go up.</i></span></div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And when the king comes, offer him no violence,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa034" id="lnum-caa034">♦</a>
 Unless he seek to thrust you out perforce.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">York.</span>
 The queen this day here holds her parliament,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa036" id="lnum-caa036">♦</a>
 But little thinks we shall be of her council:</div>
<div class="dverse">By words or blows here let us win our right.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Arm’d as we are, let’s stay within this house.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 The bloody parliament shall this be call’d,</div>
<div class="dverse"><span class="lnum">40</span>
 Unless Plantagenet, Duke of York, be king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa041" id="lnum-caa041">♦</a>
 And bashful Henry deposed, whose cowardice</div>
<div class="dverse">Hath made us by-words to our enemies.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa043" id="lnum-caa043">♦</a>
 <span class="sd-cn">York.</span>
  Then leave me not, my lords; be resolute;</div>
<div class="dverse">I mean to take possession of my right.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">War.</span>
 Neither the king, nor he that loves him best,</div>
<div class="dverse">The proudest he that holds up Lancaster,</div>
<div class="dverse">Dares stir a wing, if Warwick shake his bells.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa048" id="lnum-caa048">♦</a>
 I’ll plant Plantagenet, root him up who dares:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa049" id="lnum-caa049">♦</a>
 Resolve thee, Richard; claim the English crown.</div>

<div class="sd-entry"><i>Flourish. Enter</i>
 <span class="smcaps">K<span>ING</span></span>
 <span class="smcaps">H<span>ENRY</span>,</span>
 <span class="smcaps">C<span>LIFFORD</span>,</span>
 <span class="smcaps">N<span>ORT­HUMB­ER­LAND</span>,</span>
 <span class="smcaps">W<span>EST­MORE­LAND</span>,</span>
 <span class="smcaps">E<span>XETER</span>,</span> <i>and the rest</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa050" id="lnum-caa050">50</a>
 <span class="sd-cn">K. Hen.</span>
  My lords, look where the sturdy rebel sits,</div>
<div class="dverse">Even in the chair of state: belike he means,</div>
<div class="dverse">Back’d by the power of Warwick, that false peer,</div>
<div class="dverse">To aspire unto the crown and reign as king.</div>
<div class="dverse">Earl of Northumberland, he slew thy father,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa055" id="lnum-caa055">55</a>
 And thine, Lord Clifford; and you both have vow’d revenge</div>
<div class="dverse">On him, his sons, his favourites and his friends.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa057" id="lnum-caa057">♦</a>
 <span class="sd-cn">North.</span>
  If I be not, heavens be revenged on me!</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 The hope thereof makes Clifford mourn in steel.</div>

<div class="dverse1"><span class="sd-cn">West.</span>
 What, shall we suffer this? let’s pluck him down:</div>
<div class="dverse"><span class="lnum">60</span>
 My heart for anger burns; I cannot brook it.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Be patient, gentle Earl of Westmoreland.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa062" id="lnum-caa062">♦</a>
 <span class="sd-cn">Clif.</span>
  Patience is for poltroons, such as he:</div>
<div class="dverse">He durst not sit there, had your father lived.</div>
<div class="dverse">My gracious lord, here in the parliament</div>
<div class="dverse"><span class="lnum">65</span>
 Let us assail the family of York.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa066" id="lnum-caa066">♦</a>
 <span class="sd-cn">North.</span>
  Well hast thou spoken, cousin: be it so.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Ah, know you not the city favours them,</div>
<div class="dverse">And they have troops of soldiers at their beck?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa069" id="lnum-caa069">♦</a>
 <span class="sd-cn">Exe.</span>
  But when the duke is slain, they’ll quickly fly.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa070" id="lnum-caa070">70</a>
 <span class="sd-cn">K. Hen.</span>
  Far be the thought of this from Henry’s heart,</div>
<div class="dverse">To make a shambles of the parliament-house!</div>
<div class="dverse">Cousin of Exeter, frowns, words and threats</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa073" id="lnum-caa073">♦</a>
 Shall be the war that Henry means to use.</div>
<div class="dverse">Thou factious Duke of York, descend my throne,</div>
<div class="dverse"><span class="lnum">75</span>
 And kneel for grace and mercy at my feet;</div>
<div class="dverse">I am thy sovereign.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa076" id="lnum-caa076">♦</a>
 <span class="sd-cn">York.</span>
 <span class="i07"> </span> I am thine.</div>

<div class="dverse1"><span class="sd-cn">Exe.</span>
 For shame, come down: he made thee Duke of York.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa078" id="lnum-caa078">♦</a>
 <span class="sd-cn">York.</span>
  ’Twas my inheritance, as the earldom was.</div>

<div class="dverse1"><span class="sd-cn">Exe.</span>
 Thy father was a traitor to the crown.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">War.</span>
 Exeter, thou art a traitor to the crown</div>
<div class="dverse">In following this usurping Henry.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Whom should he follow but his natural king?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa083" id="lnum-caa083">♦</a>
 <span class="sd-cn">War.</span>
  True, Clifford; and that’s Richard Duke of York.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 And shall I stand, and thou sit in my throne?</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">York.</span>
 It must and shall be so: content thyself.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Be Duke of Lancaster; let him be king.</div>

<div class="dverse1"><span class="sd-cn">West.</span>
 He is both king and Duke of Lancaster;</div>
<div class="dverse">And that the Lord of Westmoreland shall maintain.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And Warwick shall disprove it. You forget</div>
<div class="dverse"><span class="lnum">90</span>
 That we are those which chased you from the field</div>
<div class="dverse">And slew your fathers, and with colours spread</div>
<div class="dverse">March’d through the city to the palace gates.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa093" id="lnum-caa093">♦</a>
 <span class="sd-cn">North.</span>
  Yes, Warwick, I remember it to my grief;</div>
<div class="dverse">And, by his soul, thou and thy house shall rue it.</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">West.</span>
 Plantagenet, of thee and these thy sons,</div>
<div class="dverse">Thy kinsmen and thy friends, I’ll have more lives</div>
<div class="dverse">Than drops of blood were in my father’s veins.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Urge it no more; lest that, instead of words,</div>
<div class="dverse">I send thee, Warwick, such a messenger</div>
<div class="dverse"><span class="lnum">100</span>
 As shall revenge his death before I stir.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Poor Clifford! how I scorn his worthless threats!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Will you we show our title to the crown?</div>
<div class="dverse">If not, our swords shall plead it in the field.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 What title hast thou, traitor, to the crown?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa105" id="lnum-caa105">105</a>
 Thy father was, as thou art, Duke of York;</div>
<div class="dverse">Thy grandfather, Roger Mortimer, Earl of March:</div>
<div class="dverse">I am the son of Henry the Fifth,</div>
<div class="dverse">Who made the Dauphin and the French to stoop</div>
<div class="dverse">And seized upon their towns and provinces.</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">War.</span>
 Talk not of France, sith thou hast lost it all.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 The lord protector lost it, and not I:</div>
<div class="dverse">When I was crown’d I was but nine months old.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa113" id="lnum-caa113">♦</a>
 <span class="sd-cn">Rich.</span>
  You are old enough now, and yet, methinks, you lose.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa114" id="lnum-caa114">♦</a>
 Father, tear the crown from the usurper’s head.</div>

<div class="dverse1"><span class="lnum">115</span>
 <span class="sd-cn">Edw.</span>
 Sweet father, do so; set it on your head.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa116" id="lnum-caa116">♦</a>
 <span class="sd-cn">Mont.</span>
 Good brother, as thou lovest and honourest arms,</div>
<div class="dverse">Let’s fight it out and not stand cavilling thus.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Sound drums and trumpets, and the king will fly.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Sons, peace!</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">K. Hen.</span>
  Peace, thou! and give King Henry leave to speak.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Plantagenet shall speak first: hear him, lords;</div>
<div class="dverse">And be you silent and attentive too,</div>
<div class="dverse">For he that interrupts him shall not live.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Think’st thou that I will leave my kingly throne,</div>
<div class="dverse"><span class="lnum">125</span>
 Wherein my grandsire and my father sat?</div>
<div class="dverse">No: first shall war unpeople this my realm;</div>
<div class="dverse">Ay, and their colours, often borne in France,</div>
<div class="dverse">And now in England to our heart’s great sorrow,</div>
<div class="dverse">Shall be my winding-sheet. Why faint you, lords?</div>
<div class="dverse"><span class="lnum">130</span>
 My title’s good, and better far than his.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa131" id="lnum-caa131">♦</a>
 <span class="sd-cn">War.</span>
  Prove it, Henry, and thou shalt be king.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Henry the Fourth by conquest got the crown.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 ’Twas by rebellion against his king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa134" id="lnum-caa134">♦</a>
<span class="sd-cn">K. Hen.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 I know not what to say; my title’s weak.</div>
<div class="dverse"><span class="lnum">135</span>
 Tell me, may not a king adopt an heir?</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 What then?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa137" id="lnum-caa137">♦</a>
 <span class="sd-cn">K. Hen.</span>
  An if he may, then am I lawful king;</div>
<div class="dverse">For Richard, in the view of many lords,</div>
<div class="dverse">Resign’d the crown to Henry the Fourth,</div>
<div class="dverse"><span class="lnum">140</span>
 Whose heir my father was, and I am his.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 He rose against him, being his sovereign,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa142" id="lnum-caa142">♦</a>
 And made him to resign his crown perforce.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Suppose, my lords, he did it unconstrain’d,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa144" id="lnum-caa144">♦</a>
 Think you ’twere prejudicial to his crown?</div>

<div class="dverse1"><span class="lnum">145</span>
 <span class="sd-cn">Exe.</span>
  No; for he could not so resign his crown</div>
<div class="dverse">But that the next heir should succeed and reign.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Art thou against us, Duke of Exeter?</div>

<div class="dverse1"><span class="sd-cn">Exe.</span>
 His is the right, and therefore pardon me.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Why whisper you, my lords, and answer not?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa150" id="lnum-caa150">150</a>
 <span class="sd-cn">Exe.</span>
  My conscience tells me he is lawful king.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 <span class="sd-inline">[<i>Aside</i>]</span> All will revolt from me, and turn to him.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 Plantagenet, for all the claim thou lay’st,</div>
<div class="dverse">Think not that Henry shall be so deposed.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa154" id="lnum-caa154">♦</a>
 <span class="sd-cn">War.</span>
  Deposed he shall be, in despite of all.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa155" id="lnum-caa155">155</a>
 <span class="sd-cn">North.</span>
  Thou art deceived: ’tis not thy southern power,</div>
<div class="dverse">Of Essex, Norfolk, Suffolk, nor of Kent,</div>
<div class="dverse">Which makes thee thus presumptuous and proud,</div>
<div class="dverse">Can set the duke up in despite of me.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 King Henry, be thy title right or wrong,</div>
<div class="dverse"><span class="lnum">160</span>
 Lord Clifford vows to fight in thy defence:</div>
<div class="dverse">May that ground gape and swallow me alive,</div>
<div class="dverse">Where I shall kneel to him that slew my father!</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 O Clifford, how thy words revive my heart!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa164" id="lnum-caa164">♦</a>
 <span class="sd-cn">York.</span>
  Henry of Lancaster, resign thy crown.</div>
<div class="dverse"><span class="lnum">165</span>
 What mutter you, or what conspire you, lords?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Do right unto this princely Duke of York,</div>
<div class="dverse">Or I will fill the house with armed men,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa168" id="lnum-caa168">♦</a>
 And over the chair of state, where now he sits,</div>
<div class="dverse">Write up his title with usurping blood. <span class="sd-verseend">[<i>He stamps with his foot, and the Soldiers show themselves.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa170" id="lnum-caa170">170</a>
 <span class="sd-cn">K. Hen.</span>
  My Lord of Warwick, hear me but one word:</div>
<div class="dverse">Let me for this my life-time reign as king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa171" id="lnum-caa171">♦</a>
 <span class="sd-cn">York.</span>
  Confirm the crown to me and to mine heirs,</div>
<div class="dverse">And thou shalt reign in quiet while thou livest.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 I am content: Richard Plantagenet,</div>
<div class="dverse"><span class="lnum">175</span>
 Enjoy the kingdom after my decease.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 What wrong is this unto the prince your son!</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 What good is this to England and himself!</div>

<div class="dverse1"><span class="sd-cn">West.</span>
 Base, fearful and despairing Henry!</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 How hast thou injured both thyself and us!</div>

<div class="dverse1"><span class="lnum">180</span>
 <span class="sd-cn">West.</span>
  I cannot stay to hear these articles.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 Nor I.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Come, cousin, let us tell the queen these news.</div>

<div class="dverse1"><span class="sd-cn">West.</span>
 Farewell, faint-hearted and degenerate king,</div>
<div class="dverse">In whose cold blood no spark of honour bides.</div>

<div class="dverse1"><span class="lnum">185</span>
 <span class="sd-cn">North.</span>
  Be thou a prey unto the house of York,</div>
<div class="dverse">And die in bands for this unmanly deed!</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 In dreadful war mayst thou be overcome,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa188" id="lnum-caa188">♦</a>
 Or live in peace abandon’d and despised!
 <span class="sd-verseend">[<i>Exeunt North., Cliff., and West.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa189" id="lnum-caa189">♦</a>
 <span class="sd-cn">War.</span>
  Turn this way, Henry, and regard them not.</div>

<div class="dverse1"><span class="lnum">190</span>
 <span class="sd-cn">Exe.</span>
  They seek revenge and therefore will not yield.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Ah, Exeter!</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 <span class="i09"> </span> Why should you sigh, my lord?</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Not for myself, Lord Warwick, but my son,</div>
<div class="dverse">Whom I unnaturally shall disinherit.</div>
<div class="dverse">But be it as it may: I here entail</div>
<div class="dverse"><span class="lnum">195</span>
 The crown to thee and to thine heirs for ever;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa196" id="lnum-caa196">♦</a>
 Conditionally, that here thou take an oath</div>
<div class="dverse">To cease this civil war, and, whilst I live,</div>
<div class="dverse">To honour me as thy king and sovereign,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa199" id="lnum-caa199">♦</a>
 And neither by treason nor hostility</div>
<div class="dverse"><span class="lnum">200</span>
 To seek to put me down and reign thyself.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa201" id="lnum-caa201">♦</a>
 <span class="sd-cn">York.</span>
  This oath I willingly take and will perform.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Long live King Henry! Plantagenet, embrace him.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 And long live thou and these thy forward sons!</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Now York and Lancaster are reconciled.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa205" id="lnum-caa205">205</a>
 <span class="sd-cn">Exe.</span>
 Accursed be he that seeks to make them foes!
 <span class="sd-verseend">[<i>Sennet. Here they come down.</i></span></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Farewell, my gracious lord; I’ll to my castle.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And I’ll keep London with my soldiers.</div>

<div class="dverse1"><span class="sd-cn">Norf.</span>
 And I to Norfolk with my followers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa209" id="lnum-caa209">♦</a>
 <span class="sd-cn">Mont.</span>
 And I unto the sea from whence I came.
 <span class="sd-verseend">[<i>Exeunt York and his Sons, Warwick, Norfolk, Montague, their Soldiers, and Attendants.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa210" id="lnum-caa210">210</a>
 <span class="sd-cn">K. Hen.</span>
  And I, with grief and sorrow, to the court.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">M<span>ARGARET</span></span> <i>and the</i> <span class="smcaps">P<span>RINCE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">W<span>ALES</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa211" id="lnum-caa211">♦</a>
 <span class="sd-cn">Exe.</span>
  Here comes the queen, whose looks bewray her anger:</div>
<div class="dverse">I’ll steal away.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa212" id="lnum-caa212">♦</a>
<span class="sd-cn">K. Hen.</span>
 <span class="i04"> </span>
 Exeter, so will I.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Nay, go not from me; I will follow thee.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Be patient, gentle queen, and I will stay.</div>

<div class="dverse1"><span class="lnum">215</span>
 <span class="sd-cn">Q. Mar.</span>
  Who can be patient in such extremes?</div>
<div class="dverse">Ah, wretched man! would I had died a maid,</div>
<div class="dverse">And never seen thee, never borne thee son,</div>
<div class="dverse">Seeing thou hast proved so unnatural a father!</div>
<div class="dverse">Hath he deserved to lose his birthright thus?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa220" id="lnum-caa220">220</a>
 Hadst thou but loved him half so well as I,</div>
<div class="dverse">Or felt that pain which I did for him once,</div>
<div class="dverse">Or nourish’d him as I did with my blood,</div>
<div class="dverse">Thou wouldst have left thy dearest heart-blood there,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa224" id="lnum-caa224">♦</a>
 Rather than have made that savage duke thine heir</div>
<div class="dverse"><span class="lnum">225</span>
 And disinherited thine only son.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 Father, you cannot disinherit me:</div>
<div class="dverse">If you be king, why should not I succeed?</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Pardon me, Margaret; pardon me, sweet son:</div>
<div class="dverse">The Earl of Warwick and the duke enforced me.</div>

<div class="dverse1"><span class="lnum">230</span>
 <span class="sd-cn">Q. Mar.</span>
  Enforced thee! art thou king, and wilt be forced?</div>
<div class="dverse">I shame to hear thee speak. Ah, timorous wretch!</div>
<div class="dverse">Thou hast undone thyself, thy son and me;</div>
<div class="dverse">And given unto the house of York such head</div>
<div class="dverse">As thou shalt reign but by their sufferance.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa235" id="lnum-caa235">235</a>
 To entail him and his heirs unto the crown,</div>
<div class="dverse">What is it, but to make thy sepulchre</div>
<div class="dverse">And creep into it far before thy time?</div>
<div class="dverse">Warwick is chancellor and the lord of Calais;</div>
<div class="dverse">Stern Falconbridge commands the narrow seas;</div>
<div class="dverse"><span class="lnum">240</span>
 The duke is made protector of the realm;</div>
<div class="dverse">And yet shalt thou be safe? such safety finds</div>
<div class="dverse">The trembling lamb environed with wolves.</div>
<div class="dverse">Had I been there, which am a silly woman,</div>
<div class="dverse">The soldiers should have toss’d me on their pikes</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa245" id="lnum-caa245">245</a>
 Before I would have granted to that act.</div>
<div class="dverse">But thou preferr’st thy life before thine honour:</div>
<div class="dverse">And seeing thou dost, I here divorce myself</div>
<div class="dverse">Both from thy table, Henry, and thy bed,</div>
<div class="dverse">Until that act of parliament be repeal’d</div>
<div class="dverse"><span class="lnum">250</span>
 Whereby my son is disinherited.</div>
<div class="dverse">The northern lords that have forsworn thy colours</div>
<div class="dverse">Will follow mine, if once they see them spread;</div>
<div class="dverse">And spread they shall be, to thy foul disgrace</div>
<div class="dverse">And utter ruin of the house of York.</div>
<div class="dverse"><span class="lnum">255</span>
 Thus do I leave thee. Come, son, let’s away;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa256" id="lnum-caa256">♦</a>
 Our army is ready; come, we’ll after them.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Stay, gentle Margaret, and hear me speak.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Thou hast spoke too much already: get thee gone.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa259" id="lnum-caa259">♦</a>
 <span class="sd-cn">K. Hen.</span>
  Gentle son Edward, thou wilt stay with me?</div>

<div class="dverse1"><span class="lnum">260</span>
 <span class="sd-cn">Q. Mar.</span>
  Ay, to be murder’d by his enemies.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa261" id="lnum-caa261">♦</a>
 <span class="sd-cn">Prince.</span>
  When I return with victory from the field</div>
<div class="dverse">I’ll see your grace: till then I’ll follow her.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa263" id="lnum-caa263">♦</a>
 <span class="sd-cn">Q. Mar.</span>
 Come, son, away; we may not linger thus.
 <span class="sd-verseend">[<i>Exeunt Queen Margaret and the Prince.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa264" id="lnum-caa264">♦</a>
 <span class="sd-cn">K. Hen.</span>
  Poor queen! how love to me and to her son</div>
<div class="dverse"><span class="lnum">265</span>
 Hath made her break out into terms of rage!</div>
<div class="dverse">Revenged may she be on that hateful duke,</div>
<div class="dverse">Whose haughty spirit, winged with desire,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-caa268" id="lnum-caa268">♦</a>
 Will cost my crown, and like an empty eagle</div>
<div class="dverse">Tire on the flesh of me and of my son!</div>
<div class="dverse"><span class="lnum">270</span>
 The loss of those three lords torments my heart:</div>
<div class="dverse">I’ll write unto them and entreat them fair.</div>
<div class="dverse">Come, cousin, you shall be the messenger.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-caa273" id="lnum-caa273">♦</a>
 <span class="sd-cn">Exe.</span>
 And I, I hope, shall reconcile them all.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cab</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>Sandal Castle</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">R<span>ICHARD</span>,</span> <span class="smcaps">E<span>DWARD</span>,</span> <i>and</i> <span class="smcaps">M<span>ONTAGUE</span>.</span></div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab001" id="lnum-cab001">♦</a>
 <span class="sd-cn">Rich.</span>
  Brother, though I be youngest, give me leave.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 No, I can better play the orator.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 But I have reasons strong and forcible.</div>

<div class="sd-entry"><i>Enter the</i> <span class="smcaps">D<span>UKE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">Y<span>ORK</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab004" id="lnum-cab004">♦</a>
 <span class="sd-cn">York.</span>
  Why, how now, sons and brother! at a strife?</div>
<div class="dverse"><span class="lnum">5</span>
 What is your quarrel? how began it first?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab006" id="lnum-cab006">♦</a>
 <span class="sd-cn">Edw.</span>
  No quarrel, but a slight contention.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 About what?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 About that which concerns your grace and us;</div>
<div class="dverse">The crown of England, father, which is yours.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab010" id="lnum-cab010">10</a>
 <span class="sd-cn">York.</span>
  Mine, boy? not till King Henry be dead.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Your right depends not on his life or death.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Now you are heir, therefore enjoy it now:</div>
<div class="dverse">By giving the house of Lancaster leave to breathe,</div>
<div class="dverse">It will outrun you, father, in the end.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">York.</span>
  I took an oath that he should quietly reign.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 But for a kingdom any oath may be broken:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab017" id="lnum-cab017">♦</a>
 I would break a thousand oaths to reign one year.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 No; God forbid your grace should be forsworn.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 I shall be, if I claim by open war.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Rich.</span>
  I’ll prove the contrary, if you’ll hear me speak.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Thou canst not, son; it is impossible.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 An oath is of no moment, being not took</div>
<div class="dverse">Before a true and lawful magistrate,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab024" id="lnum-cab024">♦</a>
 That hath authority over him that swears:</div>
<div class="dverse"><span class="lnum">25</span>
 Henry had none, but did usurp the place;</div>
<div class="dverse">Then, seeing ’twas he that made you to depose,</div>
<div class="dverse">Your oath, my lord, is vain and frivolous.</div>
<div class="dverse">Therefore, to arms! And, father, do but think</div>
<div class="dverse">How sweet a thing it is to wear a crown;</div>
<div class="dverse"><span class="lnum">30</span>
 Within whose circuit is Elysium</div>
<div class="dverse">And all that poets feign of bliss and joy.</div>
<div class="dverse">Why do we linger thus? I cannot rest</div>
<div class="dverse">Until the white rose that I wear be dyed</div>
<div class="dverse">Even in the lukewarm blood of Henry’s heart.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">York.</span>
  Richard, enough; I will be king, or die.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab036" id="lnum-cab036">♦</a>
 Brother, thou shalt to London presently,</div>
<div class="dverse">And whet on Warwick to this enterprise.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab038" id="lnum-cab038">♦</a>
 Thou, Richard, shalt to the Duke of Norfolk,</div>
<div class="dverse">And tell him privily of our intent.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab040" id="lnum-cab040">40</a>
 You, Edward, shall unto my Lord Cobham,</div>
<div class="dverse">With whom the Kentishmen will willingly rise:</div>
<div class="dverse">In them I trust; for they are soldiers,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab043" id="lnum-cab043">♦</a>
 Witty, courteous, liberal, full of spirit.</div>
<div class="dverse">While you are thus employ’d, what resteth more,</div>
<div class="dverse"><span class="lnum">45</span>
 But that I seek occasion how to rise,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab046" id="lnum-cab046">♦</a>
 And yet the king not privy to my drift,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab047" id="lnum-cab047">♦</a>
 Nor any of the house of Lancaster?</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse">But, stay: what news? Why comest thou in such post?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab049" id="lnum-cab049">♦</a>
 <span class="sd-cn">Gabr.</span>
  The queen with all the northern earls and lords</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-cab050" id="lnum-cab050">50</a>
 Intend here to besiege you in your castle:</div>
<div class="dverse">She is hard by with twenty thousand men;</div>
<div class="dverse">And therefore fortify your hold, my lord.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab053" id="lnum-cab053">♦</a>
 <span class="sd-cn">York.</span>
  Ay, with my sword. What! think’st thou that we fear them?</div>
<div class="dverse">Edward and Richard, you shall stay with me;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab055" id="lnum-cab055">55</a>
 My brother Montague shall post to London:</div>
<div class="dverse">Let noble Warwick, Cobham, and the rest,</div>
<div class="dverse">Whom we have left protectors of the king,</div>
<div class="dverse">With powerful policy strengthen themselves,</div>
<div class="dverse">And trust not simple Henry nor his oaths.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab060" id="lnum-cab060">60</a>
 <span class="sd-cn">Mont.</span>
  Brother, I go; I’ll win them, fear it not:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab061" id="lnum-cab061">♦</a>
 And thus most humbly I do take my leave.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">S<span>IR</span></span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">M<span>ORTIMER</span></span> <i>and</i>
<span class="smcaps">S<span>IR</span></span> <span class="smcaps">H<span>UGH</span></span> <span class="smcaps">M<span>ORTIMER</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab062" id="lnum-cab062">♦</a>
 <span class="sd-cn">York.</span>
  Sir John and Sir Hugh Mortimer, mine uncles,</div>
<div class="dverse">You are come to Sandal in a happy hour;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab064" id="lnum-cab064">♦</a>
 The army of the queen mean to besiege us.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">Sir John.</span>
  She shall not need; we’ll meet her in the field.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 What, with five thousand men?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Ay, with five hundred, father, for a need:</div>
<div class="dverse">A woman’s general; what should we fear?
 <span class="sd-verseend">[<i>A march afar off.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cab069" id="lnum-cab069">♦</a>
 <span class="sd-cn">Edw.</span>
  I hear their drums: let’s set our men in order,</div>
<div class="dverse"><span class="lnum">70</span>
 And issue forth and bid them battle straight.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Five men to twenty! though the odds be great,</div>
<div class="dverse">I doubt not, uncle, of our victory.</div>
<div class="dverse">Many a battle have I won in France,</div>
<div class="dverse">When as the enemy hath been ten to one:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cab075" id="lnum-cab075">75</a>
 Why should I not now have the like success? <span class="sd-verseend">[<i>Alarum. Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cac</span>
<span class="smcaps">S<span>CENE</span></span> III. <i>Field of battle betwixt Sandal Castle and Wakefield</i>.</h4>

<div class="sd-schg"><i>Alarums. Enter</i> <span class="smcaps">R<span>UTLAND</span></span> <i>and his</i> Tutor.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cac001" id="lnum-cac001">♦</a>
 <span class="sd-cn">Rut.</span>
  Ah, whither shall I fly to ’scape their hands?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac002" id="lnum-cac002">♦</a>
 Ah, tutor, look where bloody Clifford comes!</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">C<span>LIFFORD</span></span> <i>and</i> Soldiers.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Chaplain, away! thy priesthood saves thy life.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac004" id="lnum-cac004">♦</a>
 As for the brat of this accursed duke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac005" id="lnum-cac005">5</a>
 Whose father slew my father, he shall die.</div>

<div class="dverse1"><span class="sd-cn">Tut.</span>
 And I, my lord, will bear him company.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cac007" id="lnum-cac007">♦</a>
 <span class="sd-cn">Clif.</span>
  Soldiers, away with him!</div>

<div class="dverse1"><span class="sd-cn">Tut.</span>
 Ah, Clifford, murder not this innocent child,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac009" id="lnum-cac009">♦</a>
 Lest thou be hated both of God and man! <span class="sd-verseend">[<i>Exit, dragged off by Soldiers.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cac010" id="lnum-cac010">10</a>
 <span class="sd-cn">Clif.</span>
  How now! is he dead already? or is it fear</div>
<div class="dverse">That makes him close his eyes? I’ll open them.</div>

<div class="dverse1"><span class="sd-cn">Rut.</span>
 So looks the pent-up lion o’er the wretch</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac013" id="lnum-cac013">♦</a>
 That trembles under his devouring paws;</div>
<div class="dverse">And so he walks, insulting o’er his prey,</div>
<div class="dverse"><span class="lnum">15</span>
 And so he comes, to rend his limbs asunder.</div>
<div class="dverse">Ah, gentle Clifford, kill me with thy sword,</div>
<div class="dverse">And not with such a cruel threatening look.</div>
<div class="dverse">Sweet Clifford, hear me speak before I die.</div>
<div class="dverse">I am too mean a subject for thy wrath:</div>
<div class="dverse"><span class="lnum">20</span>
 Be thou revenged on men, and let me live.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cac021" id="lnum-cac021">♦</a>
 <span class="sd-cn">Clif.</span>
  In vain thou speak’st, poor boy; my father’s blood</div>
<div class="dverse">Hath stopp’d the passage where thy words should enter.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cac023" id="lnum-cac023">♦</a>
 <span class="sd-cn">Rut.</span>
  Then let my father’s blood open it again:</div>
<div class="dverse">He is a man, and, Clifford, cope with him.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Clif.</span>
  Had I thy brethren here, their lives and thine</div>
<div class="dverse">Were not revenge sufficient for me;</div>
<div class="dverse">No, if I digg’d up thy forefathers’ graves</div>
<div class="dverse">And hung their rotten coffins up in chains,</div>
<div class="dverse">It could not slake mine ire, nor ease my heart.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac030" id="lnum-cac030">30</a>
 The sight of any of the house of York</div>
<div class="dverse">Is as a fury to torment my soul;</div>
<div class="dverse">And till I root out their accursed line</div>
<div class="dverse">And leave not one alive, I live in hell.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac034" id="lnum-cac034">♦</a>
 Therefore—
 <span class="sd-verseend">[<i>Lifting his hand.</i></span></div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">Rut.</span>
 <span class="i02"> </span> O, let me pray before I take my death!</div>
<div class="dverse">To thee I pray; sweet Clifford, pity me!</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Such pity as my rapier’s point affords.</div>

<div class="dverse1"><span class="sd-cn">Rut.</span>
 I never did thee harm: why wilt thou slay me?</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Thy father hath.</div>

<div class="dverse1"><span class="sd-cn">Rut.</span>
 <span class="i10"> </span> But ’twas ere I was born.</div>
<div class="dverse"><span class="lnum">40</span>
 Thou hast one son; for his sake pity me,</div>
<div class="dverse">Lest in revenge thereof, sith God is just,</div>
<div class="dverse">He be as miserably slain as I.</div>
<div class="dverse">Ah, let me live in prison all my days;</div>
<div class="dverse">And when I give occasion of offence,</div>
<div class="dverse"><span class="lnum">45</span>
 Then let me die, for now thou hast no cause.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 No cause!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac047" id="lnum-cac047">♦</a>
 Thy father slew my father; therefore, die. <span class="sd-verseend">[<i>Stabs him.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cac048" id="lnum-cac048">♦</a>
 <span class="sd-cn">Rut.</span>
 Di faciant laudis summa sit ista tuæ! <span class="sd-verseend">[<i>Dies.</i></span></div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Plantagenet! I come, Plantagenet!</div>
<div class="dverse"><span class="lnum">50</span>
 And this thy son’s blood cleaving to my blade</div>
<div class="dverse">Shall rust upon my weapon, till thy blood,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cac052" id="lnum-cac052">♦</a>
 Congeal’d with this, do make me wipe off both. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cad</span>
<span class="smcaps">S<span>CENE</span></span> IV. <i>Another part of the field</i>.</h4>

<div class="sd-schg"><i>Alarum. Enter</i> <span class="smcaps">R<span>ICHARD</span>,</span> Duke of York.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad001" id="lnum-cad001">♦</a>
 <span class="sd-cn">York.</span>
  The army of the queen hath got the field:</div>
<div class="dverse">My uncles both are slain in rescuing me;</div>
<div class="dverse">And all my followers to the eager foe</div>
<div class="dverse">Turn back and fly, like ships before the wind</div>
<div class="dverse"><span class="lnum">5</span>
 Or lambs pursued by hunger-starved wolves.</div>
<div class="dverse">My sons, God knows what hath bechanced them:</div>
<div class="dverse">But this I know, they have demean’d themselves</div>
<div class="dverse">Like men born to renown by life or death.</div>
<div class="dverse">Three times did Richard make a lane to me,</div>
<div class="dverse"><span class="lnum">10</span>
 And thrice cried ‘Courage, father! fight it out!’</div>
<div class="dverse">And full as oft came Edward to my side,</div>
<div class="dverse">With purple falchion, painted to the hilt</div>
<div class="dverse">In blood of those that had encounter’d him:</div>
<div class="dverse">And when the hardiest warriors did retire,</div>
<div class="dverse"><span class="lnum">15</span>
 Richard cried, ‘Charge! and give no foot of ground!’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad016" id="lnum-cad016">♦</a>
 And cried, ‘A crown, or else a glorious tomb!</div>
<div class="dverse">A sceptre, or an earthly sepulchre!’</div>
<div class="dverse">With this, we charged again: but, out, alas!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad019" id="lnum-cad019">♦</a>
 We bodged again; as I have seen a swan</div>
<div class="dverse"><span class="lnum">20</span>
 With bootless labour swim against the tide</div>
<div class="dverse">And spend her strength with over-matching waves. <span class="sd-verseend">[<i>A short alarum within.</i></span></div>
<div class="dverse">Ah, hark! the fatal followers do pursue;</div>
<div class="dverse">And I am faint, and cannot fly their fury:</div>
<div class="dverse">And were I strong, I would not shun their fury:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad025" id="lnum-cad025">25</a>
 The sands are number’d that make up my life;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad026" id="lnum-cad026">♦</a>
 Here must I stay, and here my life must end.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">M<span>ARGARET</span>,</span> <span class="smcaps">C<span>LIFFORD</span>,</span> <span class="smcaps">N<span>ORTHUMBERLAND</span>,</span> <i>the</i> young Prince,
<i>and</i> Soldiers.</div>

<div class="dverse">Come, bloody Clifford, rough Northumberland,</div>
<div class="dverse">I dare your quenchless fury to more rage:</div>
<div class="dverse">I am your butt, and I abide your shot.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">North.</span>
  Yield to our mercy, proud Plantagenet.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Ay, to such mercy as his ruthless arm,</div>
<div class="dverse">With downright payment, show’d unto my father.</div>
<div class="dverse">Now Phaëthon hath tumbled from his car,</div>
<div class="dverse">And made an evening at the noontide prick.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad035" id="lnum-cad035">35</a>
 <span class="sd-cn">York.</span>
  My ashes, as the phœnix, may bring forth</div>
<div class="dverse">A bird that will revenge upon you all:</div>
<div class="dverse">And in that hope I throw mine eyes to heaven,</div>
<div class="dverse">Scorning whate’er you can afflict me with.</div>
<div class="dverse">Why come you not? what! multitudes, and fear?</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Clif.</span>
  So cowards fight when they can fly no further;</div>
<div class="dverse">So doves do peck the falcon’s piercing talons;</div>
<div class="dverse">So desperate thieves, all hopeless of their lives,</div>
<div class="dverse">Breathe out invectives ’gainst the officers.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 O Clifford, but bethink thee once again,</div>
<div class="dverse"><span class="lnum">45</span>
 And in thy thought o’er-run my former time;</div>
<div class="dverse">And, if thou canst for blushing, view this face,</div>
<div class="dverse">And bite thy tongue, that slanders him with cowardice</div>
<div class="dverse">Whose frown hath made thee faint and fly ere this!</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I will not bandy with thee word for word,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad050" id="lnum-cad050">50</a>
 But buckle with thee blows, twice two for one.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Hold, valiant Clifford! for a thousand causes</div>
<div class="dverse">I would prolong awhile the traitor’s life.</div>
<div class="dverse">Wrath makes him deaf: speak thou, Northumberland.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 Hold, Clifford! do not honour him so much</div>
<div class="dverse"><span class="lnum">55</span>
 To prick thy finger, though to wound his heart:</div>
<div class="dverse">What valour were it, when a cur doth grin,</div>
<div class="dverse">For one to thrust his hand between his teeth,</div>
<div class="dverse">When he might spurn him with his foot away?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad059" id="lnum-cad059">♦</a>
 It is war’s prize to take all vantages;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad060" id="lnum-cad060">60</a>
 And ten to one is no impeach of valour. <span class="sd-verseend">[<i>They lay hands on York, who struggles.</i></span></div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
  Ay, ay, so strives the woodcock with the gin.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad062" id="lnum-cad062">♦</a>
 <span class="sd-cn">North.</span>
  So doth the cony struggle in the net.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 So triumph thieves upon their conquer’d booty;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad064" id="lnum-cad064">♦</a>
 So true men yield, with robbers so o’er-match’d.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">North.</span>
  What would your grace have done unto him now?</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Brave warriors, Clifford and Northumberland,</div>
<div class="dverse">Come, make him stand upon this molehill here,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad068" id="lnum-cad068">♦</a>
 That raught at mountains with outstretched arms,</div>
<div class="dverse">Yet parted but the shadow with his hand.</div>
<div class="dverse"><span class="lnum">70</span>
 What! was it you that would be England’s king?</div>
<div class="dverse">Was’t you that revell’d in our parliament,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad072" id="lnum-cad072">♦</a>
 And made a preachment of your high descent?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad073" id="lnum-cad073">♦</a>
 Where are your mess of sons to back you now?</div>
<div class="dverse">The wanton Edward, and the lusty George?</div>
<div class="dverse"><span class="lnum">75</span>
 And where’s that valiant crook-back prodigy,</div>
<div class="dverse">Dicky your boy, that with his grumbling voice</div>
<div class="dverse">Was wont to cheer his dad in mutinies?</div>
<div class="dverse">Or, with the rest, where is your darling Rutland?</div>
<div class="dverse">Look, York: I stain’d this napkin with the blood</div>
<div class="dverse"><span class="lnum">80</span>
 That valiant Clifford, with his rapier’s point,</div>
<div class="dverse">Made issue from the bosom of the boy;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad082" id="lnum-cad082">♦</a>
 And if thine eyes can water for his death,</div>
<div class="dverse">I give thee this to dry thy cheeks withal.</div>
<div class="dverse">Alas, poor York! but that I hate thee deadly,</div>
<div class="dverse"><span class="lnum">85</span>
 I should lament thy miserable state.</div>
<div class="dverse">I prithee, grieve, to make me merry, York.</div>
<div class="dverse">What, hath thy fiery heart so parch’d thine entrails</div>

<div class="dverse">That not a tear can fall for Rutland’s death?</div>
<div class="dverse">Why art thou patient, man? thou shouldst be mad;</div>
<div class="dverse"><span class="lnum">90</span>
 And I, to make thee mad, do mock thee thus.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad091" id="lnum-cad091">♦</a>
 Stamp, rave, and fret, that I may sing and dance.</div>
<div class="dverse">Thou wouldst be fee’d, I see, to make me sport:</div>
<div class="dverse">York cannot speak, unless he wear a crown.</div>
<div class="dverse">A crown for York! and, lords, bow low to him:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad095" id="lnum-cad095">95</a>
 Hold you his hands, whilst I do set it on. <span class="sd-verseend">[<i>Putting a paper crown on his head.</i></span></div>
<div class="dverse">Ay, marry, sir, now looks he like a king!</div>
<div class="dverse">Ay, this is he that took King Henry’s chair;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad098" id="lnum-cad098">♦</a>
 And this is he was his adopted heir.</div>
<div class="dverse">But how is it that great Plantagenet</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad100" id="lnum-cad100">100</a>
 Is crown’d so soon, and broke his solemn oath?</div>
<div class="dverse">As I bethink me, you should not be king</div>
<div class="dverse">Till our King Henry had shook hands with death.</div>
<div class="dverse">And will you pale your head in Henry’s glory,</div>
<div class="dverse">And rob his temples of the diadem,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad105" id="lnum-cad105">105</a>
 Now in his life, against your holy oath?</div>
<div class="dverse">O, ’tis a fault too too unpardonable!</div>
<div class="dverse">Off with the crown; and, with the crown, his head;</div>
<div class="dverse">And, whilst we breathe, take time to do him dead.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad109" id="lnum-cad109">♦</a>
 <span class="sd-cn">Clif.</span>
  That is my office, for my father’s sake.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad110" id="lnum-cad110">110</a>
 <span class="sd-cn">Q. Mar.</span>
  Nay, stay; let’s hear the orisons he makes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad111" id="lnum-cad111">♦</a>
 <span class="sd-cn">York.</span>
  She-wolf of France, but worse than wolves of France,</div>
<div class="dverse">Whose tongue more poisons than the adder’s tooth!</div>
<div class="dverse">How ill-beseeming is it in thy sex</div>
<div class="dverse">To triumph, like an Amazonian trull,</div>
<div class="dverse"><span class="lnum">115</span>
 Upon their woes whom fortune captivates!</div>
<div class="dverse">But that thy face is, visard-like, unchanging,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad117" id="lnum-cad117">♦</a>
 Made impudent with use of evil deeds,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad118" id="lnum-cad118">♦</a>
 I would assay, proud queen, to make thee blush.</div>
<div class="dverse">To tell thee whence thou camest, of whom derived,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad120" id="lnum-cad120">120</a>
 Were shame enough to shame thee, wert thou not shameless.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad121" id="lnum-cad121">♦</a>
 Thy father bears the type of King of Naples,</div>
<div class="dverse">Of both the Sicils and Jerusalem,</div>
<div class="dverse">Yet not so wealthy as an English yeoman.</div>
<div class="dverse">Hath that poor monarch taught thee to insult?</div>
<div class="dverse"><span class="lnum">125</span>
 It needs not, nor it boots thee not, proud queen,</div>
<div class="dverse">Unless the adage must be verified,</div>
<div class="dverse">That beggars mounted run their horse to death.</div>
<div class="dverse">’Tis beauty that doth oft make women proud;</div>
<div class="dverse">But, God he knows, thy share thereof is small:</div>
<div class="dverse"><span class="lnum">130</span>
 ’Tis virtue that doth make them most admired;</div>
<div class="dverse">The contrary doth make thee wonder’d at:</div>
<div class="dverse">’Tis government that makes them seem divine;</div>
<div class="dverse">The want thereof makes thee abominable:</div>
<div class="dverse">Thou art as opposite to every good</div>
<div class="dverse"><span class="lnum">135</span>
 As the Antipodes are unto us,</div>
<div class="dverse">Or as the south to the septentrion.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad137" id="lnum-cad137">♦</a>
 O tiger’s heart wrapp’d in a woman’s hide!</div>
<div class="dverse">How couldst thou drain the life-blood of the child,</div>
<div class="dverse">To bid the father wipe his eyes withal,</div>
<div class="dverse"><span class="lnum">140</span>
 And yet be seen to bear a woman’s face?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad141" id="lnum-cad141">♦</a>
 Women are soft, mild, pitiful and flexible;</div>
<div class="dverse">Thou stern, obdurate, flinty, rough, remorseless.</div>
<div class="dverse">Bid’st thou me rage? why, now thou hast thy wish:</div>
<div class="dverse">Wouldst have me weep? why, now thou hast thy will:</div>
<div class="dverse"><span class="lnum">145</span>
 For raging wind blows up incessant showers,</div>
<div class="dverse">And when the rage allays, the rain begins.</div>
<div class="dverse">These tears are my sweet Rutland’s obsequies:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad148" id="lnum-cad148">♦</a>
 And every drop cries vengeance for his death,</div>
<div class="dverse">’Gainst thee, fell Clifford, and thee, false Frenchwoman.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad150" id="lnum-cad150">150</a>
 <span class="sd-cn">North.</span>
  Beshrew me, but his passion moves me so</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad151" id="lnum-cad151">♦</a>
 That hardly can I check my eyes from tears.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad152" id="lnum-cad152">♦</a>
 <span class="sd-cn">York.</span>
  That face of his the hungry cannibals</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad153" id="lnum-cad153">♦</a>
 Would not have touch’d, would not have stain’d with blood:</div>
<div class="dverse">But you are more inhuman, more inexorable,</div>
<div class="dverse"><span class="lnum">155</span>
 O, ten times more, than tigers of Hyrcania.</div>
<div class="dverse">See, ruthless queen, a hapless father’s tears:</div>
<div class="dverse">This cloth thou dip’dst in blood of my sweet boy,</div>
<div class="dverse">And I with tears do wash the blood away.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad159" id="lnum-cad159">♦</a>
 Keep thou the napkin, and go boast of this:</div>
<div class="dverse"><span class="lnum">160</span>
 And if thou tell’st the heavy story right,</div>
<div class="dverse">Upon my soul, the hearers will shed tears;</div>
<div class="dverse">Yea even my foes will shed fast-falling tears,</div>
<div class="dverse">And say ‘Alas, it was a piteous deed!’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad164" id="lnum-cad164">♦</a>
 There, take the crown, and, with the crown, my curse;</div>
<div class="dverse"><span class="lnum">165</span>
 And in thy need such comfort come to thee</div>
<div class="dverse">As now I reap at thy too cruel hand!</div>
<div class="dverse">Hard-hearted Clifford, take me from the world:</div>
<div class="dverse">My soul to heaven, my blood upon your heads!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad169" id="lnum-cad169">♦</a>
 <span class="sd-cn">North.</span>
  Had he been slaughter-man to all my kin,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad170" id="lnum-cad170">170</a>
 I should not for my life but weep with him,</div>
<div class="dverse">To see how inly sorrow gripes his soul.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad172" id="lnum-cad172">♦</a>
 <span class="sd-cn">Q. Mar.</span>
  What, weeping-ripe, my Lord Northumberland?</div>
<div class="dverse">Think but upon the wrong he did us all,</div>
<div class="dverse">And that will quickly dry thy melting tears.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad175" id="lnum-cad175">175</a>
 <span class="sd-cn">Clif.</span>
 Here’s for my oath, here’s for my father’s death. <span class="sd-verseend">[<i>Stabbing him.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cad176" id="lnum-cad176">♦</a>
 <span class="sd-cn">Q. Mar.</span>
 And here’s to right our gentle-hearted king. <span class="sd-verseend">[<i>Stabbing him.</i></span></div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Open Thy gate of mercy, gracious God!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad178" id="lnum-cad178">♦</a>
 My soul flies through these wounds to seek out Thee.
 <span class="sd-verseend">[<i>Dies.</i></span></div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Off with his head, and set it on York gates;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cad180" id="lnum-cad180">180</a>
 So York may overlook the town of York.
 <span class="sd-verseend">[<i>Flourish. Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT II.</h3>

<h4 class="h4main"><span class="dnavigate">cba</span>
<span class="smcaps">S<span>CENE</span></span> I.
<i>A plain near Mortimer’s Cross in Herefordshire</i>.</h4>

<div class="sd-schg"><i>A march. Enter</i> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">R<span>ICHARD</span>,</span> <i>and their
power</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba001" id="lnum-cba001">♦</a>
 <span class="sd-cn">Edw.</span>
  I wonder how our princely father ’scaped,</div>
<div class="dverse">Or whether he be ’scaped away or no</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba003" id="lnum-cba003">♦</a>
 From Clifford’s and Northumberland’s pursuit:</div>
<div class="dverse">Had he been ta’en, we should have heard the news;</div>
<div class="dverse"><span class="lnum">5</span>
 Had he been slain, we should have heard the news;</div>
<div class="dverse">Or had he ’scaped, methinks we should have heard</div>
<div class="dverse">The happy tidings of his good escape.</div>
<div class="dverse">How fares my brother? why is he so sad?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 I cannot joy, until I be resolved</div>
<div class="dverse"><span class="lnum">10</span>
 Where our right valiant father is become.</div>
<div class="dverse">I saw him in the battle range about;</div>
<div class="dverse">And watch’d him how he singled Clifford forth.</div>
<div class="dverse">Methought he bore him in the thickest troop</div>
<div class="dverse">As doth a lion in a herd of neat;</div>
<div class="dverse"><span class="lnum">15</span>
 Or as a bear, encompass’d round with dogs,</div>
<div class="dverse">Who having pinch’d a few and made them cry,</div>
<div class="dverse">The rest stand all aloof, and bark at him.</div>
<div class="dverse">So fared our father with his enemies;</div>
<div class="dverse">So fled his enemies my warlike father:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba020" id="lnum-cba020">20</a>
 Methinks, ’tis prize enough to be his son.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba021" id="lnum-cba021">♦</a>
 See how the morning opes her golden gates,</div>
<div class="dverse">And takes her farewell of the glorious sun!</div>
<div class="dverse">How well resembles it the prime of youth,</div>
<div class="dverse">Trimm’d like a younker prancing to his love!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba025" id="lnum-cba025">25</a>
 <span class="sd-cn">Edw.</span>
  Dazzle mine eyes, or do I see three suns?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Three glorious suns, each one a perfect sun;</div>
<div class="dverse">Not separated with the racking clouds,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba028" id="lnum-cba028">♦</a>
 But sever’d in a pale clear-shining sky.</div>
<div class="dverse">See, see! they join, embrace, and seem to kiss,</div>
<div class="dverse"><span class="lnum">30</span>
 As if they vow’d some league inviolable:</div>
<div class="dverse">Now are they but one lamp, one light, one sun.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba032" id="lnum-cba032">♦</a>
 In this the heaven figures some event.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba033" id="lnum-cba033">♦</a>
 <span class="sd-cn">Edw.</span>
  ’Tis wondrous strange, the like yet never heard of.</div>
<div class="dverse">I think it cites us, brother, to the field,</div>
<div class="dverse"><span class="lnum">35</span>
 That we, the sons of brave Plantagenet,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba036" id="lnum-cba036">♦</a>
 Each one already blazing by our meeds,</div>
<div class="dverse">Should notwithstanding join our lights together</div>
<div class="dverse">And over-shine the earth as this the world.</div>
<div class="dverse">Whate’er it bodes, henceforward will I bear</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba040" id="lnum-cba040">40</a>
 Upon my target three fair-shining suns.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba041" id="lnum-cba041">♦</a>
 <span class="sd-cn">Rich.</span>
  Nay, bear three daughters: by your leave I speak it.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba042" id="lnum-cba042">♦</a>
 You love the breeder better than the male.</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse">But what art thou, whose heavy looks foretell</div>
<div class="dverse">Some dreadful story hanging on thy tongue?</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Mess.</span>
  Ah, one that was a woful looker-on</div>
<div class="dverse">When as the noble Duke of York was slain,</div>
<div class="dverse">Your princely father and my loving lord!</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 O, speak no more, for I have heard too much.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Say how he died, for I will hear it all.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Mess.</span>
  Environed he was with many foes,</div>
<div class="dverse">And stood against them, as the hope of Troy</div>
<div class="dverse">Against the Greeks that would have enter’d Troy.</div>
<div class="dverse">But Hercules himself must yield to odds;</div>
<div class="dverse">And many strokes, though with a little axe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba055" id="lnum-cba055">55</a>
 Hew down and fell the hardest-timber’d oak.</div>
<div class="dverse">By many hands your father was subdued;</div>
<div class="dverse">But only slaughter’d by the ireful arm</div>
<div class="dverse">Of unrelenting Clifford and the queen,</div>
<div class="dverse">Who crown’d the gracious duke in high despite,</div>
<div class="dverse"><span class="lnum">60</span>
 Laugh’d in his face; and when with grief he wept,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba061" id="lnum-cba061">♦</a>
 The ruthless queen gave him to dry his cheeks</div>
<div class="dverse">A napkin steeped in the harmless blood</div>
<div class="dverse">Of sweet young Rutland, by rough Clifford slain:</div>
<div class="dverse">And after many scorns, many foul taunts,</div>
<div class="dverse"><span class="lnum">65</span>
 They took his head, and on the gates of York</div>
<div class="dverse">They set the same; and there it doth remain,</div>
<div class="dverse">The saddest spectacle that e’er I view’d.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Sweet Duke of York, our prop to lean upon,</div>
<div class="dverse">Now thou art gone, we have no staff, no stay.</div>
<div class="dverse"><span class="lnum">70</span>
 O Clifford, boisterous Clifford! thou hast slain</div>
<div class="dverse">The flower of Europe for his chivalry;</div>
<div class="dverse">And treacherously hast thou vanquish’d him,</div>
<div class="dverse">For hand to hand he would have vanquish’d thee.</div>
<div class="dverse">Now my soul’s palace is become a prison:</div>
<div class="dverse"><span class="lnum">75</span>
 Ah, would she break from hence, that this my body</div>
<div class="dverse">Might in the ground be closed up in rest!</div>
<div class="dverse">For never henceforth shall I joy again,</div>
<div class="dverse">Never, O never, shall I see more joy!</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 I cannot weep; for all my body’s moisture</div>
<div class="dverse"><span class="lnum">80</span>
 Scarce serves to quench my furnace-burning heart:</div>
<div class="dverse">Nor can my tongue unload my heart’s great burthen;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba082" id="lnum-cba082">♦</a>
 For selfsame wind that I should speak withal</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba083" id="lnum-cba083">♦</a>
 Is kindling coals that fires all my breast,</div>
<div class="dverse">And burns me up with flames that tears would quench.</div>
<div class="dverse"><span class="lnum">85</span>
 To weep is to make less the depth of grief:</div>
<div class="dverse">Tears then for babes; blows and revenge for me!</div>
<div class="dverse">Richard, I bear thy name; I’ll venge thy death,</div>
<div class="dverse">Or die renowned by attempting it.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 His name that valiant duke hath left with thee;</div>
<div class="dverse"><span class="lnum">90</span>
 His dukedom and his chair with me is left.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Nay, if thou be that princely eagle’s bird,</div>
<div class="dverse">Show thy descent by gazing ’gainst the sun:</div>
<div class="dverse">For chair and dukedom, throne and kingdom say;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba094" id="lnum-cba094">♦</a>
 Either that is thine, or else thou wert not his.</div>

<div class="sd-entry"><i>March. Enter</i> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">M<span>ARQUESS</span></span> <span class="smmaj">OF</span> <span class="smcaps">M<span>ONTAGUE</span>,</span> <i>and their army</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba095" id="lnum-cba095">95</a>
 <span class="sd-cn">War.</span>
  How now, fair lords! What fare? what news abroad?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba096" id="lnum-cba096">♦</a>
 <span class="sd-cn">Rich.</span>
  Great Lord of Warwick, if we should recount</div>
<div class="dverse">Our baleful news, and at each word’s deliverance</div>
<div class="dverse">Stab poniards in our flesh till all were told,</div>
<div class="dverse">The words would add more anguish than the wounds.</div>
<div class="dverse"><span class="lnum">100</span>
 O valiant lord, the Duke of York is slain!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba101" id="lnum-cba101">♦</a>
 <span class="sd-cn">Edw.</span>
  O Warwick, Warwick! that Plantagenet,</div>
<div class="dverse">Which held thee dearly as his soul’s redemption,</div>
<div class="dverse">Is by the stern Lord Clifford done to death.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Ten days ago I drown’d these news in tears;</div>
<div class="dverse"><span class="lnum">105</span>
 And now, to add more measure to your woes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba106" id="lnum-cba106">♦</a>
 I come to tell you things sith then befall’n.</div>
<div class="dverse">After the bloody fray at Wakefield fought,</div>
<div class="dverse">Where your brave father breathed his latest gasp,</div>
<div class="dverse">Tidings, as swiftly as the posts could run,</div>
<div class="dverse"><span class="lnum">110</span>
 Were brought me of your loss and his depart.</div>
<div class="dverse">I, then in London, keeper of the king,</div>
<div class="dverse">Muster’d my soldiers, gather’d flocks of friends,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba113" id="lnum-cba113">♦</a>
 And very well appointed, as I thought,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba114" id="lnum-cba114">♦</a>
 March’d toward Saint Alban’s to intercept the queen,</div>
<div class="dverse"><span class="lnum">115</span>
 Bearing the king in my behalf along;</div>
<div class="dverse">For by my scouts I was advertised</div>
<div class="dverse">That she was coming with a full intent</div>
<div class="dverse">To dash our late decree in parliament</div>
<div class="dverse">Touching King Henry’s oath and your succession.</div>
<div class="dverse"><span class="lnum">120</span>
 Short tale to make, we at Saint Alban’s met,</div>
<div class="dverse">Our battles join’d, and both sides fiercely fought:</div>
<div class="dverse">But whether ’twas the coldness of the king,</div>
<div class="dverse">Who look’d full gently on his warlike queen,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba124" id="lnum-cba124">♦</a>
 That robb’d my soldiers of their heated spleen;</div>
<div class="dverse"><span class="lnum">125</span>
 Or whether ’twas report of her success;</div>
<div class="dverse">Or more than common fear of Clifford’s rigour,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba127" id="lnum-cba127">♦</a>
 Who thunders to his captives blood and death,</div>
<div class="dverse">I cannot judge: but, to conclude with truth,</div>
<div class="dverse">Their weapons like to lightning came and went;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba130" id="lnum-cba130">130</a>
 Our soldiers’, like the night-owl’s lazy flight,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba131" id="lnum-cba131">♦</a>
 Or like an idle thresher with a flail,</div>
<div class="dverse">Fell gently down, as if they struck their friends.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba133" id="lnum-cba133">♦</a>
 I cheer’d them up with justice of our cause,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba134" id="lnum-cba134">♦</a>
 With promise of high pay and great rewards:</div>
<div class="dverse"><span class="lnum">135</span>
 But all in vain; they had no heart to fight,</div>
<div class="dverse">And we in them no hope to win the day;</div>
<div class="dverse">So that we fled; the king unto the queen;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba138" id="lnum-cba138">♦</a>
 Lord George your brother, Norfolk and myself,</div>
<div class="dverse">In haste, post-haste, are come to join with you;</div>
<div class="dverse"><span class="lnum">140</span>
 For in the marches here we heard you were,</div>
<div class="dverse">Making another head to fight again.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Where is the Duke of Norfolk, gentle Warwick?</div>
<div class="dverse">And when came George from Burgundy to England?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba144" id="lnum-cba144">♦</a>
 <span class="sd-cn">War.</span>
  Some six miles off the duke is with the soldiers;</div>
<div class="dverse"><span class="lnum">145</span>
 And for your brother, he was lately sent</div>
<div class="dverse">From your kind aunt, Duchess of Burgundy,</div>
<div class="dverse">With aid of soldiers to this needful war.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 ’Twas odds, belike, when valiant Warwick fled:</div>
<div class="dverse">Oft have I heard his praises in pursuit,</div>
<div class="dverse"><span class="lnum">150</span>
 But ne’er till now his scandal of retire.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Nor now my scandal, Richard, dost thou hear;</div>
<div class="dverse">For thou shalt know this strong right hand of mine</div>
<div class="dverse">Can pluck the diadem from faint Henry’s head,</div>
<div class="dverse">And wring the awful sceptre from his fist,</div>
<div class="dverse"><span class="lnum">155</span>
 Were he as famous and as bold in war</div>
<div class="dverse">As he is famed for mildness, peace, and prayer.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 I know it well, Lord Warwick; blame me not:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba158" id="lnum-cba158">♦</a>
 ’Tis love I bear thy glories makes me speak.</div>
<div class="dverse">But in this troublous time what’s to be done?</div>
<div class="dverse"><span class="lnum">160</span>
 Shall we go throw away our coats of steel,</div>
<div class="dverse">And wrap our bodies in black mourning gowns,</div>
<div class="dverse">Numbering our Ave-Maries with our beads?</div>
<div class="dverse">Or shall we on the helmets of our foes</div>
<div class="dverse">Tell our devotion with revengeful arms?</div>
<div class="dverse"><span class="lnum">165</span>
 If for the last, say ay, and to it, lords.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Why, therefore Warwick came to seek you out;</div>
<div class="dverse">And therefore comes my brother Montague.</div>
<div class="dverse">Attend me, lords. The proud insulting queen,</div>
<div class="dverse">With Clifford and the haught Northumberland,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba170" id="lnum-cba170">170</a>
 And of their feather many moe proud birds,</div>
<div class="dverse">Have wrought the easy-melting king like wax.</div>
<div class="dverse">He swore consent to your succession,</div>
<div class="dverse">His oath enrolled in the parliament;</div>
<div class="dverse">And now to London all the crew are gone,</div>
<div class="dverse"><span class="lnum">175</span>
 To frustrate both his oath and what beside</div>
<div class="dverse">May make against the house of Lancaster.</div>
<div class="dverse">Their power, I think, is thirty thousand strong:</div>
<div class="dverse">Now, if the help of Norfolk and myself,</div>
<div class="dverse">With all the friends that thou, brave Earl of March,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba180" id="lnum-cba180">180</a>
 Amongst the loving Welshmen canst procure,</div>
<div class="dverse">Will but amount to five and twenty thousand,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba182" id="lnum-cba182">♦</a>
 Why, Via! to London will we march amain,</div>
<div class="dverse">And once again bestride our foaming steeds,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba184" id="lnum-cba184">♦</a>
 And once again cry ‘Charge upon our foes!’</div>
<div class="dverse"><span class="lnum">185</span>
 But never once again turn back and fly.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Ay, now methinks I hear great Warwick speak:</div>
<div class="dverse">Ne’er may he live to see a sunshine day,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba188" id="lnum-cba188">♦</a>
 That cries ‘Retire,’ if Warwick bid him stay.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba189" id="lnum-cba189">♦</a>
 <span class="sd-cn">Edw.</span>
  Lord Warwick, on thy shoulder will I lean;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba190" id="lnum-cba190">190</a>
 And when thou fail’st—as God forbid the hour!—</div>
<div class="dverse">Must Edward fall, which peril heaven forfend!</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 No longer Earl of March, but Duke of York:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba193" id="lnum-cba193">♦</a>
 The next degree is England’s royal throne;</div>
<div class="dverse">For King of England shalt thou be proclaim’d</div>
<div class="dverse"><span class="lnum">195</span>
 In every borough as we pass along;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba196" id="lnum-cba196">♦</a>
 And he that throws not up his cap for joy</div>
<div class="dverse">Shall for the fault make forfeit of his head.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cba198" id="lnum-cba198">♦</a>
 King Edward, valiant Richard, Montague,</div>
<div class="dverse">Stay we no longer, dreaming of renown,</div>
<div class="dverse"><span class="lnum">200</span>
 But sound the trumpets, and about our task.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Then, Clifford, were thy heart as hard as steel,</div>
<div class="dverse">As thou hast shown it flinty by thy deeds,</div>
<div class="dverse">I come to pierce it, or to give thee mine.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Then strike up drums: God and Saint George for us!</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse1"><span class="lnum">205</span>
 <span class="sd-cn">War.</span>
  How now! what news?</div>

<div class="dverse1"><span class="sd-cn">Mess.</span>
 The Duke of Norfolk sends you word by me,</div>
<div class="dverse">The queen is coming with a puissant host;</div>
<div class="dverse">And craves your company for speedy counsel.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cba209" id="lnum-cba209">♦</a>
 <span class="sd-cn">War.</span>
 Why then it sorts, brave warriors, let’s away. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cbb</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>Before York</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span>,</span> <span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">M<span>ARGARET</span>,</span> <i>the</i> <span class="smcaps">P<span>RINCE</span></span> <span class="smmaj">OF</span>
<span class="smcaps">W<span>ALES</span>,</span> <span class="smcaps">C<span>LIFFORD</span>,</span> <i>and</i> <span class="smcaps">N<span>ORTHUMBERLAND</span>,</span> <i>with drum and
trumpets</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbb001" id="lnum-cbb001">♦</a>
 <span class="sd-cn">Q. Mar.</span>
  Welcome, my lord, to this brave town of York.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb002" id="lnum-cbb002">♦</a>
 Yonder’s the head of that arch-enemy</div>
<div class="dverse">That sought to be encompass’d with your crown:</div>
<div class="dverse">Doth not the object cheer your heart, my lord?</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">K. Hen.</span>
  Ay, as the rocks cheer them that fear their wreck:</div>
<div class="dverse">To see this sight, it irks my very soul.</div>
<div class="dverse">Withhold revenge, dear God! ’tis not my fault,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb008" id="lnum-cbb008">♦</a>
 Nor wittingly have I infringed my vow.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 My gracious liege, this too much lenity</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb010" id="lnum-cbb010">10</a>
 And harmful pity must be laid aside.</div>
<div class="dverse">To whom do lions cast their gentle looks?</div>
<div class="dverse">Not to the beast that would usurp their den.</div>
<div class="dverse">Whose hand is that the forest bear doth lick?</div>
<div class="dverse">Not his that spoils her young before her face.</div>
<div class="dverse"><span class="lnum">15</span>
 Who ’scapes the lurking serpent’s mortal sting?</div>
<div class="dverse">Not he that sets his foot upon her back.</div>
<div class="dverse">The smallest worm will turn being trodden on,</div>
<div class="dverse">And doves will peck in safeguard of their brood.</div>
<div class="dverse">Ambitious York did level at thy crown,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb020" id="lnum-cbb020">20</a>
 Thou smiling while he knit his angry brows:</div>
<div class="dverse">He, but a duke, would have his son a king,</div>
<div class="dverse">And raise his issue, like a loving sire;</div>
<div class="dverse">Thou, being a king, blest with a goodly son,</div>
<div class="dverse">Didst yield consent to disinherit him,</div>
<div class="dverse"><span class="lnum">25</span>
 Which argued thee a most unloving father.</div>
<div class="dverse">Unreasonable creatures feed their young;</div>
<div class="dverse">And though man’s face be fearful to their eyes,</div>
<div class="dverse">Yet, in protection of their tender ones,</div>
<div class="dverse">Who hath not seen them, even with those wings</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb030" id="lnum-cbb030">30</a>
 Which sometime they have used with fearful flight,</div>
<div class="dverse">Make war with him that climb’d unto their nest,</div>
<div class="dverse">Offering their own lives in their young’s defence?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb033" id="lnum-cbb033">♦</a>
 For shame, my liege, make them your precedent!</div>
<div class="dverse">Were it not pity that this goodly boy</div>
<div class="dverse"><span class="lnum">35</span>
 Should lose his birthright by his father’s fault,</div>
<div class="dverse">And long hereafter say unto his child,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb037" id="lnum-cbb037">♦</a>
 ‘What my great-grandfather and grandsire got</div>
<div class="dverse">My careless father fondly gave away’?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb039" id="lnum-cbb039">♦</a>
 Ah, what a shame were this! Look on the boy;</div>
<div class="dverse"><span class="lnum">40</span>
 And let his manly face, which promiseth</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb041" id="lnum-cbb041">♦</a>
 Successful fortune, steel thy melting heart</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb042" id="lnum-cbb042">♦</a>
 To hold thine own and leave thine own with him.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Full well hath Clifford play’d the orator,</div>
<div class="dverse">Inferring arguments of mighty force.</div>
<div class="dverse"><span class="lnum">45</span>
 But, Clifford, tell me, didst thou never hear</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb046" id="lnum-cbb046">♦</a>
 That things ill-got had ever bad success?</div>
<div class="dverse">And happy always was it for that son</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb048" id="lnum-cbb048">♦</a>
 Whose father for his hoarding went to hell?</div>
<div class="dverse">I’ll leave my son my virtuous deeds behind;</div>
<div class="dverse"><span class="lnum">50</span>
 And would my father had left me no more!</div>
<div class="dverse">For all the rest is held at such a rate</div>
<div class="dverse">As brings a thousand-fold more care to keep</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb053" id="lnum-cbb053">♦</a>
 Than in possession any jot of pleasure.</div>
<div class="dverse">Ah, cousin York! would thy best friends did know</div>
<div class="dverse"><span class="lnum">55</span>
 How it doth grieve me that thy head is here!</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 My lord, cheer up your spirits: our foes are nigh,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb057" id="lnum-cbb057">♦</a>
 And this soft courage makes your followers faint.</div>
<div class="dverse">You promised knighthood to our forward son:</div>
<div class="dverse">Unsheathe your sword, and dub him presently.</div>
<div class="dverse"><span class="lnum">60</span>
 Edward, kneel down.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Edward Plantagenet, arise a knight;</div>
<div class="dverse">And learn this lesson, draw thy sword in right.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 My gracious father, by your kingly leave,</div>
<div class="dverse">I’ll draw it as apparent to the crown,</div>
<div class="dverse"><span class="lnum">65</span>
 And in that quarrel use it to the death.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Why, that is spoken like a toward prince.</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse1"><span class="sd-cn">Mess.</span>
 Royal commanders, be in readiness:</div>
<div class="dverse">For with a band of thirty thousand men</div>
<div class="dverse">Comes Warwick, backing of the Duke of York;</div>
<div class="dverse"><span class="lnum">70</span>
 And in the towns, as they do march along,</div>
<div class="dverse">Proclaims him king, and many fly to him:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb072" id="lnum-cbb072">♦</a>
 Darraign your battle, for they are at hand.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I would your highness would depart the field:</div>
<div class="dverse">The queen hath best success when you are absent.</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Q. Mar.</span>
  Ay, good my lord, and leave us to our fortune.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Why, that’s my fortune too; therefore I’ll stay.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 Be it with resolution then to fight.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 My royal father, cheer these noble lords</div>
<div class="dverse">And hearten those that fight in your defence:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb080" id="lnum-cbb080">80</a>
 Unsheathe your sword, good father; cry ‘Saint George!’</div>

<div class="sd-entry"><i>March. Enter</i> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">G<span>EORGE</span>,</span> <span class="smcaps">R<span>ICHARD</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">N<span>ORFOLK</span>,</span> <span class="smcaps">M<span>ONTAGUE</span>,</span> <i>and</i> Soldiers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbb081" id="lnum-cbb081">♦</a>
 <span class="sd-cn">Edw.</span>
  Now, perjured Henry! wilt thou kneel for grace,</div>
<div class="dverse">And set thy diadem upon my head;</div>
<div class="dverse">Or bide the mortal fortune of the field?</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Go, rate thy minions, proud insulting boy!</div>
<div class="dverse"><span class="lnum">85</span>
 Becomes it thee to be thus bold in terms</div>
<div class="dverse">Before thy sovereign and thy lawful king?</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 I am his king, and he should bow his knee;</div>
<div class="dverse">I was adopted heir by his consent:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb089" id="lnum-cbb089">♦</a>
 Since when, his oath is broke; for, as I hear,</div>
<div class="dverse"><span class="lnum">90</span>
 You, that are king, though he do wear the crown,</div>
<div class="dverse">Have caused him, by new act of parliament,</div>
<div class="dverse">To blot out me, and put his own son in.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 And reason too:</div>
<div class="dverse">Who should succeed the father but the son?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbb095" id="lnum-cbb095">95</a>
 <span class="sd-cn">Rich.</span>
  Are you there, butcher? O, I cannot speak!</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Ay, crook-back, here I stand to answer thee,</div>
<div class="dverse">Or any he the proudest of thy sort.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 ’Twas you that kill’d young Rutland, was it not?</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Ay, and old York, and yet not satisfied.</div>

<div class="dverse1"><span class="lnum">100</span>
 <span class="sd-cn">Rich.</span>
  For God’s sake, lords, give signal to the fight.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbb101" id="lnum-cbb101">♦</a>
 <span class="sd-cn">War.</span>
  What say’st thou, Henry, wilt thou yield the crown?</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Why, how now, long-tongued Warwick! dare you speak?</div>
<div class="dverse">When you and I met at Saint Alban’s last,</div>
<div class="dverse">Your legs did better service than your hands.</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">War.</span>
  Then ’twas my turn to fly, and now ’tis thine.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 You said so much before, and yet you fled.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 ’Twas not your valour, Clifford, drove me thence.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 No, nor your manhood that durst make you stay.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Northumberland, I hold thee reverently.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb110" id="lnum-cbb110">110</a>
 Break off the parley; for scarce I can refrain</div>

<div class="dverse">The execution of my big-swoln heart</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb112" id="lnum-cbb112">♦</a>
 Upon that Clifford, that cruel child-killer.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I slew thy father, call’st thou him a child?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Ay, like a dastard and a treacherous coward,</div>
<div class="dverse"><span class="lnum">115</span>
 As thou didst kill our tender brother Rutland;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb116" id="lnum-cbb116">♦</a>
 But ere sunset I’ll make thee curse the deed.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Have done with words, my lords, and hear me speak.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Defy them then, or else hold close thy lips.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 I prithee, give no limits to my tongue:</div>
<div class="dverse"><span class="lnum">120</span>
 I am a king, and privileged to speak.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbb121" id="lnum-cbb121">♦</a>
 <span class="sd-cn">Clif.</span>
  My liege, the wound that bred this meeting here</div>
<div class="dverse">Cannot be cured by words; therefore be still.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbb123" id="lnum-cbb123">♦</a>
 <span class="sd-cn">Rich.</span>
  Then, executioner, unsheathe thy sword:</div>
<div class="dverse">By him that made us all, I am resolved</div>
<div class="dverse"><span class="lnum">125</span>
 That Clifford’s manhood lies upon his tongue.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Say, Henry, shall I have my right, or no?</div>
<div class="dverse">A thousand men have broke their fasts to-day,</div>
<div class="dverse">That ne’er shall dine unless thou yield the crown.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 If thou deny, their blood upon thy head;</div>
<div class="dverse"><span class="lnum">130</span>
 For York in justice puts his armour on.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 If that be right which Warwick says is right,</div>
<div class="dverse">There is no wrong, but every thing is right.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbb133" id="lnum-cbb133">♦</a>
 <span class="sd-cn">Rich.</span>
  Whoever got thee, there thy mother stands;</div>
<div class="dverse">For, well I wot, thou hast thy mother’s tongue.</div>

<div class="dverse1"><span class="lnum">135</span>
 <span class="sd-cn">Q. Mar.</span>
  But thou art neither like thy sire nor dam;</div>
<div class="dverse">But like a foul mis-shapen stigmatic,</div>
<div class="dverse">Mark’d by the destinies to be avoided,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb138" id="lnum-cbb138">♦</a>
 As venom toads, or lizards’ dreadful stings.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Iron of Naples hid with English gilt,</div>
<div class="dverse"><span class="lnum">140</span>
 Whose father bears the title of a king,—</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb141" id="lnum-cbb141">♦</a>
 As if a channel should be call’d the sea,—</div>
<div class="dverse">Shamest thou not, knowing whence thou art extraught,</div>
<div class="dverse">To let thy tongue detect thy base-born heart?</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 A wisp of straw were worth a thousand crowns,</div>
<div class="dverse"><span class="lnum">145</span>
 To make this shameless callet know herself.</div>
<div class="dverse">Helen of Greece was fairer far than thou,</div>
<div class="dverse">Although thy husband may be Menelaus;</div>
<div class="dverse">And ne’er was Agamemnon’s brother wrong’d</div>
<div class="dverse">By that false woman, as this king by thee.</div>
<div class="dverse"><span class="lnum">150</span>
 His father revell’d in the heart of France,</div>
<div class="dverse">And tamed the king, and made the dauphin stoop;</div>
<div class="dverse">And had he match’d according to his state,</div>
<div class="dverse">He might have kept that glory to this day;</div>
<div class="dverse">But when he took a beggar to his bed,</div>
<div class="dverse"><span class="lnum">155</span>
 And graced thy poor sire with his bridal-day,</div>
<div class="dverse">Even then that sunshine brew’d a shower for him,</div>
<div class="dverse">That wash’d his father’s fortunes forth of France,</div>
<div class="dverse">And heap’d sedition on his crown at home.</div>
<div class="dverse">For what hath broach’d this tumult but thy pride?</div>
<div class="dverse"><span class="lnum">160</span>
 Hadst thou been meek, our title still had slept;</div>
<div class="dverse">And we, in pity of the gentle king,</div>
<div class="dverse">Had slipp’d our claim until another age.</div>

<div class="dverse1"><span class="sd-cn">Geo.</span>
 But when we saw our sunshine made thy spring,</div>
<div class="dverse">And that thy summer bred us no increase,</div>
<div class="dverse"><span class="lnum">165</span>
 We set the axe to thy usurping root;</div>
<div class="dverse">And though the edge hath something hit ourselves,</div>
<div class="dverse">Yet, know thou, since we have begun to strike,</div>
<div class="dverse">We’ll never leave till we have hewn thee down,</div>
<div class="dverse">Or bathed thy growing with our heated bloods.</div>

<div class="dverse1"><span class="lnum">170</span>
 <span class="sd-cn">Edw.</span>
  And, in this resolution, I defy thee;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb171" id="lnum-cbb171">♦</a>
 Not willing any longer conference,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb172" id="lnum-cbb172">♦</a>
 Since thou deniest the gentle king to speak.</div>
<div class="dverse">Sound trumpets! let our bloody colours wave!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb174" id="lnum-cbb174">♦</a>
 And either victory, or else a grave.</div>

<div class="dverse1"><span class="lnum">175</span>
 <span class="sd-cn">Q. Mar.</span>
  Stay, Edward.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbb176" id="lnum-cbb176">♦</a>
 <span class="sd-cn">Edw.</span>
  No, wrangling woman, we’ll no longer stay:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbb177" id="lnum-cbb177">♦</a>
 These words will cost ten thousand lives this day. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cbc</span>
<span class="smcaps">S<span>CENE</span></span> III. <i>A field of battle between Towton and Saxton, in Yorkshire</i>.</h4>

<div class="sd-schg"><i>Alarum. Excursions. Enter</i> <span class="smcaps">W<span>ARWICK</span>.</span></div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbc001" id="lnum-cbc001">♦</a>
 <span class="sd-cn">War.</span>
  Forspent with toil, as runners with a race,</div>
<div class="dverse">I lay me down a little while to breathe;</div>
<div class="dverse">For strokes received, and many blows repaid,</div>
<div class="dverse">Have robb’d my strong-knit sinews of their strength,</div>
<div class="dverse"><span class="lnum">5</span>
 And spite of spite needs must I rest awhile.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">E<span>DWARD</span>,</span> <i>running</i>.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Smile, gentle heaven! or strike, ungentle death!</div>
<div class="dverse">For this world frowns, and Edward’s sun is clouded.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbc008" id="lnum-cbc008">♦</a>
 <span class="sd-cn">War.</span>
  How now, my lord! what hap? what hope of good?</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">G<span>EORGE</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbc009" id="lnum-cbc009">♦</a>
 <span class="sd-cn">Geo.</span>
  Our hap is loss, our hope but sad despair;</div>
<div class="dverse"><span class="lnum">10</span>
 Our ranks are broke, and ruin follows us:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc011" id="lnum-cbc011">♦</a>
 What counsel give you? whither shall we fly?</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Bootless is flight, they follow us with wings;</div>
<div class="dverse">And weak we are and cannot shun pursuit.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">R<span>ICHARD</span></span>.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Ah, Warwick, why hast thou withdrawn thyself?</div>
<div class="dverse"><span class="lnum">15</span>
 Thy brother’s blood the thirsty earth hath drunk,</div>
<div class="dverse">Broach’d with the steely point of Clifford’s lance;</div>
<div class="dverse">And in the very pangs of death he cried,</div>
<div class="dverse">Like to a dismal clangor heard from far,</div>
<div class="dverse">‘Warwick, revenge! brother, revenge my death!’</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc020" id="lnum-cbc020">20</a>
 So, underneath the belly of their steeds,</div>
<div class="dverse">That stain’d their fetlocks in his smoking blood,</div>
<div class="dverse">The noble gentleman gave up the ghost.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then let the earth be drunken with our blood:</div>
<div class="dverse">I’ll kill my horse, because I will not fly.</div>
<div class="dverse"><span class="lnum">25</span>
 Why stand we like soft-hearted women here,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc026" id="lnum-cbc026">♦</a>
 Wailing our losses, whiles the foe doth rage;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc027" id="lnum-cbc027">♦</a>
 And look upon, as if the tragedy</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc028" id="lnum-cbc028">♦</a>
 Were play’d in jest by counterfeiting actors?</div>
<div class="dverse">Here on my knee I vow to God above,</div>
<div class="dverse"><span class="lnum">30</span>
 I’ll never pause again, never stand still,</div>
<div class="dverse">Till either death hath closed these eyes of mine</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc032" id="lnum-cbc032">♦</a>
 Or fortune given me measure of revenge.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 O Warwick, I do bend my knee with thine;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc034" id="lnum-cbc034">♦</a>
 And in this vow do chain my soul to thine!</div>
<div class="dverse"><span class="lnum">35</span>
 And, ere my knee rise from the earth’s cold face,</div>
<div class="dverse">I throw my hands, mine eyes, my heart to thee,</div>
<div class="dverse">Thou setter up and plucker down of kings,</div>
<div class="dverse">Beseeching thee, if with thy will it stands</div>
<div class="dverse">That to my foes this body must be prey,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc040" id="lnum-cbc040">40</a>
 Yet that thy brazen gates of heaven may ope,</div>
<div class="dverse">And give sweet passage to my sinful soul!</div>
<div class="dverse">Now, lords, take leave until we meet again,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc043" id="lnum-cbc043">♦</a>
 Where’er it be, in heaven or in earth.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbc044" id="lnum-cbc044">♦</a>
 <span class="sd-cn">Rich.</span>
  Brother, give me thy hand; and, gentle Warwick,</div>
<div class="dverse"><span class="lnum">45</span>
 Let me embrace thee in my weary arms:</div>
<div class="dverse">I, that did never weep, now melt with woe</div>
<div class="dverse">That winter should cut off our spring-time so.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbc048" id="lnum-cbc048">♦</a>
 <span class="sd-cn">War.</span>
  Away, away! Once more, sweet lords, farewell.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbc049" id="lnum-cbc049">♦</a>
 <span class="sd-cn">Geo.</span>
  Yet let us all together to our troops,</div>
<div class="dverse"><span class="lnum">50</span>
 And give them leave to fly that will not stay;</div>
<div class="dverse">And call them pillars that will stand to us;</div>
<div class="dverse">And, if we thrive, promise them such rewards</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc053" id="lnum-cbc053">♦</a>
 As victors wear at the Olympian games:</div>
<div class="dverse">This may plant courage in their quailing breasts;</div>
<div class="dverse"><span class="lnum">55</span>
 For yet is hope of life and victory.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbc056" id="lnum-cbc056">♦</a>
 Forslow no longer, make we hence amain. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cbd</span>
<span class="smcaps">S<span>CENE</span></span> IV. <i>Another part of the field</i>.</h4>

<div class="sd-schg"><i>Excursions. Enter</i> <span class="smcaps">R<span>ICHARD</span></span> <i>and</i> <span class="smcaps">C<span>LIFFORD</span>.</span></div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbd001" id="lnum-cbd001">♦</a>
 <span class="sd-cn">Rich.</span>
  Now, Clifford, I have singled thee alone:</div>
<div class="dverse">Suppose this arm is for the Duke of York,</div>
<div class="dverse">And this for Rutland; both bound to revenge,</div>
<div class="dverse">Wert thou environ’d with a brazen wall.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">Clif.</span>
  Now, Richard, I am with thee here alone:</div>
<div class="dverse">This is the hand that stabb’d thy father York;</div>
<div class="dverse">And this the hand that slew thy brother Rutland;</div>
<div class="dverse">And here’s the heart that triumphs in their death</div>
<div class="dverse">And cheers these hands that slew thy sire and brother</div>
<div class="dverse"><span class="lnum">10</span>
 To execute the like upon thyself;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbd011" id="lnum-cbd011">♦</a>
 And so, have at thee! <span class="sd-verseend">[<i>They fight. Warwick comes; Clifford flies.</i></span></div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Nay, Warwick, single out some other chase;</div>
<div class="dverse">For I myself will hunt this wolf to death. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cbe</span>
<span class="smcaps">S<span>CENE</span></span> V. <i>Another part of the field</i>.</h4>

<div class="sd-schg"><i>Alarum. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span></span> <i>alone</i>. </div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbe001" id="lnum-cbe001">♦</a>
 <span class="sd-cn">King.</span>
  This battle fares like to the morning’s war,</div>
<div class="dverse">When dying clouds contend with growing light,</div>
<div class="dverse">What time the shepherd, blowing of his nails,</div>
<div class="dverse">Can neither call it perfect day nor night.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe005" id="lnum-cbe005">5</a>
 Now sways it this way, like a mighty sea</div>
<div class="dverse">Forced by the tide to combat with the wind;</div>
<div class="dverse">Now sways it that way, like the selfsame sea</div>
<div class="dverse">Forced to retire by fury of the wind:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe009" id="lnum-cbe009">♦</a>
 Sometime the flood prevails, and then the wind;</div>
<div class="dverse"><span class="lnum">10</span>
 Now one the better, then another best;</div>
<div class="dverse">Both tugging to be victors, breast to breast,</div>
<div class="dverse">Yet neither conqueror nor conquered:</div>
<div class="dverse">So is the equal poise of this fell war.</div>
<div class="dverse">Here on this molehill will I sit me down.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe015" id="lnum-cbe015">15</a>
 To whom God will, there be the victory!</div>
<div class="dverse">For Margaret my queen, and Clifford too,</div>
<div class="dverse">Have chid me from the battle; swearing both</div>
<div class="dverse">They prosper best of all when I am thence.</div>
<div class="dverse">Would I were dead! if God’s good will were so;</div>
<div class="dverse"><span class="lnum">20</span>
 For what is in this world but grief and woe?</div>
<div class="dverse">O God! methinks it were a happy life,</div>
<div class="dverse">To be no better than a homely swain;</div>
<div class="dverse">To sit upon a hill, as I do now,</div>
<div class="dverse">To carve out dials quaintly, point by point,</div>
<div class="dverse"><span class="lnum">25</span>
 Thereby to see the minutes how they run,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe026" id="lnum-cbe026">♦</a>
 How many make the hour full complete;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe027" id="lnum-cbe027">♦</a>
 How many hours bring about the day;</div>
<div class="dverse">How many days will finish up the year;</div>
<div class="dverse">How many years a mortal man may live.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe030" id="lnum-cbe030">30</a>
 When this is known, then to divide the times:</div>
<div class="dverse">So many hours must I tend my flock;</div>
<div class="dverse">So many hours must I take my rest;</div>
<div class="dverse">So many hours must I contemplate;</div>
<div class="dverse">So many hours must I sport myself;</div>
<div class="dverse"><span class="lnum">35</span>
 So many days my ewes have been with young;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe036" id="lnum-cbe036">♦</a>
 So many weeks ere the poor fools will ean;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe037" id="lnum-cbe037">♦</a>
 So many years ere I shall shear the fleece:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe038" id="lnum-cbe038">♦</a>
 So minutes, hours, days, months, and years,</div>
<div class="dverse">Pass’d over to the end they were created,</div>
<div class="dverse"><span class="lnum">40</span>
 Would bring white hairs unto a quiet grave.</div>
<div class="dverse">Ah, what a life were this! how sweet! how lovely!</div>
<div class="dverse">Gives not the hawthorn-bush a sweeter shade</div>
<div class="dverse">To shepherds looking on their silly sheep,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe044" id="lnum-cbe044">♦</a>
 Than doth a rich embroider’d canopy</div>
<div class="dverse"><span class="lnum">45</span>
 To kings that fear their subjects’ treachery?</div>
<div class="dverse">O, yes, it doth; a thousand-fold it doth.</div>
<div class="dverse">And to conclude, the shepherd’s homely curds,</div>
<div class="dverse">His cold thin drink out of his leather bottle,</div>
<div class="dverse">His wonted sleep under a fresh tree’s shade,</div>
<div class="dverse"><span class="lnum">50</span>
 All which secure and sweetly he enjoys,</div>
<div class="dverse">Is far beyond a prince’s delicates,</div>
<div class="dverse">His viands sparkling in a golden cup,</div>
<div class="dverse">His body couched in a curious bed,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe054" id="lnum-cbe054">♦</a>
 When care, mistrust, and treason waits on him.</div>

<div class="sd-entry"><i>Alarum. Enter a</i> Son <i>that has killed his father, dragging in the dead body</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbe055" id="lnum-cbe055">55</a>
 <span class="sd-cn">Son.</span>
  Ill blows the wind that profits nobody.</div>
<div class="dverse">This man, whom hand to hand I slew in fight,</div>
<div class="dverse">May be possessed with some store of crowns;</div>
<div class="dverse">And I, that haply take them from him now,</div>
<div class="dverse">May yet ere night yield both my life and them</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe060" id="lnum-cbe060">60</a>
 To some man else, as this dead man doth me.</div>
<div class="dverse">Who’s this? O God! it is my father’s face,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe062" id="lnum-cbe062">♦</a>
 Whom in this conflict I unwares have kill’d.</div>
<div class="dverse">O heavy times, begetting such events!</div>
<div class="dverse">From London by the king was I press’d forth;</div>
<div class="dverse"><span class="lnum">65</span>
 My father, being the Earl of Warwick’s man,</div>
<div class="dverse">Came on the part of York, press’d by his master;</div>
<div class="dverse">And I, who at his hands received my life,</div>
<div class="dverse">Have by my hands of life bereaved him.</div>
<div class="dverse">Pardon me, God, I knew not what I did!</div>
<div class="dverse"><span class="lnum">70</span>
 And pardon, father, for I knew not thee!</div>
<div class="dverse">My tears shall wipe away these bloody marks;</div>
<div class="dverse">And no more words till they have flow’d their fill.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 O piteous spectacle! O bloody times!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe074" id="lnum-cbe074">♦</a>
 Whiles lions war and battle for their dens,</div>
<div class="dverse"><span class="lnum">75</span>
 Poor harmless lambs abide their enmity.</div>
<div class="dverse">Weep, wretched man, I’ll aid thee tear for tear;</div>
<div class="dverse">And let our hearts and eyes, like civil war,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe078" id="lnum-cbe078">♦</a>
 Be blind with tears, and break o’ercharged with grief.</div>

<div class="sd-entry"><i>Enter a</i> Father <i>that has killed his son, bringing in the body</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbe079" id="lnum-cbe079">♦</a>
 <span class="sd-cn">Fath.</span>
  Thou that so stoutly hast resisted me,</div>
<div class="dverse"><span class="lnum">80</span>
 Give me thy gold, if thou hast any gold;</div>
<div class="dverse">For I have bought it with an hundred blows.</div>
<div class="dverse">But let me see: is this our foeman’s face?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe083" id="lnum-cbe083">♦</a>
 Ah, no, no, no, it is mine only son!</div>
<div class="dverse">Ah, boy, if any life be left in thee,</div>
<div class="dverse"><span class="lnum">85</span>
 Throw up thine eye! see, see what showers arise,</div>
<div class="dverse">Blown with the windy tempest of my heart,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe087" id="lnum-cbe087">♦</a>
 Upon thy wounds, that kill mine eye and heart!</div>
<div class="dverse">O, pity, God, this miserable age!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe089" id="lnum-cbe089">♦</a>
 What stratagems, how fell, how butcherly,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe090" id="lnum-cbe090">90</a>
 Erroneous, mutinous and unnatural,</div>
<div class="dverse">This deadly quarrel daily doth beget!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe092" id="lnum-cbe092">♦</a>
 O boy, thy father gave thee life too soon,</div>
<div class="dverse">And hath bereft thee of thy life too late!</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Woe above woe! grief more than common grief!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe095" id="lnum-cbe095">95</a>
 O that my death would stay these ruthful deeds!</div>
<div class="dverse">O, pity, pity, gentle heaven, pity!</div>
<div class="dverse">The red rose and the white are on his face,</div>
<div class="dverse">The fatal colours of our striving houses:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe099" id="lnum-cbe099">♦</a>
 The one his purple blood right well resembles;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe100" id="lnum-cbe100">100</a>
 The other his pale cheeks, methinks, presenteth:</div>
<div class="dverse">Wither one rose, and let the other flourish;</div>
<div class="dverse">If you contend, a thousand lives must wither.</div>

<div class="dverse1"><span class="sd-cn">Son.</span>
 How will my mother for a father’s death</div>
<div class="dverse">Take on with me and ne’er be satisfied!</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">Fath.</span>
  How will my wife for slaughter of my son</div>
<div class="dverse">Shed seas of tears and ne’er be satisfied!</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 How will the country for these woful chances</div>
<div class="dverse">Misthink the king and not be satisfied!</div>

<div class="dverse1"><span class="sd-cn">Son.</span>
 Was ever son so rued a father’s death?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbe110" id="lnum-cbe110">110</a>
 <span class="sd-cn">Fath.</span>
  Was ever father so bemoan’d his son?</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Was ever king so grieved for subjects’ woe?</div>
<div class="dverse">Much is your sorrow; mine ten times so much.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbe113" id="lnum-cbe113">♦</a>
 <span class="sd-cn">Son.</span>
 I’ll bear thee hence, where I may weep my fill. <span class="sd-verseend">[<i>Exit with the body.</i></span></div>

<div class="dverse1"><span class="sd-cn">Fath.</span>
 These arms of mine shall be thy winding-sheet;</div>
<div class="dverse"><span class="lnum">115</span>
 My heart, sweet boy, shall be thy sepulchre,</div>
<div class="dverse">For from my heart thine image ne’er shall go;</div>
<div class="dverse">My sighing breast shall be thy funeral bell;</div>
<div class="dverse">And so obsequious will thy father be,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe119" id="lnum-cbe119">♦</a>
 Even for the loss of thee, having no more,</div>
<div class="dverse"><span class="lnum">120</span>
 As Priam was for all his valiant sons.</div>
<div class="dverse">I’ll bear thee hence; and let them fight that will,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe122" id="lnum-cbe122">♦</a>
 For I have murdered where I should not kill. <span class="sd-verseend">[<i>Exit with the body.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Sad-hearted men, much overgone with care,</div>
<div class="dverse">Here sits a king more woful than you are.</div>

<div class="sd-entry"><i>Alarums: excursions. Enter</i> <span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">M<span>ARGARET</span>,</span> <i>the</i> <span class="smcaps">P<span>RINCE</span>,</span>
<i>and</i> <span class="smcaps">E<span>XETER</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbe125" id="lnum-cbe125">125</a>
 <span class="sd-cn">Prince.</span>
  Fly, father, fly! for all your friends are fled,</div>
<div class="dverse">And Warwick rages like a chafed bull:</div>
<div class="dverse">Away! for death doth hold us in pursuit.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Mount you, my lord; towards Berwick post amain:</div>
<div class="dverse">Edward and Richard, like a brace of greyhounds</div>
<div class="dverse"><span class="lnum">130</span>
 Having the fearful flying hare in sight,</div>
<div class="dverse">With fiery eyes sparkling for very wrath,</div>
<div class="dverse">And bloody steel grasp’d in their ireful hands,</div>
<div class="dverse">Are at our backs; and therefore hence amain.</div>

<div class="dverse1"><span class="sd-cn">Exe.</span>
 Away! for vengeance comes along with them:</div>
<div class="dverse"><span class="lnum">135</span>
 Nay, stay not to expostulate, make speed;</div>
<div class="dverse">Or else come after: I’ll away before.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Nay, take me with thee, good sweet Exeter:</div>
<div class="dverse">Not that I fear to stay, but love to go</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbe139" id="lnum-cbe139">♦</a>
 Whither the queen intends. Forward; away!
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cbf</span>
<span class="smcaps">S<span>CENE</span></span> VI. <i>Another part of the field</i>.</h4>

<div class="sd-schg"><i>A loud alarum. Enter</i> <span class="smcaps">C<span>LIFFORD</span>,</span> <i>wounded</i>. </div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf001" id="lnum-cbf001">♦</a>
 <span class="sd-cn">Clif.</span>
  Here burns my candle out; ay, here it dies,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf002" id="lnum-cbf002">♦</a>
 Which, whiles it lasted, gave King Henry light.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf003" id="lnum-cbf003">♦</a>
 O Lancaster, I fear thy overthrow</div>
<div class="dverse">More than my body’s parting with my soul!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf005" id="lnum-cbf005">5</a>
 My love and fear glued many friends to thee;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf006" id="lnum-cbf006">♦</a>
 And, now I fall, thy tough commixture melts.</div>
<div class="dverse">Impairing Henry, strengthening misproud York,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf008" id="lnum-cbf008">♦</a>
 The common people swarm like summer flies;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf009" id="lnum-cbf009">♦</a>
 And whither fly the gnats but to the sun?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf010" id="lnum-cbf010">10</a>
 And who shines now but Henry’s enemies?</div>
<div class="dverse">O Phœbus, hadst thou never given consent</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf012" id="lnum-cbf012">♦</a>
 That Phaëthon should check thy fiery steeds,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf013" id="lnum-cbf013">♦</a>
 Thy burning car never had scorch’d the earth!</div>
<div class="dverse">And, Henry, hadst thou sway’d as kings should do,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf015" id="lnum-cbf015">15</a>
 Or as thy father and his father did,</div>
<div class="dverse">Giving no ground unto the house of York,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf017" id="lnum-cbf017">♦</a>
 They never then had sprung like summer flies;</div>
<div class="dverse">I and ten thousand in this luckless realm</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf019" id="lnum-cbf019">♦</a>
 Had left no mourning widows for our death;</div>
<div class="dverse"><span class="lnum">20</span>
 And thou this day hadst kept thy chair in peace.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf021" id="lnum-cbf021">♦</a>
 For what doth cherish weeds but gentle air?</div>
<div class="dverse">And what makes robbers bold but too much lenity?</div>
<div class="dverse">Bootless are plaints, and cureless are my wounds;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf024" id="lnum-cbf024">♦</a>
 No way to fly, nor strength to hold out flight:</div>
<div class="dverse"><span class="lnum">25</span>
 The foe is merciless, and will not pity;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf026" id="lnum-cbf026">♦</a>
 For at their hands I have deserved no pity.</div>
<div class="dverse">The air hath got into my deadly wounds,</div>
<div class="dverse">And much effuse of blood doth make me faint.</div>
<div class="dverse">Come, York and Richard, Warwick and the rest;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf030" id="lnum-cbf030">30</a>
 I stabb’d your fathers’ bosoms, split my breast. <span class="sd-verseend">[<i>He faints.</i></span></div>

<div class="sd-entry"><i>Alarum and retreat. Enter</i>, <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">G<span>EORGE</span>,</span> <span class="smcaps">R<span>ICHARD</span>,</span>
    <span class="smcaps">M<span>ONTAGUE</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <i>and</i> <span class="smcaps">S<span>OLDIERS</span></span>,</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Now breathe we, lords: good fortune bids us pause,</div>
<div class="dverse">And smooth the frowns of war with peaceful looks.</div>
<div class="dverse">Some troops pursue the bloody-minded queen,</div>
<div class="dverse">That led calm Henry, though he were a king,</div>
<div class="dverse"><span class="lnum">35</span>
 As doth a sail, fill’d with a fretting gust,</div>
<div class="dverse">Command an argosy to stem the waves.</div>
<div class="dverse">But think you, lords, that Clifford fled with them?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 No, ’tis impossible he should escape;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf039" id="lnum-cbf039">♦</a>
 For, though before his face I speak the words,</div>
<div class="dverse"><span class="lnum">40</span>
 Your brother Richard mark’d him for the grave:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf041" id="lnum-cbf041">♦</a>
 And wheresoe’er he is, he’s surely dead. <span class="sd-verseend">[<i>Clifford groans, and dies.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf042" id="lnum-cbf042">♦</a>
 <span class="sd-cn">Edw.</span>
  Whose soul is that which takes her heavy leave?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf043" id="lnum-cbf043">♦</a>
 <span class="sd-cn">Rich.</span>
  A deadly groan, like life and death’s departing.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 See who it is: and, now the battle’s ended,</div>
<div class="dverse"><span class="lnum">45</span>
 If friend or foe, let him be gently used.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Revoke that doom of mercy, for ’tis Clifford;</div>
<div class="dverse">Who not contented that he lopp’d the branch</div>
<div class="dverse">In hewing Rutland when his leaves put forth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf049" id="lnum-cbf049">♦</a>
 But set his murdering knife unto the root</div>
<div class="dverse"><span class="lnum">50</span>
 From whence that tender spray did sweetly spring,</div>
<div class="dverse">I mean our princely father, Duke of York.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 From off the gates of York fetch down the head,</div>
<div class="dverse">Your father’s head, which Clifford placed there;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf054" id="lnum-cbf054">♦</a>
 Instead whereof let this supply the room:</div>
<div class="dverse"><span class="lnum">55</span>
 Measure for measure must be answered.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Bring forth that fatal screech-owl to our house,</div>
<div class="dverse">That nothing sung but death to us and ours:</div>
<div class="dverse">Now death shall stop his dismal threatening sound,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf059" id="lnum-cbf059">♦</a>
 And his ill-boding tongue no more shall speak.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf060" id="lnum-cbf060">60</a>
 <span class="sd-cn">War.</span>
  I think his understanding is bereft.</div>
<div class="dverse">Speak, Clifford, dost thou know who speaks to thee?</div>
<div class="dverse">Dark cloudy death o’ershades his beams of life,</div>
<div class="dverse">And he nor sees nor hears us what we say.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 O, would he did! and so perhaps he doth:</div>
<div class="dverse"><span class="lnum">65</span>
 ’Tis but his policy to counterfeit,</div>
<div class="dverse">Because he would avoid such bitter taunts</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf067" id="lnum-cbf067">♦</a>
 Which in the time of death he gave our father.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf068" id="lnum-cbf068">♦</a>
 <span class="sd-cn">Geo.</span>
  If so thou think’st, vex him with eager words.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Clifford, ask mercy and obtain no grace.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Edw.</span>
  Clifford, repent in bootless penitence.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Clifford, devise excuses for thy faults.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf072" id="lnum-cbf072">♦</a>
 <span class="sd-cn">Geo.</span>
  While we devise fell tortures for thy faults.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Thou didst love York, and I am son to York.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Thou pitied’st Rutland; I will pity thee.</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Geo.</span>
  Where’s Captain Margaret, to fence you now?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf076" id="lnum-cbf076">♦</a>
 <span class="sd-cn">War.</span>
  They mock thee, Clifford: swear as thou wast wont.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf077" id="lnum-cbf077">♦</a>
 <span class="sd-cn">Rich.</span>
  What, not an oath? nay, then the world goes hard</div>
<div class="dverse">When Clifford cannot spare his friends an oath.</div>
<div class="dverse">I know by that he’s dead; and, by my soul,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf080" id="lnum-cbf080">80</a>
 If this right hand would buy two hours’ life,</div>
<div class="dverse">That I in all despite might rail at him,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf082" id="lnum-cbf082">♦</a>
 This hand should chop it off, and with the issuing blood</div>
<div class="dverse">Stifle the villain whose unstanched thirst</div>
<div class="dverse">York and young Rutland could not satisfy.</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">War.</span>
  Ay, but he’s dead: off with the traitor’s head,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf086" id="lnum-cbf086">♦</a>
 And rear it in the place your father’s stands.</div>
<div class="dverse">And now to London with triumphant march,</div>
<div class="dverse">There to be crowned England’s royal king:</div>
<div class="dverse">From whence shall Warwick cut the sea to France,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf090" id="lnum-cbf090">90</a>
 And ask the Lady Bona for thy queen:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf091" id="lnum-cbf091">♦</a>
 So shalt thou sinew both these lands together;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf092" id="lnum-cbf092">♦</a>
 And, having France thy friend, thou shalt not dread</div>
<div class="dverse">The scatter’d foe that hopes to rise again;</div>
<div class="dverse">For though they cannot greatly sting to hurt,</div>
<div class="dverse"><span class="lnum">95</span>
 Yet look to have them buzz to offend thine ears.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf096" id="lnum-cbf096">♦</a>
 First will I see the coronation;</div>
<div class="dverse">And then to Brittany I’ll cross the sea,</div>
<div class="dverse">To effect this marriage, so it please my lord.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Even as thou wilt, sweet Warwick, let it be;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cbf100" id="lnum-cbf100">100</a>
 For in thy shoulder do I build my seat,</div>
<div class="dverse">And never will I undertake the thing</div>
<div class="dverse">Wherein thy counsel and consent is wanting.</div>
<div class="dverse">Richard, I will create thee Duke of Gloucester,</div>
<div class="dverse">And George, of Clarence: Warwick, as ourself,</div>
<div class="dverse"><span class="lnum">105</span>
 Shall do and undo as him pleaseth best.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cbf106" id="lnum-cbf106">♦</a>
 <span class="sd-cn">Rich.</span>
  Let me be Duke of Clarence, George of Gloucester;</div>
<div class="dverse">For Gloucester’s dukedom is too ominous.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Tut, that’s a foolish observation:</div>
<div class="dverse">Richard, be Duke of Gloucester. Now to London,</div>
<div class="dverse"><span class="lnum">110</span>
 To see these honours in possession. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT III.</h3>

<h4 class="h4main"><span class="dnavigate">cca</span>
<span class="smcaps">S<span>CENE</span></span> I.
 <i>A forest in the north of England</i>.</h4>

<div class="sd-schg"><i>Enter two</i> Keepers,
 <i>with cross-bows in their hands</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca001" id="lnum-cca001">♦</a>
 <span class="sd-cn">First Keep.</span>
  Under this thick-grown brake we’ll shroud ourselves;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca002" id="lnum-cca002">♦</a>
 For through this laund anon the deer will come;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca003" id="lnum-cca003">♦</a>
 And in this covert will we make our stand,</div>
<div class="dverse">Culling the principal of all the deer.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca005" id="lnum-cca005">5</a>
 <span class="sd-cn">Sec. Keep.</span>
  I’ll stay above the hill, so both may shoot.</div>

<div class="dverse1"><span class="sd-cn">First Keep.</span>
 That cannot be; the noise of thy cross-bow</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca007" id="lnum-cca007">♦</a>
 Will scare the herd, and so my shoot is lost.</div>
<div class="dverse">Here stand we both, and aim we at the best:</div>
<div class="dverse">And, for the time shall not seem tedious,</div>
<div class="dverse"><span class="lnum">10</span>
 I’ll tell thee what befel me on a day</div>
<div class="dverse">In this self-place where now we mean to stand.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca012" id="lnum-cca012">♦</a>
 <span class="sd-cn">Sec. Keep.</span>
  Here comes a man; let’s stay till he be past.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span>,</span> <i>disguised, with a prayer-book</i>.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 From Scotland am I stol’n, even of pure love,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca014" id="lnum-cca014">♦</a>
 To greet mine own land with my wishful sight.</div>
<div class="dverse"><span class="lnum">15</span>
 No, Harry, Harry, ’tis no land of thine;</div>
<div class="dverse">Thy place is fill’d, thy sceptre wrung from thee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca017" id="lnum-cca017">♦</a>
 Thy balm wash’d off wherewith thou wast anointed:</div>
<div class="dverse">No bending knee will call thee Cæsar now,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca019" id="lnum-cca019">♦</a>
 No humble suitors press to speak for right,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca020" id="lnum-cca020">20</a>
 No, not a man comes for redress of thee;</div>
<div class="dverse">For how can I help them, and not myself?</div>

<div class="dverse1"><span class="sd-cn">First Keep.</span>
 Ay, here’s a deer whose skin ’s a keeper’s fee:</div>
<div class="dverse">This is the quondam king; let’s seize upon him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca024" id="lnum-cca024">♦</a>
 <span class="sd-cn">K. Hen.</span>
  Let me embrace thee, sour adversity,</div>
<div class="dverse"><span class="lnum">25</span>
 For wise men say it is the wisest course.</div>

<div class="dverse1"><span class="sd-cn">Sec. Keep.</span>
 Why linger we? let us lay hands upon him.</div>

<div class="dverse1"><span class="sd-cn">First Keep.</span>
 Forbear awhile; we’ll hear a little more.</div>

<div class="dverse1" id="lnum-cca028"><span class="sd-cn">K. Hen.</span>
 My queen and son are gone to France for aid;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca029" id="lnum-cca029">♦</a>
 And, as I hear, the great commanding Warwick</div>
<div class="dverse"><span class="lnum">30</span>
 Is thither gone, to crave the French king’s sister</div>
<div class="dverse">To wife for Edward: if this news be true,</div>
<div class="dverse">Poor queen and son, your labour is but lost;</div>
<div class="dverse">For Warwick is a subtle orator,</div>
<div class="dverse">And Lewis a prince soon won with moving words.</div>
<div class="dverse"><span class="lnum">35</span>
 By this account then Margaret may win him;</div>
<div class="dverse">For she’s a woman to be pitied much:</div>
<div class="dverse">Her sighs will make a battery in his breast;</div>
<div class="dverse">Her tears will pierce into a marble heart;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca039" id="lnum-cca039">♦</a>
 The tiger will be mild whiles she doth mourn;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca040" id="lnum-cca040">40</a>
 And Nero will be tainted with remorse,</div>
<div class="dverse">To hear and see her plaints, her brinish tears.</div>
<div class="dverse">Ay, but she’s come to beg, Warwick, to give;</div>
<div class="dverse">She, on his left side, craving aid for Henry,</div>
<div class="dverse">He, on his right, asking a wife for Edward.</div>
<div class="dverse"><span class="lnum">45</span>
 She weeps, and says her Henry is deposed;</div>
<div class="dverse">He smiles, and says his Edward is install’d;</div>
<div class="dverse">That she, poor wretch, for grief can speak no more;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca048" id="lnum-cca048">♦</a>
 Whiles Warwick tells his title, smooths the wrong,</div>
<div class="dverse">Inferreth arguments of mighty strength,</div>
<div class="dverse"><span class="lnum">50</span>
 And in conclusion wins the king from her,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca051" id="lnum-cca051">♦</a>
 With promise of his sister, and what else,</div>
<div class="dverse">To strengthen and support King Edward’s place.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca053" id="lnum-cca053">♦</a>
 O Margaret, thus ’twill be; and thou, poor soul,</div>
<div class="dverse">Art then forsaken, as thou went’st forlorn!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca055" id="lnum-cca055">55</a>
 <span class="sd-cn">Sec. Keep.</span>
  Say, what art thou that talk’st of kings and queens?</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 More than I seem, and less than I was born to:</div>
<div class="dverse">A man at least, for less I should not be;</div>
<div class="dverse">And men may talk of kings, and why not I?</div>

<div class="dverse1"><span class="sd-cn">Sec. Keep.</span>
 Ay, but thou talk’st as if thou wert a king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca060" id="lnum-cca060">60</a>
 <span class="sd-cn">K. Hen.</span>
  Why, so I am, in mind; and that’s enough.</div>

<div class="dverse1"><span class="sd-cn">Sec. Keep.</span>
 But, if thou be a king, where is thy crown?</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 My crown is in my heart, not on my head;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca063" id="lnum-cca063">♦</a>
 Not deck’d with diamonds and Indian stones,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca064" id="lnum-cca064">♦</a>
 Nor to be seen: my crown is call’d content:</div>
<div class="dverse"><span class="lnum">65</span>
 A crown it is that seldom kings enjoy.</div>

<div class="dverse1"><span class="sd-cn">Sec. Keep.</span>
 Well, if you be a king crown’d with content,</div>
<div class="dverse">Your crown content and you must be contented</div>
<div class="dverse">To go along with us; for, as we think,</div>
<div class="dverse">You are the king King Edward hath deposed;</div>
<div class="dverse"><span class="lnum">70</span>
 And we his subjects sworn in all allegiance</div>
<div class="dverse">Will apprehend you as his enemy.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 But did you never swear, and break an oath?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca073" id="lnum-cca073">♦</a>
 <span class="sd-cn">Sec. Keep.</span>
  No, never such an oath; nor will not now.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca074" id="lnum-cca074">♦</a>
 <span class="sd-cn">K. Hen.</span>
  Where did you dwell when I was King of England?</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Sec. Keep.</span>
  Here in this country, where we now remain.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 I was anointed king at nine months old;</div>
<div class="dverse">My father and my grandfather were kings,</div>
<div class="dverse">And you were sworn true subjects unto me:</div>
<div class="dverse">And tell me, then, have you not broke your oaths?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca080" id="lnum-cca080">80</a>
 <span class="sd-cn">First Keep.</span>
  No;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca081" id="lnum-cca081">♦</a>
 For we were subjects but while you were king.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Why, am I dead? do I not breathe a man?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca083" id="lnum-cca083">♦</a>
 Ah, simple men, you know not what you swear!</div>
<div class="dverse">Look, as I blow this feather from my face,</div>
<div class="dverse"><span class="lnum">85</span>
 And as the air blows it to me again,</div>
<div class="dverse">Obeying with my wind when I do blow,</div>
<div class="dverse">And yielding to another when it blows,</div>
<div class="dverse">Commanded always by the greater gust;</div>
<div class="dverse">Such is the lightness of you common men.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca090" id="lnum-cca090">90</a>
 But do not break your oaths; for of that sin</div>
<div class="dverse">My mild entreaty shall not make you guilty.</div>
<div class="dverse">Go where you will, the king shall be commanded;</div>
<div class="dverse">And be you kings, command, and I’ll obey.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca094" id="lnum-cca094">♦</a>
 <span class="sd-cn">First Keep.</span>
  We are true subjects to the king, King Edward.</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">K. Hen.</span>
  So would you be again to Henry,</div>
<div class="dverse">If he were seated as King Edward is.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cca097" id="lnum-cca097">♦</a>
 <span class="sd-cn">First Keep.</span>
  We charge you, in God’s name, and the king’s,</div>
<div class="dverse">To go with us unto the officers.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 In God’s name, lead; your king’s name be obey’d:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cca100" id="lnum-cca100">100</a>
 And what God will, that let your king perform;</div>
<div class="dverse">And what he will, I humbly yield unto. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">ccb</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>London. The palace</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">C<span>LARENCE</span>,</span> <i>and</i>
<span class="smcaps">L<span>ADY</span></span> <span class="smcaps">G<span>REY</span>.</span> </div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb001" id="lnum-ccb001">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Brother of Gloucester, at Saint Alban’s field</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb002" id="lnum-ccb002">♦</a>
 This lady’s husband, Sir Richard Grey, was slain,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb003" id="lnum-ccb003">♦</a>
 His lands then seized on by the conqueror:</div>
<div class="dverse">Her suit is now to repossess those lands;</div>
<div class="dverse"><span class="lnum">5</span>
 Which we in justice cannot well deny,</div>
<div class="dverse">Because in quarrel of the house of York</div>
<div class="dverse">The worthy gentleman did lose his life.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Your highness shall do well to grant her suit;</div>
<div class="dverse">It were dishonour to deny it her.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">K. Edw.</span>
  It were no less; but yet I’ll make a pause.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb011" id="lnum-ccb011">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span> Yea, is it so?</div>
<div class="dverse">I see the lady hath a thing to grant,</div>
<div class="dverse">Before the king will grant her humble suit.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb014" id="lnum-ccb014">♦</a>
 <span class="sd-cn">Clar.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 He knows the game: how true he keeps the wind!</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span> Silence!</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Widow, we will consider of your suit;</div>
<div class="dverse">And come some other time to know our mind.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 Right gracious lord, I cannot brook delay:</div>
<div class="dverse">May it please your highness to resolve me now;</div>
<div class="dverse"><span class="lnum">20</span>
 And what your pleasure is, shall satisfy me.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb021" id="lnum-ccb021">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span>
 Ay, widow? then I’ll warrant you all your lands,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb022" id="lnum-ccb022">♦</a>
 An if what pleases him shall pleasure you.</div>
<div class="dverse">Fight closer, or, good faith, you’ll catch a blow.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 I fear her not, unless she chance to fall.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span>
 God forbid that! for he’ll take vantages.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 How many children hast thou, widow? tell me.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 I think he means to beg a child of her.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb028" id="lnum-ccb028">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span>
 Nay, whip me then: he’ll rather give her two.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 Three, my most gracious lord.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span>
 You shall have four, if you’ll be ruled by him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb031" id="lnum-ccb031">♦</a>
 <span class="sd-cn">K. Edw.</span>
  ’Twere pity they should lose their father’s lands.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb032" id="lnum-ccb032">♦</a>
 <span class="sd-cn">L. Grey.</span>
  Be pitiful, dread lord, and grant it then.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Lords, give us leave: I’ll try this widow’s wit.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span> Ay, good leave have you; for you will have leave,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb035" id="lnum-ccb035">35</a>
 Till youth take leave and leave you to the crutch. <span class="sd-verseend">[<i>Glou. and Clar. retire.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Now tell me, madam, do you love your children?</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 Ay, full as dearly as I love myself.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 And would you not do much to do them good?</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 To do them good, I would sustain some harm.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">K. Edw.</span>
  Then get your husband’s lands, to do them good.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 Therefore I came unto your majesty.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 I’ll tell you how these lands are to be got.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 So shall you bind me to your highness’ service.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 What service wilt thou do me, if I give them?</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">L. Grey.</span>
  What you command, that rests in me to do.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb046" id="lnum-ccb046">♦</a>
 <span class="sd-cn">K. Edw.</span>
  But you will take exceptions to my boon.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 No, gracious lord, except I cannot do it.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Ay, but thou canst do what I mean to ask.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 Why, then I will do what your grace commands.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb050" id="lnum-ccb050">50</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span>
 He plies her hard; and much rain wears the marble.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb051" id="lnum-ccb051">♦</a>
 <span class="sd-cn">Clar.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 As red as fire! nay, then her wax must melt.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 Why stops my lord? shall I not hear my task?</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 An easy task; ’tis but to love a king.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 That’s soon perform’d, because I am a subject.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">K. Edw.</span>
  Why, then, thy husband’s lands I freely give thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb056" id="lnum-ccb056">♦</a>
 <span class="sd-cn">L. Grey.</span>
  I take my leave with many thousand thanks.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb057" id="lnum-ccb057">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span>
 The match is made; she seals it with a curt’sy.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 But stay thee, ’tis the fruits of love I mean.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 The fruits of love I mean, my loving liege.</div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">K. Edw.</span>
  Ay, but, I fear me, in another sense.</div>
<div class="dverse">What love, think’st thou, I sue so much to get?</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 My love till death, my humble thanks, my prayers;</div>
<div class="dverse">That love which virtue begs and virtue grants.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 No, by my troth, I did not mean such love.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">L. Grey.</span>
  Why, then you mean not as I thought you did.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 But now you partly may perceive my mind.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 My mind will never grant what I perceive</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb068" id="lnum-ccb068">♦</a>
 Your highness aims at, if I aim aright.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 To tell thee plain, I aim to lie with thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb070" id="lnum-ccb070">70</a>
 <span class="sd-cn">L. Grey.</span>
  To tell you plain, I had rather lie in prison.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Why, then thou shalt not have thy husband’s lands.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 Why, then mine honesty shall be my dower;</div>
<div class="dverse">For by that loss I will not purchase them.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb074" id="lnum-ccb074">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Therein thou wrong’st thy children mightily.</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">L. Grey.</span>
  Herein your highness wrongs both them and me.</div>
<div class="dverse">But, mighty lord, this merry inclination</div>
<div class="dverse">Accords not with the sadness of my suit:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb078" id="lnum-ccb078">♦</a>
 Please you dismiss me, either with ‘ay’ or ‘no.’</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Ay, if thou wilt say ‘ay’ to my request;</div>
<div class="dverse"><span class="lnum">80</span>
 No, if thou dost say ‘no’ to my demand.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 Then, no, my lord. My suit is at an end.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb082" id="lnum-ccb082">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span>
 The widow likes him not, she knits her brows.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb083" id="lnum-ccb083">♦</a>
 <span class="sd-cn">Clar.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 He is the bluntest wooer in Christendom.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb084" id="lnum-ccb084">♦</a>
 <span class="sd-cn">K. Edw.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 Her looks do argue her replete with modesty;</div>
<div class="dverse"><span class="lnum">85</span>
 Her words do show her wit incomparable;</div>
<div class="dverse">All her perfections challenge sovereignty:</div>
<div class="dverse">One way or other, she is for a king;</div>
<div class="dverse">And she shall be my love, or else my queen.—</div>
<div class="dverse">Say that King Edward take thee for his queen?</div>

<div class="dverse1"><span class="lnum">90</span>
 <span class="sd-cn">L. Grey.</span>
  ’Tis better said than done, my gracious lord:</div>
<div class="dverse">I am a subject fit to jest withal,</div>
<div class="dverse">But far unfit to be a sovereign.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Sweet widow, by my state I swear to thee</div>
<div class="dverse">I speak no more than what my soul intends;</div>
<div class="dverse"><span class="lnum">95</span>
 And that is, to enjoy thee for my love.</div>

<div class="dverse1"><span class="sd-cn">L. Grey.</span>
 And that is more than I will yield unto:</div>
<div class="dverse">I know I am too mean to be your queen,</div>
<div class="dverse">And yet too good to be your concubine.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 You cavil, widow: I did mean, my queen.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb100" id="lnum-ccb100">100</a>
 <span class="sd-cn">L. Grey.</span>
  ’Twill grieve your grace my sons should call you father.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb101" id="lnum-ccb101">♦</a>
 <span class="sd-cn">K. Edw.</span>
  No more than when my daughters call thee mother.</div>
<div class="dverse">Thou art a widow, and thou hast some children;</div>
<div class="dverse">And, by God’s mother, I, being but a bachelor,</div>
<div class="dverse">Have other some: why, ’tis a happy thing</div>
<div class="dverse"><span class="lnum">105</span>
 To be the father unto many sons.</div>
<div class="dverse">Answer no more, for thou shalt be my queen.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside to Clar.</i>]</span>
 The ghostly father now hath done his shrift.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb108" id="lnum-ccb108">♦</a>
 <span class="sd-cn">Clar.</span>
 <span class="sd-inline">[<i>Aside to Glou.</i>]</span>
 When he was made a shriver, ’twas for shift.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Brothers, you muse what chat we two have had.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb110" id="lnum-ccb110">110</a>
 <span class="sd-cn">Glou.</span>
  The widow likes it not, for she looks very sad.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 You’ld think it strange if I should marry her.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 To whom, my lord?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb112" id="lnum-ccb112">♦</a>
<span class="sd-cn">K. Edw.</span>
 <span class="i09"> </span>
 Why, Clarence, to myself.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 That would be ten days’ wonder at the least.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 That’s a day longer than a wonder lasts.</div>

<div class="dverse1"><span class="lnum">115</span>
 <span class="sd-cn">Glou.</span>
  By so much is the wonder in extremes.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Well, jest on, brothers: I can tell you both</div>
<div class="dverse">Her suit is granted for her husband’s lands.</div>

<div class="sd-entry"><i>Enter a</i> Nobleman.</div>

<div class="dverse1"><span class="sd-cn">Nob.</span>
 My gracious lord, Henry your foe is taken,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb119" id="lnum-ccb119">♦</a>
 And brought your prisoner to your palace gate.</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">K. Edw.</span>
  See that he be convey’d unto the Tower:</div>
<div class="dverse">And go we, brothers, to the man that took him,</div>
<div class="dverse">To question of his apprehension.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb123" id="lnum-ccb123">♦</a>
 Widow, go you along. Lords, use her honourably. <span class="sd-verseend">[<i>Exeunt all but Gloucester.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccb124" id="lnum-ccb124">♦</a>
 <span class="sd-cn">Glou.</span>
  Ay, Edward will use women honourably.</div>
<div class="dverse"><span class="lnum">125</span>
 Would he were wasted, marrow, bones and all,</div>
<div class="dverse">That from his loins no hopeful branch may spring,</div>
<div class="dverse">To cross me from the golden time I look for!</div>
<div class="dverse">And yet, between my soul’s desire and me—</div>
<div class="dverse">The lustful Edward’s title buried—</div>
<div class="dverse"><span class="lnum">130</span>
 Is Clarence, Henry, and his son young Edward,</div>
<div class="dverse">And all the unlook’d for issue of their bodies,</div>
<div class="dverse">To take their rooms, ere I can place myself:</div>
<div class="dverse">A cold premeditation for my purpose!</div>
<div class="dverse">Why, then, I do but dream on sovereignty;</div>
<div class="dverse"><span class="lnum">135</span>
 Like one that stands upon a promontory,</div>
<div class="dverse">And spies a far-off shore where he would tread,</div>
<div class="dverse">Wishing his foot were equal with his eye,</div>
<div class="dverse">And chides the sea that sunders him from thence,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb139" id="lnum-ccb139">♦</a>
 Saying, he’ll lade it dry to have his way:</div>
<div class="dverse"><span class="lnum">140</span>
 So do I wish the crown, being so far off;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb141" id="lnum-ccb141">♦</a>
 And so I chide the means that keeps me from it;</div>
<div class="dverse">And so I say, I’ll cut the causes off,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb143" id="lnum-ccb143">♦</a>
 Flattering me with impossibilities.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb144" id="lnum-ccb144">♦</a>
 My eye’s too quick, my heart o’erweens too much,</div>
<div class="dverse"><span class="lnum">145</span>
 Unless my hand and strength could equal them.</div>
<div class="dverse">Well, say there is no kingdom then for Richard;</div>
<div class="dverse">What other pleasure can the world afford?</div>
<div class="dverse">I’ll make my heaven in a lady’s lap,</div>
<div class="dverse">And deck my body in gay ornaments,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb150" id="lnum-ccb150">150</a>
 And witch sweet ladies with my words and looks.</div>
<div class="dverse">O miserable thought! and more unlikely</div>
<div class="dverse">Than to accomplish twenty golden crowns!</div>
<div class="dverse">Why, love forswore me in my mother’s womb:</div>
<div class="dverse">And, for I should not deal in her soft laws,</div>
<div class="dverse"><span class="lnum">155</span>
 She did corrupt frail nature with some bribe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb156" id="lnum-ccb156">♦</a>
 To shrink mine arm up like a wither’d shrub;</div>
<div class="dverse">To make an envious mountain on my back,</div>
<div class="dverse">Where sits deformity to mock my body;</div>
<div class="dverse">To shape my legs of an unequal size;</div>
<div class="dverse"><span class="lnum">160</span>
 To disproportion me in every part,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb161" id="lnum-ccb161">♦</a>
 Like to a chaos, or an unlick’d bear-whelp</div>
<div class="dverse">That carries no impression like the dam.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb163" id="lnum-ccb163">♦</a>
 And am I then a man to be beloved?</div>
<div class="dverse">O monstrous fault, to harbour such a thought!</div>
<div class="dverse"><span class="lnum">165</span>
 Then, since this earth affords no joy to me,</div>
<div class="dverse">But to command, to check, to o’erbear such</div>
<div class="dverse">As are of better person than myself,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb168" id="lnum-ccb168">♦</a>
 I’ll make my heaven to dream upon the crown,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb169" id="lnum-ccb169">♦</a>
 And, whiles I live, to account this world but hell,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb170" id="lnum-ccb170">170</a>
 Until my mis-shaped trunk that bears this head</div>
<div class="dverse">Be round impaled with a glorious crown.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb172" id="lnum-ccb172">♦</a>
 And yet I know not how to get the crown,</div>
<div class="dverse">For many lives stand between me and home:</div>
<div class="dverse">And I,—like one lost in a thorny wood,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb175" id="lnum-ccb175">175</a>
 That rends the thorns and is rent with the thorns,</div>
<div class="dverse">Seeking a way and straying from the way;</div>
<div class="dverse">Not knowing how to find the open air,</div>
<div class="dverse">But toiling desperately to find it out,—</div>
<div class="dverse">Torment myself to catch the English crown:</div>
<div class="dverse"><span class="lnum">180</span>
 And from that torment I will free myself,</div>
<div class="dverse">Or hew my way out with a bloody axe.</div>
<div class="dverse">Why, I can smile, and murder whiles I smile,</div>
<div class="dverse">And cry ‘Content’ to that which grieves my heart,</div>
<div class="dverse">And wet my cheeks with artificial tears,</div>
<div class="dverse"><span class="lnum">185</span>
 And frame my face to all occasions.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb186" id="lnum-ccb186">♦</a>
 I’ll drown more sailors than the mermaid shall;</div>
<div class="dverse">I’ll slay more gazers than the basilisk;</div>
<div class="dverse">I’ll play the orator as well as Nestor,</div>
<div class="dverse">Deceive more slily than Ulysses could,</div>
<div class="dverse"><span class="lnum">190</span>
 And, like a Sinon, take another Troy.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb191" id="lnum-ccb191">♦</a>
 I can add colours to the chameleon,</div>
<div class="dverse">Change shapes with Proteus for advantages,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb193" id="lnum-ccb193">♦</a>
 And set the murderous Machiavel to school.</div>
<div class="dverse">Can I do this, and cannot get a crown?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccb195" id="lnum-ccb195">195</a>
 Tut, were it farther off, I’ll pluck it down.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">ccc</span>
<span class="smcaps">S<span>CENE</span></span> III. <i>France. The</i> <span class="smcaps">K<span>ING’S</span></span> <i>palace</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">L<span>EWIS</span></span> <i>the French King, his sister</i> <span class="smcaps">B<span>ONA</span>,</span> <i>his Admiral, called</i> <span class="smcaps">B<span>OURBON</span>:</span>
<span class="smcaps">P<span>RINCE</span></span>
<span class="smcaps">E<span>DWARD</span>,</span>
<span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">M<span>ARGARET</span>,</span> <i>and the</i> <span class="smcaps">E<span>ARL</span></span> <span class="smmaj">OF</span>
<span class="smcaps">O<span>XFORD</span>.</span> <span class="smcaps">L<span>EWIS</span></span> <i>sits, and riseth up again</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc001" id="lnum-ccc001">♦</a>
 <span class="sd-cn">K. Lew.</span>
  Fair Queen of England, worthy Margaret,</div>
<div class="dverse">Sit down with us: it ill befits thy state</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc003" id="lnum-ccc003">♦</a>
 And birth, that thou shouldst stand while Lewis doth sit.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 No, mighty King of France: now Margaret</div>
<div class="dverse"><span class="lnum">5</span>
 Must strike her sail and learn awhile to serve</div>
<div class="dverse">Where kings command. I was, I must confess,</div>
<div class="dverse">Great Albion’s queen in former golden days:</div>
<div class="dverse">But now mischance hath trod my title down,</div>
<div class="dverse">And with dishonour laid me on the ground;</div>
<div class="dverse"><span class="lnum">10</span>
 Where I must take like seat unto my fortune,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc011" id="lnum-ccc011">♦</a>
 And to my humble seat conform myself.</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 Why, say, fair queen, whence springs this deep despair?</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 From such a cause as fills mine eyes with tears</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc014" id="lnum-ccc014">♦</a>
 And stops my tongue, while heart is drown’d in cares.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">K. Lew.</span>
  Whate’er it be, be thou still like thyself,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc016" id="lnum-ccc016">♦</a>
 And sit thee by our side: <span class="sd-inline">[<i>Seats her by him</i>]</span> yield not thy neck</div>
<div class="dverse">To fortune’s yoke, but let thy dauntless mind</div>
<div class="dverse">Still ride in triumph over all mischance.</div>
<div class="dverse">Be plain, Queen Margaret, and tell thy grief;</div>
<div class="dverse"><span class="lnum">20</span>
 It shall be eased, if France can yield relief.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc021" id="lnum-ccc021">♦</a>
 <span class="sd-cn">Q. Mar.</span>
  Those gracious words revive my drooping thoughts</div>
<div class="dverse">And give my tongue-tied sorrows leave to speak.</div>
<div class="dverse">Now, therefore, be it known to noble Lewis,</div>
<div class="dverse">That Henry, sole possessor of my love,</div>
<div class="dverse"><span class="lnum">25</span>
 Is of a king become a banish’d man,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc026" id="lnum-ccc026">♦</a>
 And forced to live in Scotland a forlorn;</div>
<div class="dverse">While proud ambitious Edward Duke of York</div>
<div class="dverse">Usurps the regal title and the seat</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc029" id="lnum-ccc029">♦</a>
 Of England’s true-anointed lawful king.</div>
<div class="dverse"><span class="lnum">30</span>
 This is the cause that I, poor Margaret,</div>
<div class="dverse">With this my son, Prince Edward, Henry’s heir,</div>
<div class="dverse">Am come to crave thy just and lawful aid;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc033" id="lnum-ccc033">♦</a>
 And if thou fail us, all our hope is done:</div>
<div class="dverse">Scotland hath will to help, but cannot help;</div>
<div class="dverse"><span class="lnum">35</span>
 Our people and our peers are both misled,</div>
<div class="dverse">Our treasure seized, our soldiers put to flight,</div>
<div class="dverse">And, as thou seest, ourselves in heavy plight.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc038" id="lnum-ccc038">♦</a>
 <span class="sd-cn">K. Lew.</span>
  Renowned queen, with patience calm the storm,</div>
<div class="dverse">While we bethink a means to break it off.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Q. Mar.</span>
  The more we stay, the stronger grows our foe.</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 The more I stay, the more I’ll succour thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc042" id="lnum-ccc042">♦</a>
 <span class="sd-cn">Q. Mar.</span>
  O, but impatience waiteth on true sorrow.</div>
<div class="dverse">And see where comes the breeder of my sorrow!</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">W<span>ARWICK</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc044" id="lnum-ccc044">♦</a>
 <span class="sd-cn">K. Lew.</span>
  What’s he approacheth boldly to our presence?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc045" id="lnum-ccc045">45</a>
 <span class="sd-cn">Q. Mar.</span>
  Our Earl of Warwick, Edward’s greatest friend.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc046" id="lnum-ccc046">♦</a>
 <span class="sd-cn">K. Lew.</span>
 Welcome, brave Warwick! What brings thee to France?
 <span class="sd-verseend">[<i>He descends. She ariseth.</i></span></div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Ay, now begins a second storm to rise;</div>
<div class="dverse">For this is he that moves both wind and tide.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 From worthy Edward, king of Albion,</div>
<div class="dverse"><span class="lnum">50</span>
 My lord and sovereign, and thy vowed friend,</div>
<div class="dverse">I come, in kindness and unfeigned love,</div>
<div class="dverse">First, to do greetings to thy royal person;</div>
<div class="dverse">And then to crave a league of amity;</div>
<div class="dverse">And lastly, to confirm that amity</div>
<div class="dverse"><span class="lnum">55</span>
 With nuptial knot, if thou vouchsafe to grant</div>
<div class="dverse">That virtuous Lady Bona, thy fair sister,</div>
<div class="dverse">To England’s king in lawful marriage.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc058" id="lnum-ccc058">♦</a>
 <span class="sd-cn">Q. Mar.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 If that go forward, Henry’s hope is done.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc059" id="lnum-ccc059">♦</a>
<span class="sd-cn">War.</span>
 <span class="sd-inline">[<i>To Bona</i>]</span>
 And, gracious madam, in our king’s behalf,</div>
<div class="dverse"><span class="lnum">60</span>
 I am commanded, with your leave and favour,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc061" id="lnum-ccc061">♦</a>
 Humbly to kiss your hand and with my tongue</div>
<div class="dverse">To tell the passion of my sovereign’s heart;</div>
<div class="dverse">Where fame, late entering at his heedful ears,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc064" id="lnum-ccc064">♦</a>
 Hath placed thy beauty’s image and thy virtue.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">Q. Mar.</span>
  King Lewis and Lady Bona, hear me speak,</div>
<div class="dverse">Before you answer Warwick. His demand</div>
<div class="dverse">Springs not from Edward’s well-meant honest love,</div>
<div class="dverse">But from deceit bred by necessity;</div>
<div class="dverse">For how can tyrants safely govern home,</div>
<div class="dverse"><span class="lnum">70</span>
 Unless abroad they purchase great alliance?</div>
<div class="dverse">To prove him tyrant this reason may suffice,</div>
<div class="dverse">That Henry liveth still; but were he dead,</div>
<div class="dverse">Yet here Prince Edward stands, King Henry’s son.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc074" id="lnum-ccc074">♦</a>
 Look, therefore, Lewis, that by this league and marriage</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc075" id="lnum-ccc075">75</a>
 Thou draw not on thy danger and dishonour;</div>
<div class="dverse">For though usurpers sway the rule awhile,</div>
<div class="dverse">Yet heavens are just, and time suppresseth wrongs.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Injurious Margaret!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc078" id="lnum-ccc078">♦</a>
<span class="sd-cn">Prince.</span>
 <span class="i09"> </span>
 And why not queen?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Because thy father Henry did usurp;</div>
<div class="dverse"><span class="lnum">80</span>
 And thou no more art prince than she is queen.</div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 Then Warwick disannuls great John of Gaunt,</div>
<div class="dverse">Which did subdue the greatest part of Spain;</div>
<div class="dverse">And, after John of Gaunt, Henry the Fourth,</div>
<div class="dverse">Whose wisdom was a mirror to the wisest;</div>
<div class="dverse"><span class="lnum">85</span>
 And, after that wise prince, Henry the Fifth,</div>
<div class="dverse">Who by his prowess conquered all France:</div>
<div class="dverse">From these our Henry lineally descends.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Oxford, how haps it, in this smooth discourse,</div>
<div class="dverse">You told not how Henry the Sixth hath lost</div>
<div class="dverse"><span class="lnum">90</span>
 All that which Henry the Fifth had gotten?</div>
<div class="dverse">Methinks these peers of France should smile at that.</div>
<div class="dverse">But for the rest, you tell a pedigree</div>
<div class="dverse">Of threescore and two years; a silly time</div>
<div class="dverse">To make prescription for a kingdom’s worth.</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">Oxf.</span>
  Why, Warwick, canst thou speak against thy liege,</div>
<div class="dverse">Whom thou obeyed’st thirty and six years,</div>
<div class="dverse">And not bewray thy treason with a blush?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Can Oxford, that did ever fence the right,</div>
<div class="dverse">Now buckler falsehood with a pedigree?</div>
<div class="dverse"><span class="lnum">100</span>
 For shame! leave Henry, and call Edward king.</div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 Call him my king by whose injurious doom</div>
<div class="dverse">My elder brother, the Lord Aubrey Vere,</div>
<div class="dverse">Was done to death? and more than so, my father,</div>
<div class="dverse">Even in the downfall of his mellow’d years,</div>
<div class="dverse"><span class="lnum">105</span>
 When nature brought him to the door of death?</div>
<div class="dverse">No, Warwick, no; while life upholds this arm,</div>
<div class="dverse">This arm upholds the house of Lancaster.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And I the house of York.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc109" id="lnum-ccc109">♦</a>
 <span class="sd-cn">K. Lew.</span>
  Queen Margaret, Prince Edward, and Oxford,</div>
<div class="dverse"><span class="lnum">110</span>
 Vouchsafe, at our request, to stand aside,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc111" id="lnum-ccc111">♦</a>
 While I use further conference with Warwick.
 <span class="sd-verseend">[<i>They stand aloof.</i></span></div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Heavens grant that Warwick’s words bewitch him not!</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 Now, Warwick, tell me, even upon thy conscience,</div>
<div class="dverse">Is Edward your true king? for I were loath</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc115" id="lnum-ccc115">115</a>
 To link with him that were not lawful chosen.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Thereon I pawn my credit and mine honour.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc117" id="lnum-ccc117">♦</a>
 <span class="sd-cn">K. Lew.</span>
  But is he gracious in the people’s eye?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 The more that Henry was unfortunate.</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 Then further, all dissembling set aside,</div>
<div class="dverse"><span class="lnum">120</span>
 Tell me for truth the measure of his love</div>
<div class="dverse">Unto our sister Bona.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 <span class="i09"> </span> Such it seems</div>
<div class="dverse">As may beseem a monarch like himself.</div>
<div class="dverse">Myself have often heard him say and swear</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc124" id="lnum-ccc124">♦</a>
 That this his love was an eternal plant,</div>
<div class="dverse"><span class="lnum">125</span>
 Whereof the root was fix’d in virtue’s ground,</div>
<div class="dverse">The leaves and fruit maintain’d with beauty’s sun,</div>
<div class="dverse">Exempt from envy, but not from disdain,</div>
<div class="dverse">Unless the Lady Bona quit his pain.</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 Now, sister, let us hear your firm resolve.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc130" id="lnum-ccc130">130</a>
 <span class="sd-cn">Bona.</span>
  Your grant, or your denial, shall be mine:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc131" id="lnum-ccc131">♦</a>
 <span class="sd-inline">[<i>To War.</i>]</span>
 Yet I confess that often ere this day,</div>
<div class="dverse">When I have heard your king’s desert recounted,</div>
<div class="dverse">Mine ear hath tempted judgment to desire.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc134" id="lnum-ccc134">♦</a>
 <span class="sd-cn">K. Lew.</span>
  Then, Warwick, thus: our sister shall be Edward’s;</div>
<div class="dverse"><span class="lnum">135</span>
 And now forthwith shall articles be drawn</div>
<div class="dverse">Touching the jointure that your king must make,</div>
<div class="dverse">Which with her dowry shall be counterpoised.</div>
<div class="dverse">Draw near, Queen Margaret, and be a witness</div>
<div class="dverse">That Bona shall be wife to the English king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc140" id="lnum-ccc140">140</a>
 <span class="sd-cn">Prince.</span>
  To Edward, but not to the English king.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Deceitful Warwick! it was thy device</div>
<div class="dverse">By this alliance to make void my suit:</div>
<div class="dverse">Before thy coming Lewis was Henry’s friend.</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 And still is friend to him and Margaret:</div>
<div class="dverse"><span class="lnum">145</span>
 But if your title to the crown be weak,</div>
<div class="dverse">As may appear by Edward’s good success,</div>
<div class="dverse">Then ’tis but reason that I be released</div>
<div class="dverse">From giving aid which late I promised.</div>
<div class="dverse">Yet shall you have all kindness at my hand</div>
<div class="dverse"><span class="lnum">150</span>
 That your estate requires and mine can yield.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Henry now lives in Scotland at his ease,</div>
<div class="dverse">Where having nothing, nothing can he lose.</div>
<div class="dverse">And as for you yourself, our quondam queen,</div>
<div class="dverse">You have a father able to maintain you;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc155" id="lnum-ccc155">155</a>
 And better ’twere you troubled him than France.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc156" id="lnum-ccc156">♦</a>
 <span class="sd-cn">Q. Mar.</span>
  Peace, impudent and shameless Warwick, peace,</div>
<div class="dverse">Proud setter up and puller down of kings!</div>
<div class="dverse">I will not hence, till, with my talk and tears,</div>
<div class="dverse">Both full of truth, I make King Lewis behold</div>
<div class="dverse"><span class="lnum">160</span>
 Thy sly conveyance and thy lord’s false love;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc161" id="lnum-ccc161">♦</a>
 For both of you are birds of selfsame feather.
 <span class="sd-verseend">[<i>Post blows a horn within.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 Warwick, this is some post to us or thee.</div>

<div class="sd-entry"><i>Enter a</i> Post.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc163" id="lnum-ccc163">♦</a>
<span class="sd-cn">Post.</span>
 <span class="sd-inline">[<i>To War.</i>]</span>
  My lord ambassador, these letters are for you,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc164" id="lnum-ccc164">♦</a>
 Sent from your brother, Marquess Montague:</div>
<div class="dverse"><span class="lnum">165</span>
 <span class="sd-inline">[<i>To Lewis</i>]</span>
  These from our king unto your majesty:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc166" id="lnum-ccc166">♦</a>
<span class="sd-inline">[<i>To Margaret</i>]</span>
 And, madam, these for you; from whom I know not.
 <span class="sd-verseend">[<i>They all read their letters.</i></span></div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 I like it well that our fair queen and mistress</div>
<div class="dverse">Smiles at her news, while Warwick frowns at his.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc169" id="lnum-ccc169">♦</a>
 <span class="sd-cn">Prince.</span>
  Nay, mark how Lewis stamps, as he were nettled:</div>
<div class="dverse"><span class="lnum">170</span>
 I hope all’s for the best.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc171" id="lnum-ccc171">♦</a>
 <span class="sd-cn">K. Lew.</span>
  Warwick, what are thy news? and yours, fair queen?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc172" id="lnum-ccc172">♦</a>
 <span class="sd-cn">Q. Mar.</span>
  Mine, such as fill my heart with unhoped joys.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Mine, full of sorrow and heart’s discontent.</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 What! has your king married the Lady Grey?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc175" id="lnum-ccc175">175</a>
 And now, to soothe your forgery and his,</div>
<div class="dverse">Sends me a paper to persuade me patience?</div>
<div class="dverse">Is this the alliance that he seeks with France?</div>
<div class="dverse">Dare he presume to scorn us in this manner?</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 I told your majesty as much before:</div>
<div class="dverse"><span class="lnum">180</span>
 This proveth Edward’s love and Warwick’s honesty.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 King Lewis, I here protest, in sight of heaven,</div>
<div class="dverse">And by the hope I have of heavenly bliss,</div>
<div class="dverse">That I am clear from this misdeed of Edward’s,</div>
<div class="dverse">No more my king, for he dishonours me,</div>
<div class="dverse"><span class="lnum">185</span>
 But most himself, if he could see his shame.</div>
<div class="dverse">Did I forget that by the house of York</div>
<div class="dverse">My father came untimely to his death?</div>
<div class="dverse">Did I let pass the abuse done to my niece?</div>
<div class="dverse">Did I impale him with the regal crown?</div>
<div class="dverse"><span class="lnum">190</span>
 Did I put Henry from his native right?</div>
<div class="dverse">And am I guerdon’d at the last with shame?</div>
<div class="dverse">Shame on himself! for my desert is honour:</div>
<div class="dverse">And to repair my honour lost for him,</div>
<div class="dverse">I here renounce him and return to Henry.</div>
<div class="dverse"><span class="lnum">195</span>
 My noble queen, let former grudges pass,</div>
<div class="dverse">And henceforth I am thy true servitor:</div>
<div class="dverse">I will revenge his wrong to Lady Bona</div>
<div class="dverse">And replant Henry in his former state.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc199" id="lnum-ccc199">♦</a>
 <span class="sd-cn">Q. Mar.</span>
  Warwick, these words have turn’d my hate to love;</div>
<div class="dverse"><span class="lnum">200</span>
 And I forgive and quite forget old faults,</div>
<div class="dverse">And joy that thou becomest King Henry’s friend.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 So much his friend, ay, his unfeigned friend,</div>
<div class="dverse">That, if King Lewis vouchsafe to furnish us</div>
<div class="dverse">With some few bands of chosen soldiers,</div>
<div class="dverse"><span class="lnum">205</span>
 I’ll undertake to land them on our coast</div>
<div class="dverse">And force the tyrant from his seat by war.</div>
<div class="dverse">’Tis not his new-made bride shall succour him:</div>
<div class="dverse">And as for Clarence, as my letters tell me,</div>
<div class="dverse">He’s very likely now to fall from him,</div>
<div class="dverse"><span class="lnum">210</span>
 For matching more for wanton lust than honour,</div>
<div class="dverse">Or than for strength and safety of our country.</div>

<div class="dverse1"><span class="sd-cn">Bona.</span>
 Dear brother, how shall Bona be revenged</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc213" id="lnum-ccc213">♦</a>
 But by thy help to this distressed queen?</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Renowned prince, how shall poor Henry live,</div>
<div class="dverse"><span class="lnum">215</span>
 Unless thou rescue him from foul despair?</div>

<div class="dverse1"><span class="sd-cn">Bona.</span>
 My quarrel and this English queen’s are one.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And mine, fair Lady Bona, joins with yours.</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 And mine with hers, and thine, and Margaret’s.</div>
<div class="dverse">Therefore at last I firmly am resolved</div>
<div class="dverse"><span class="lnum">220</span>
 You shall have aid.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Let me give humble thanks for all at once.</div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 Then, England’s messenger, return in post,</div>
<div class="dverse">And tell false Edward, thy supposed king,</div>
<div class="dverse">That Lewis of France is sending over masquers</div>
<div class="dverse"><span class="lnum">225</span>
 To revel it with him and his new bride:</div>
<div class="dverse">Thou seest what’s past, go fear thy king withal.</div>

<div class="dverse1"><span class="sd-cn">Bona.</span>
 Tell him, in hope he’ll prove a widower shortly,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc228" id="lnum-ccc228">♦</a>
 I’ll wear the willow garland for his sake.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Tell him, my mourning weeds are laid aside,</div>
<div class="dverse"><span class="lnum">230</span>
 And I am ready to put armour on.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Tell him from me that he hath done me wrong,</div>
<div class="dverse">And therefore I’ll uncrown him ere’t be long.</div>
<div class="dverse">There’s thy reward: be gone. <span class="sd-verseend">[<i>Exit Post.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc233" id="lnum-ccc233">♦</a>
 <span class="sd-cn">K. Lew.</span>
 <span class="i10"> </span> But, Warwick,</div>
<div class="dverse">Thou and Oxford, with five thousand men,</div>
<div class="dverse"><span class="lnum">235</span>
 Shall cross the seas, and bid false Edward battle;</div>
<div class="dverse">And, as occasion serves, this noble queen</div>
<div class="dverse">And prince shall follow with a fresh supply.</div>
<div class="dverse">Yet, ere thou go, but answer me one doubt,</div>
<div class="dverse">What pledge have we of thy firm loyalty?</div>

<div class="dverse1"><span class="lnum">240</span>
 <span class="sd-cn">War.</span>
  This shall assure my constant loyalty,</div>
<div class="dverse">That if our queen and this young prince agree,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc242" id="lnum-ccc242">♦</a>
 I’ll join mine eldest daughter and my joy</div>
<div class="dverse">To him forthwith in holy wedlock bands.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Yes, I agree, and thank you for your motion.</div>
<div class="dverse"><span class="lnum">245</span>
 Son Edward, she is fair and virtuous,</div>
<div class="dverse">Therefore delay not, give thy hand to Warwick;</div>
<div class="dverse">And, with thy hand, thy faith irrevocable,</div>
<div class="dverse">That only Warwick’s daughter shall be thine.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ccc249" id="lnum-ccc249">♦</a>
 <span class="sd-cn">Prince.</span>
  Yes, I accept her, for she well deserves it;</div>
<div class="dverse"><span class="lnum">250</span>
 And here, to pledge my vow, I give my hand.
 <span class="sd-verseend">[<i>He gives his hand to Warwick.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Lew.</span>
 Why stay we now? These soldiers shall be levied,</div>
<div class="dverse">And thou, Lord Bourbon, our high admiral,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc253" id="lnum-ccc253">♦</a>
 Shalt waft them over with our royal fleet.</div>
<div class="dverse">I long till Edward fall by war’s mischance,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ccc255" id="lnum-ccc255">255</a>
 For mocking marriage with a dame of France.
 <span class="sd-verseend">[<i>Exeunt all but Warwick.</i></span></div>

<div class="dverse1"><span class="sd-cn">War.</span>
 I came from Edward as ambassador,</div>
<div class="dverse">But I return his sworn and mortal foe:</div>
<div class="dverse">Matter of marriage was the charge he gave me,</div>
<div class="dverse">But dreadful war shall answer his demand.</div>
<div class="dverse"><span class="lnum">260</span>
 Had he none else to make a stale but me?</div>
<div class="dverse">Then none but I shall turn his jest to sorrow.</div>
<div class="dverse">I was the chief that raised him to the crown,</div>
<div class="dverse">And I’ll be chief to bring him down again:</div>
<div class="dverse">Not that I pity Henry’s misery,</div>
<div class="dverse"><span class="lnum">265</span>
 But seek revenge on Edward’s mockery.
 <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="section">
<h3 class="h3main">ACT IV.</h3>

<h4 class="h4main"><span class="dnavigate">cda</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>London. The
palace</i>. </h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">C<span>LARENCE</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <i>and</i> <span class="smcaps">M<span>ONTAGUE</span>.</span></div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda001" id="lnum-cda001">♦</a>
 <span class="sd-cn">Glou.</span>
  Now tell me, brother Clarence, what think you</div>
<div class="dverse">Of this new marriage with the Lady Grey?</div>
<div class="dverse">Hath not our brother made a worthy choice?</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 Alas, you know, ’tis far from hence to France;</div>
<div class="dverse"><span class="lnum">5</span>
 How could he stay till Warwick made return?</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 My lords, forbear this talk; here comes the king.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 And his well-chosen bride.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda008" id="lnum-cda008">♦</a>
 <span class="sd-cn">Clar.</span>
  I mind to tell him plainly what I think.</div>

<div class="sd-entry"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <i>attended;</i>
<span class="smcaps">L<span>ADY</span></span> <span class="smcaps">G<span>REY</span>,</span> <i>as Queen;</i>
<span class="smcaps">P<span>EMBROKE</span>,</span> <span class="smcaps">S<span>TAFFORD</span>,</span> <span class="smcaps">H<span>ASTINGS</span>,</span> <i>and others</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda009" id="lnum-cda009">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Now, brother of Clarence, how like you our choice,</div>
<div class="dverse"><span class="lnum">10</span>
 That you stand pensive, as half malcontent?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda011" id="lnum-cda011">♦</a>
 <span class="sd-cn">Clar.</span>
  As well as Lewis of France, or the Earl of Warwick,</div>
<div class="dverse">Which are so weak of courage and in judgement</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda013" id="lnum-cda013">♦</a>
 That they’ll take no offence at our abuse.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Suppose they take offence without a cause,</div>
<div class="dverse"><span class="lnum">15</span>
 They are but Lewis and Warwick: I am Edward,</div>
<div class="dverse">Your king and Warwick’s, and must have my will.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda017" id="lnum-cda017">♦</a>
 <span class="sd-cn">Glou.</span>
  And shall have your will, because our king:</div>
<div class="dverse">Yet hasty marriage seldom proveth well.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda019" id="lnum-cda019">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Yea, brother Richard, are you offended too?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda020" id="lnum-cda020">20</a>
 <span class="sd-cn">Glou.</span>
  Not I:</div>
<div class="dverse">No, God forbid that I should wish them sever’d</div>
<div class="dverse">Whom God hath join’d together; ay, and ’twere pity</div>
<div class="dverse">To sunder them that yoke so well together.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Setting your scorns and your mislike aside,</div>
<div class="dverse"><span class="lnum">25</span>
 Tell me some reason why the Lady Grey</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda026" id="lnum-cda026">♦</a>
 Should not become my wife and England’s queen.</div>
<div class="dverse">And you too, Somerset and Montague,</div>
<div class="dverse">Speak freely what you think.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda029" id="lnum-cda029">♦</a>
 <span class="sd-cn">Clar.</span>
  Then this is mine opinion: that King Lewis</div>
<div class="dverse"><span class="lnum">30</span>
 Becomes your enemy, for mocking him</div>
<div class="dverse">About the marriage of the Lady Bona.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 And Warwick, doing what you gave in charge,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda033" id="lnum-cda033">♦</a>
 Is now dishonoured by this new marriage.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 What if both Lewis and Warwick be appeased</div>
<div class="dverse"><span class="lnum">35</span>
 By such invention as I can devise?</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 Yet, to have join’d with France in such alliance</div>
<div class="dverse">Would more have strengthen’d this our commonwealth</div>
<div class="dverse">’Gainst foreign storms than any home-bred marriage.</div>

<div class="dverse1"><span class="sd-cn">Hast.</span>
 Why, knows not Montague that of itself</div>
<div class="dverse"><span class="lnum">40</span>
 England is safe, if true within itself?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda041" id="lnum-cda041">♦</a>
 <span class="sd-cn">Mont.</span>
  But the safer when ’tis back’d with France.</div>

<div class="dverse1"><span class="sd-cn">Hast.</span>
 ’Tis better using France than trusting France:</div>
<div class="dverse">Let us be back’d with God and with the seas</div>
<div class="dverse">Which He hath given for fence impregnable,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda045" id="lnum-cda045">45</a>
 And with their helps only defend ourselves;</div>
<div class="dverse">In them and in ourselves our safety lies.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 For this one speech Lord Hastings well deserves</div>
<div class="dverse">To have the heir of the Lord Hungerford.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Ay, what of that? it was my will and grant;</div>
<div class="dverse"><span class="lnum">50</span>
 And for this once my will shall stand for law.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 And yet methinks your grace hath not done well,</div>
<div class="dverse">To give the heir and daughter of Lord Scales</div>
<div class="dverse">Unto the brother of your loving bride;</div>
<div class="dverse">She better would have fitted me or Clarence:</div>
<div class="dverse"><span class="lnum">55</span>
 But in your bride you bury brotherhood.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 Or else you would not have bestow’d the heir</div>
<div class="dverse">Of the Lord Bonville on your new wife’s son,</div>
<div class="dverse">And leave your brothers to go speed elsewhere.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Alas, poor Clarence! is it for a wife</div>
<div class="dverse"><span class="lnum">60</span>
 That thou art malcontent? I will provide thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda061" id="lnum-cda061">♦</a>
 <span class="sd-cn">Clar.</span>
  In choosing for yourself, you show’d your judgement,</div>
<div class="dverse">Which being shallow, you shall give me leave</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda063" id="lnum-cda063">♦</a>
 To play the broker in mine own behalf;</div>
<div class="dverse">And to that end I shortly mind to leave you.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">K. Edw.</span>
  Leave me, or tarry, Edward will be king,</div>
<div class="dverse">And not be tied unto his brother’s will.</div>

<div class="dverse1"><span class="sd-cn">Q. Eliz.</span>
 My lords, before it pleased his majesty</div>
<div class="dverse">To raise my state to title of a queen,</div>
<div class="dverse">Do me but right, and you must all confess</div>
<div class="dverse"><span class="lnum">70</span>
 That I was not ignoble of descent;</div>
<div class="dverse">And meaner than myself have had like fortune.</div>
<div class="dverse">But as this title honours me and mine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda073" id="lnum-cda073">♦</a>
 So your dislike, to whom I would be pleasing,</div>
<div class="dverse">Doth cloud my joys with danger and with sorrow.</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">K. Edw.</span>
  My love, forbear to fawn upon their frowns:</div>
<div class="dverse">What danger or what sorrow can befall thee,</div>
<div class="dverse">So long as Edward is thy constant friend,</div>
<div class="dverse">And their true sovereign, whom they must obey?</div>
<div class="dverse">Nay, whom they shall obey, and love thee too,</div>
<div class="dverse"><span class="lnum">80</span>
 Unless they seek for hatred at my hands;</div>
<div class="dverse">Which if they do, yet will I keep thee safe,</div>
<div class="dverse">And they shall feel the vengeance of my wrath.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda083" id="lnum-cda083">♦</a>
 <span class="sd-cn">Glou.</span>
 I hear, yet say not much, but think the more.
 <span class="sd-verseend">[<i>Aside.</i></span></div>

<div class="sd-entry"><i>Enter a</i> Post.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda084" id="lnum-cda084">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Now, messenger, what letters or what news</div>
<div class="dverse"><span class="lnum">85</span>
 From France?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda086" id="lnum-cda086">♦</a>
 <span class="sd-cn">Post.</span>
  My sovereign liege, no letters; and few words,</div>
<div class="dverse">But such as I, without your special pardon,</div>
<div class="dverse">Dare not relate.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda089" id="lnum-cda089">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Go to, we pardon thee: therefore, in brief,</div>
<div class="dverse"><span class="lnum">90</span>
 Tell me their words as near as thou canst guess them.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda091" id="lnum-cda091">♦</a>
 What answer makes King Lewis unto our letters?</div>

<div class="dverse1"><span class="sd-cn">Post.</span>
 At my depart, these were his very words:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda093" id="lnum-cda093">♦</a>
 ‘Go tell false Edward, thy supposed king,</div>
<div class="dverse">That Lewis of France is sending over masquers</div>
<div class="dverse"><span class="lnum">95</span>
 To revel it with him and his new bride.’</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Is Lewis so brave? belike he thinks me Henry.</div>
<div class="dverse">But what said Lady Bona to my marriage?</div>

<div class="dverse1"><span class="sd-cn">Post.</span>
 These were her words, utter’d with mild disdain:</div>
<div class="dverse">‘Tell him, in hope he’ll prove a widower shortly,</div>
<div class="dverse"><span class="lnum">100</span>
 I’ll wear the willow garland for his sake.’</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 I blame not her, she could say little less;</div>
<div class="dverse">She had the wrong. But what said Henry’s queen?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda103" id="lnum-cda103">♦</a>
 For I have heard that she was there in place.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda104" id="lnum-cda104">♦</a>
 <span class="sd-cn">Post.</span>
  ‘Tell him,’ quoth she, ‘my mourning weeds are done,</div>
<div class="dverse"><span class="lnum">105</span>
 And I am ready to put armour on.’</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Belike she minds to play the Amazon.</div>
<div class="dverse">But what said Warwick to these injuries?</div>

<div class="dverse1"><span class="sd-cn">Post.</span>
 He, more incensed against your majesty</div>
<div class="dverse">Than all the rest, discharged me with these words:</div>
<div class="dverse"><span class="lnum">110</span>
 ‘Tell him from me that he hath done me wrong,</div>
<div class="dverse">And therefore I’ll uncrown him ere’t be long.’</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Ha! durst the traitor breathe out so proud words?</div>
<div class="dverse">Well, I will arm me, being thus forewarn’d:</div>
<div class="dverse">They shall have wars and pay for their presumption.</div>
<div class="dverse"><span class="lnum">115</span>
 But say, is Warwick friends with Margaret?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda116" id="lnum-cda116">♦</a>
 <span class="sd-cn">Post.</span>
  Ay, gracious sovereign; they are so link’d in friendship,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda117" id="lnum-cda117">♦</a>
 That young Prince Edward marries Warwick’s daughter.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda118" id="lnum-cda118">♦</a>
 <span class="sd-cn">Clar.</span>
  Belike the elder; Clarence will have the younger.</div>
<div class="dverse">Now, brother king, farewell, and sit you fast,</div>
<div class="dverse"><span class="lnum">120</span>
 For I will hence to Warwick’s other daughter;</div>
<div class="dverse">That, though I want a kingdom, yet in marriage</div>
<div class="dverse">I may not prove inferior to yourself.</div>
<div class="dverse">You that love me and Warwick, follow me.
 <span class="sd-verseend">[<i>Exit Clarence, and Somerset follows.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cda124" id="lnum-cda124">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside</i>]</span> Not I:</div>
<div class="dverse"><span class="lnum">125</span>
 My thoughts aim at a further matter; I</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda126" id="lnum-cda126">♦</a>
 Stay not for the love of Edward, but the crown.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Clarence and Somerset both gone to Warwick!</div>
<div class="dverse">Yet am I arm’d against the worst can happen;</div>
<div class="dverse">And haste is needful in this desperate case.</div>
<div class="dverse"><span class="lnum">130</span>
 Pembroke and Stafford, you in our behalf</div>
<div class="dverse">Go levy men, and make prepare for war;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cda132" id="lnum-cda132">♦</a>
 They are already, or quickly will be landed:</div>
<div class="dverse">Myself in person will straight follow you.
 <span class="sd-verseend">[<i>Exeunt Pembroke and Stafford.</i></span></div>
<div class="dverse">But, ere I go, Hastings and Montague,</div>
<div class="dverse"><span class="lnum">135</span>
 Resolve my doubt. You twain, of all the rest,</div>
<div class="dverse">Are near to Warwick by blood and by alliance:</div>
<div class="dverse">Tell me if you love Warwick more than me?</div>
<div class="dverse">If it be so, then both depart to him;</div>
<div class="dverse">I rather wish you foes than hollow friends:</div>
<div class="dverse"><span class="lnum">140</span>
 But if you mind to hold your true obedience,</div>
<div class="dverse">Give me assurance with some friendly vow,</div>
<div class="dverse">That I may never have you in suspect.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 So God help Montague as he proves true!</div>

<div class="dverse1"><span class="sd-cn">Hast.</span>
 And Hastings as he favours Edward’s cause!</div>

<div class="dverse1"><span class="lnum">145</span>
 <span class="sd-cn">K. Edw.</span>
  Now, brother Richard, will you stand by us?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ay, in despite of all that shall withstand you.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Why, so! then am I sure of victory.</div>
<div class="dverse">Now therefore let us hence; and lose no hour,</div>
<div class="dverse">Till we meet Warwick with his foreign power. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cdb</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>A plain in Warwickshire</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">W<span>ARWICK</span></span> <i>and</i> <span class="smcaps">O<span>XFORD</span>,</span> <i>with French soldiers</i>. </div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdb001" id="lnum-cdb001">♦</a>
 <span class="sd-cn">War.</span>
  Trust me, my lord, all hitherto goes well;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdb002" id="lnum-cdb002">♦</a>
 The common people by numbers swarm to us.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdb003" id="lnum-cdb003">♦</a>
 But see where Somerset and Clarence comes!</div>
<div class="dverse">Speak suddenly, my lords, are we all friends?</div>

<div class="sd-entry"><i>Enter</i>
<span class="smcaps">C<span>LARENCE</span></span>
<i>and</i> <span class="smcaps">S<span>OMERSET</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdb005" id="lnum-cdb005">5</a>
 <span class="sd-cn">Clar.</span>
  Fear not that, my lord.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then, gentle Clarence, welcome unto Warwick;</div>
<div class="dverse">And welcome, Somerset: I hold it cowardice</div>
<div class="dverse">To rest mistrustful where a noble heart</div>
<div class="dverse">Hath pawn’d an open hand in sign of love;</div>
<div class="dverse"><span class="lnum">10</span>
 Else might I think that Clarence, Edward’s brother,</div>
<div class="dverse">Were but a feigned friend to our proceedings:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdb012" id="lnum-cdb012">♦</a>
 But welcome, sweet Clarence; my daughter shall be thine.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdb013" id="lnum-cdb013">♦</a>
 And now what rests but, in night’s coverture,</div>
<div class="dverse">Thy brother being carelessly encamp’d,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdb015" id="lnum-cdb015">15</a>
 His soldiers lurking in the towns about,</div>
<div class="dverse">And but attended by a simple guard,</div>
<div class="dverse">We may surprise and take him at our pleasure?</div>
<div class="dverse">Our scouts have found the adventure very easy:</div>
<div class="dverse">That as Ulysses and stout Diomede</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdb020" id="lnum-cdb020">20</a>
 With sleight and manhood stole to Rhesus’ tents,</div>
<div class="dverse">And brought from thence the Thracian fatal steeds,</div>
<div class="dverse">So we, well cover’d with the night’s black mantle,</div>
<div class="dverse">At unawares may beat down Edward’s guard</div>
<div class="dverse">And seize himself; I say not, slaughter him,</div>
<div class="dverse"><span class="lnum">25</span>
 For I intend but only to surprise him.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdb026" id="lnum-cdb026">♦</a>
 You that will follow me to this attempt,</div>
<div class="dverse">Applaud the name of Henry with your leader. <span class="sd-verseend">[<i>They all cry</i>, ‘Henry!’</span></div>
<div class="dverse">Why, then, let’s on our way in silent sort:</div>
<div class="dverse">For Warwick and his friends, God and Saint George! <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cdc</span>
<span class="smcaps">S<span>CENE</span></span> III. <i>Edward’s camp, near Warwick</i>.</h4>

<div class="sd-schg"><i>Enter three</i> Watchmen, <i>to guard the</i> <span class="smcaps">K<span>ING’S</span></span> <i>tent</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc001" id="lnum-cdc001">♦</a>
 <span class="sd-cn">First Watch.</span>
  Come on, my masters, each man take his stand:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc002" id="lnum-cdc002">♦</a>
 The king by this is set him down to sleep.</div>

<div class="dverse1"><span class="sd-cn">Second Watch.</span>
 What, will he not to bed?</div>

<div class="dverse1"><span class="sd-cn">First Watch.</span>
 Why, no; for he hath made a solemn vow</div>
<div class="dverse"><span class="lnum">5</span>
 Never to lie and take his natural rest</div>
<div class="dverse">Till Warwick or himself be quite suppress’d.</div>

<div class="dverse1"><span class="sd-cn">Second Watch.</span>
 To-morrow then belike shall be the day,</div>
<div class="dverse">If Warwick be so near as men report.</div>

<div class="dverse1"><span class="sd-cn">Third Watch.</span>
 But say, I pray, what nobleman is that</div>
<div class="dverse"><span class="lnum">10</span>
 That with the king here resteth in his tent?</div>

<div class="dverse1"><span class="sd-cn">First Watch.</span>
 ’Tis the Lord Hastings, the king’s chiefest friend.</div>

<div class="dverse1"><span class="sd-cn">Third Watch.</span>
 O, is it so? But why commands the king</div>
<div class="dverse">That his chief followers lodge in towns about him,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc014" id="lnum-cdc014">♦</a>
 While he himself keeps in the cold field?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc015" id="lnum-cdc015">15</a>
 <span class="sd-cn">Second Watch.</span>
  ’Tis the more honour, because more dangerous.</div>

<div class="dverse1"><span class="sd-cn">Third Watch.</span>
 Ay, but give me worship and quietness;</div>
<div class="dverse">I like it better than a dangerous honour.</div>
<div class="dverse">If Warwick knew in what estate he stands,</div>
<div class="dverse">’Tis to be doubted he would waken him.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">First Watch.</span>
  Unless our halberds did shut up his passage.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc021" id="lnum-cdc021">♦</a>
 <span class="sd-cn">Second Watch.</span>
  Ay, wherefore else guard we his royal tent,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc022" id="lnum-cdc022">♦</a>
 But to defend his person from night-foes?</div>

<div class="sd-entry"><i>Enter</i>
<span class="smcaps">W<span>ARWICK</span>,</span>
<span class="smcaps">C<span>LARENCE</span>,</span>
<span class="smcaps">O<span>XFORD</span>,</span>
<span class="smcaps">S<span>OMERSET</span>,</span> <i>and French soldiers, silent all</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc023" id="lnum-cdc023">♦</a>
 <span class="sd-cn">War.</span>
  This is his tent; and see where stand his guard.</div>
<div class="dverse">Courage, my masters! honour now or never!</div>
<div class="dverse"><span class="lnum">25</span>
 But follow me, and Edward shall be ours.</div>

<div class="dverse1"><span class="sd-cn">First Watch.</span>
 Who goes there?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc027" id="lnum-cdc027">♦</a>
 <span class="sd-cn">Second Watch.</span>
 Stay, or thou diest!
 <span class="sd-verseend">[<i>Warwick and the rest cry all</i>,
 ‘Warwick! Warwick!’ <i>and set upon the Guard, who fly, crying</i>,
 ‘Arm! arm!’ <i>Warwick and the rest following them.</i></span></div>

<div class="sd-entry"><i>The drum playing and trumpet sounding, re-enter</i> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <i>and the rest, bringing the</i> <span class="smcaps">K<span>ING</span></span> <i>out in his gown, sitting in a chair.</i> <span class="smcaps">R<span>ICHARD</span></span>
<i>and</i> <span class="smcaps">H<span>ASTINGS</span></span> <i>fly over the stage</i>.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 What are they that fly there?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc029" id="lnum-cdc029">♦</a>
 <span class="sd-cn">War.</span>
  Richard and Hastings: let them go; here is</div>
<div class="dverse">The duke.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc030" id="lnum-cdc030">30</a>
 <span class="sd-cn">K. Edw.</span>
  The duke! Why, Warwick, when we parted,</div>
<div class="dverse">Thou call’dst me king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc031" id="lnum-cdc031">♦</a>
 <span class="sd-cn">War.</span>
 <span class="i09"> </span> Ay, but the case is alter’d:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc032" id="lnum-cdc032">♦</a>
 When you disgraced me in my embassade,</div>
<div class="dverse">Then I degraded you from being king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc034" id="lnum-cdc034">♦</a>
 And come now to create you Duke of York.</div>
<div class="dverse"><span class="lnum">35</span>
 Alas! how should you govern any kingdom,</div>
<div class="dverse">That know not how to use ambassadors,</div>
<div class="dverse">Nor how to be contented with one wife,</div>
<div class="dverse">Nor how to use your brothers brotherly,</div>
<div class="dverse">Nor how to study for the people’s welfare,</div>
<div class="dverse"><span class="lnum">40</span>
 Nor how to shroud yourself from enemies?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdc041" id="lnum-cdc041">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Yea, brother of Clarence, art thou here too?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc042" id="lnum-cdc042">♦</a>
 Nay, then I see that Edward needs must down.</div>
<div class="dverse">Yet, Warwick, in despite of all mischance,</div>
<div class="dverse">Of thee thyself and all thy complices,</div>
<div class="dverse"><span class="lnum">45</span>
 Edward will always bear himself as king:</div>
<div class="dverse">Though fortune’s malice overthrow my state,</div>
<div class="dverse">My mind exceeds the compass of her wheel.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then, for his mind, be Edward England’s king: <span class="sd-verseend">[<i>Takes off his crown.</i></span></div>
<div class="dverse">But Henry now shall wear the English crown,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc050" id="lnum-cdc050">50</a>
 And be true king indeed, thou but the shadow.</div>
<div class="dverse">My Lord of Somerset, at my request,</div>
<div class="dverse">See that forthwith Duke Edward be convey’d</div>
<div class="dverse">Unto my brother, Archbishop of York.</div>
<div class="dverse">When I have fought with Pembroke and his fellows,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc055" id="lnum-cdc055">55</a>
 I’ll follow you, and tell what answer</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc056" id="lnum-cdc056">♦</a>
 Lewis and the Lady Bona send to him.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc057" id="lnum-cdc057">♦</a>
 Now, for a while farewell, good Duke of York.
 <span class="sd-verseend">[<i>They lead him out forcibly.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 What fates impose, that men must needs abide;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc059" id="lnum-cdc059">♦</a>
 It boots not to resist both wind and tide.
 <span class="sd-verseend">[<i>Exit, guarded.</i></span></div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">Oxf.</span>
  What now remains, my lords, for us to do</div>
<div class="dverse">But march to London with our soldiers?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Ay, that’s the first thing that we have to do;</div>
<div class="dverse">To free king Henry from imprisonment</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdc064" id="lnum-cdc064">♦</a>
 And see him seated in the regal throne. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cdd</span>
<span class="smcaps">S<span>CENE</span></span> IV. <i>London. The palace</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">E<span>LIZABETH</span></span> <i>and</i> <span class="smcaps">R<span>IVERS</span>.</span> </div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdd001" id="lnum-cdd001">♦</a>
 <span class="sd-cn">Riv.</span>
  Madam, what makes you in this sudden change?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdd002" id="lnum-cdd002">♦</a>
 <span class="sd-cn">Q. Eliz.</span>
  Why, brother Rivers, are you yet to learn</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdd003" id="lnum-cdd003">♦</a>
 What late misfortune is befall’n King Edward?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdd004" id="lnum-cdd004">♦</a>
 <span class="sd-cn">Riv.</span>
  What! loss of some pitch’d battle against Warwick?</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">Q. Eliz.</span>
  No, but the loss of his own royal person.</div>

<div class="dverse1"><span class="sd-cn">Riv.</span>
 Then is my sovereign slain?</div>

<div class="dverse1"><span class="sd-cn">Q. Eliz.</span>
 Ay, almost slain, for he is taken prisoner,</div>
<div class="dverse">Either betray’d by falsehood of his guard</div>
<div class="dverse">Or by his foe surprised at unawares:</div>
<div class="dverse"><span class="lnum">10</span>
 And, as I further have to understand,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdd011" id="lnum-cdd011">♦</a>
 Is new committed to the Bishop of York,</div>
<div class="dverse">Fell Warwick’s brother and by that our foe.</div>

<div class="dverse1"><span class="sd-cn">Riv.</span>
 These news I must confess are full of grief;</div>
<div class="dverse">Yet, gracious madam, bear it as you may:</div>
<div class="dverse"><span class="lnum">15</span>
 Warwick may lose, that now hath won the day.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdd016" id="lnum-cdd016">♦</a>
 <span class="sd-cn">Q. Eliz.</span>
  Till then fair hope must hinder life’s decay.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdd017" id="lnum-cdd017">♦</a>
 And I the rather wean me from despair</div>
<div class="dverse">For love of Edward’s offspring in my womb:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdd019" id="lnum-cdd019">♦</a>
 This is it that makes me bridle passion</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdd020" id="lnum-cdd020">20</a>
 And bear with mildness my misfortune’s cross;</div>
<div class="dverse">Ay, ay, for this I draw in many a tear</div>
<div class="dverse">And stop the rising of blood-sucking sighs,</div>
<div class="dverse">Lest with my sighs or tears I blast or drown</div>

<div class="dverse">King Edward’s fruit, true heir to the English crown.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdd025" id="lnum-cdd025">25</a>
 <span class="sd-cn">Riv.</span>
  But, madam, where is Warwick then become?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdd026" id="lnum-cdd026">♦</a>
 <span class="sd-cn">Q. Eliz.</span>
  I am inform’d that he comes towards London,</div>
<div class="dverse">To set the crown once more on Henry’s head:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdd028" id="lnum-cdd028">♦</a>
 Guess thou the rest; King Edward’s friends must down,</div>
<div class="dverse">But, to prevent the tyrant’s violence,—</div>
<div class="dverse"><span class="lnum">30</span>
 For trust not him that hath once broken faith,—</div>
<div class="dverse">I’ll hence forthwith unto the sanctuary,</div>
<div class="dverse">To save at least the heir of Edward’s right:</div>
<div class="dverse">There shall I rest secure from force and fraud.</div>
<div class="dverse">Come, therefore, let us fly while we may fly:</div>
<div class="dverse"><span class="lnum">35</span>
 If Warwick take us we are sure to die.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cde</span>
<span class="smcaps">S<span>CENE</span></span> V. <i>A park near Middleham Castle in Yorkshire</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">G<span>LOUCESTER</span>,</span>
<span class="smcaps">L<span>ORD</span></span> <span class="smcaps">H<span>ASTINGS</span>,</span> <i>and</i>
<span class="smcaps">S<span>IR</span></span> <span class="smcaps">W<span>ILLIAM</span></span> <span class="smcaps">S<span>TANLEY</span>.</span></div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cde001" id="lnum-cde001">♦</a>
 <span class="sd-cn">Glou.</span>
  Now, my Lord Hastings and Sir William Stanley,</div>
<div class="dverse">Leave off to wonder why I drew you hither,</div>
<div class="dverse">Into this chiefest thicket of the park.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cde004" id="lnum-cde004">♦</a>
 Thus stands the case: you know our king, my brother,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cde005" id="lnum-cde005">5</a>
 Is prisoner to the bishop here, at whose hands</div>
<div class="dverse">He hath good usage and great liberty,</div>
<div class="dverse">And, often but attended with weak guard,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cde008" id="lnum-cde008">♦</a>
 Comes hunting this way to disport himself.</div>
<div class="dverse">I have advertised him by secret means</div>
<div class="dverse"><span class="lnum">10</span>
 That if about this hour he make this way</div>
<div class="dverse">Under the colour of his usual game,</div>
<div class="dverse">He shall here find his friends with horse and men</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cde013" id="lnum-cde013">♦</a>
 To set him free from his captivity.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span></span> <i>and a</i> Huntsman <i>with him</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cde014" id="lnum-cde014">♦</a>
 <span class="sd-cn">Hunt.</span>
  This way, my lord; for this way lies the game.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cde015" id="lnum-cde015">15</a>
 <span class="sd-cn">K. Edw.</span>
  Nay, this way, man: see where the huntsmen stand.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cde016" id="lnum-cde016">♦</a>
 Now, brother of Gloucester, Lord Hastings, and the rest,</div>
<div class="dverse">Stand you thus close, to steal the bishop’s deer?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Brother, the time and case requireth haste:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cde019" id="lnum-cde019">♦</a>
 Your horse stands ready at the park-corner.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 But whither shall we then?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cde020" id="lnum-cde020">20</a>
 <span class="sd-cn">Hast.</span>
 <span class="i16"> </span> To Lynn, my lord,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cde021" id="lnum-cde021">♦</a>
 And ship from thence to Flanders.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cde022" id="lnum-cde022">♦</a>
 <span class="sd-cn">Glou.</span>
  Well guess’d, believe me; for that was my meaning.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Stanley, I will requite thy forwardness.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 But wherefore stay we? ’tis no time to talk.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cde025" id="lnum-cde025">25</a>
 <span class="sd-cn">K. Edw.</span>
  Huntsman, what say’st thou? wilt thou go along?</div>

<div class="dverse1"><span class="sd-cn">Hunt.</span>
 Better do so than tarry and be hang’d.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cde027" id="lnum-cde027">♦</a>
 <span class="sd-cn">Glou.</span>
  Come then, away; let’s ha’ no more ado.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cde028" id="lnum-cde028">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Bishop, farewell: shield thee from Warwick’s frown;</div>
<div class="dverse">And pray that I may repossess the crown. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cdf</span>
<span class="smcaps">S<span>CENE</span></span> VI. <i>London. The Tower</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span>,</span> <span class="smcaps">C<span>LARENCE</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <i>young</i>
<span class="smcaps">R<span>ICHMOND</span>,</span>
<span class="smcaps">O<span>XFORD</span>,</span> <span class="smcaps">M<span>ONTAGUE</span>,</span> <i>and</i> Lieutenant of the Tower.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdf001" id="lnum-cdf001">♦</a>
 <span class="sd-cn">K. Hen.</span>
  Master lieutenant, now that God and friends</div>
<div class="dverse">Have shaken Edward from the regal seat,</div>
<div class="dverse">And turn’d my captive state to liberty,</div>
<div class="dverse">My fear to hope, my sorrows unto joys,</div>
<div class="dverse"><span class="lnum">5</span>
 At our enlargement what are thy due fees?</div>

<div class="dverse1"><span class="sd-cn">Lieu.</span>
 Subjects may challenge nothing of their sovereigns;</div>
<div class="dverse">But if an humble prayer may prevail,</div>
<div class="dverse">I then crave pardon of your majesty.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 For what, lieutenant? for well using me?</div>
<div class="dverse"><span class="lnum">10</span>
 Nay, be thou sure I’ll well requite thy kindness,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdf011" id="lnum-cdf011">♦</a>
 For that it made my imprisonment a pleasure;</div>
<div class="dverse">Ay, such a pleasure as incaged birds</div>
<div class="dverse">Conceive when after many moody thoughts</div>
<div class="dverse">At last by notes of household harmony</div>
<div class="dverse"><span class="lnum">15</span>
 They quite forget their loss of liberty.</div>
<div class="dverse">But, Warwick, after God, thou set’st me free,</div>
<div class="dverse">And chiefly therefore I thank God and thee;</div>
<div class="dverse">He was the author, thou the instrument.</div>
<div class="dverse">Therefore, that I may conquer fortune’s spite</div>
<div class="dverse"><span class="lnum">20</span>
 By living low, where fortune cannot hurt me,</div>
<div class="dverse">And that the people of this blessed land</div>
<div class="dverse">May not be punish’d with my thwarting stars,</div>
<div class="dverse">Warwick, although my head still wear the crown,</div>
<div class="dverse">I here resign my government to thee,</div>
<div class="dverse"><span class="lnum">25</span>
 For thou art fortunate in all thy deeds.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Your grace hath still been famed for virtuous;</div>
<div class="dverse">And now may seem as wise as virtuous,</div>
<div class="dverse">By spying and avoiding fortune’s malice,</div>
<div class="dverse">For few men rightly temper with the stars:</div>
<div class="dverse"><span class="lnum">30</span>
 Yet in this one thing let me blame your grace,</div>
<div class="dverse">For choosing me when Clarence is in place.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 No, Warwick, thou art worthy of the sway,</div>
<div class="dverse">To whom the heavens in thy nativity</div>
<div class="dverse">Adjudged an olive branch and laurel crown,</div>
<div class="dverse"><span class="lnum">35</span>
 As likely to be blest in peace and war;</div>
<div class="dverse">And therefore I yield thee my free consent.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And I choose Clarence only for protector.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Warwick and Clarence, give me both your hands:</div>
<div class="dverse">Now join your hands, and with your hands your hearts,</div>
<div class="dverse"><span class="lnum">40</span>
 That no dissension hinder government:</div>
<div class="dverse">I make you both protectors of this land,</div>
<div class="dverse">While I myself will lead a private life</div>
<div class="dverse">And in devotion spend my latter days,</div>
<div class="dverse">To sin’s rebuke and my Creator’s praise.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">War.</span>
  What answers Clarence to his sovereign’s will?</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 That he consents, if Warwick yield consent;</div>
<div class="dverse">For on thy fortune I repose myself.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Why, then, though loath, yet must I be content:</div>
<div class="dverse">We’ll yoke together, like a double shadow</div>
<div class="dverse"><span class="lnum">50</span>
 To Henry’s body, and supply his place;</div>
<div class="dverse">I mean, in bearing weight of government,</div>
<div class="dverse">While he enjoys the honour and his ease.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdf053" id="lnum-cdf053">♦</a>
 And, Clarence, now then it is more than needful</div>
<div class="dverse">Forthwith that Edward be pronounced a traitor,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdf055" id="lnum-cdf055">55</a>
 And all his lands and goods be confiscate.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdf056" id="lnum-cdf056">♦</a>
 <span class="sd-cn">Clar.</span>
  What else? and that succession be determined.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Ay, therein Clarence shall not want his part.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdf058" id="lnum-cdf058">♦</a>
 <span class="sd-cn">K. Hen.</span>
  But, with the first of all your chief affairs,</div>
<div class="dverse">Let me entreat, for I command no more,</div>
<div class="dverse"><span class="lnum">60</span>
 That Margaret your queen and my son Edward</div>
<div class="dverse">Be sent for, to return from France with speed;</div>
<div class="dverse">For, till I see them here, by doubtful fear</div>
<div class="dverse">My joy of liberty is half eclipsed.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 It shall be done, my sovereign, with all speed.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">K. Hen.</span>
  My Lord of Somerset, what youth is that,</div>
<div class="dverse">Of whom you seem to have so tender care?</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 My liege, it is young Henry, earl of Richmond.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdf068" id="lnum-cdf068">♦</a>
 <span class="sd-cn">K. Hen.</span>
 Come hither, England’s hope.
 <span class="sd-inline">[<i>Lays his hand on his head</i>]</span> If secret powers</div>
<div class="dverse">Suggest but truth to my divining thoughts,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdf070" id="lnum-cdf070">70</a>
 This pretty lad will prove our country’s bliss.</div>
<div class="dverse">His looks are full of peaceful majesty,</div>
<div class="dverse">His head by nature framed to wear a crown,</div>
<div class="dverse">His hand to wield a sceptre, and himself</div>
<div class="dverse">Likely in time to bless a regal throne.</div>
<div class="dverse"><span class="lnum">75</span>
 Make much of him, my lords, for this is he</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdf076" id="lnum-cdf076">♦</a>
 Must help you more than you are hurt by me.</div>

<div class="sd-entry"><i>Enter a</i> Post.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdf077" id="lnum-cdf077">♦</a>
 <span class="sd-cn">War.</span>
  What news, my friend?</div>

<div class="dverse1"><span class="sd-cn">Post.</span>
 That Edward is escaped from your brother,</div>
<div class="dverse">And fled, as he hears since, to Burgundy.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">War.</span>
  Unsavoury news! but how made he escape?</div>

<div class="dverse1"><span class="sd-cn">Post.</span>
 He was convey’d by Richard duke of Gloucester</div>
<div class="dverse">And the Lord Hastings, who attended him</div>
<div class="dverse">In secret ambush on the forest side</div>
<div class="dverse">And from the bishop’s huntsmen rescued him;</div>
<div class="dverse"><span class="lnum">85</span>
 For hunting was his daily exercise.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 My brother was too careless of his charge.</div>
<div class="dverse">But let us hence, my sovereign, to provide</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdf088" id="lnum-cdf088">♦</a>
 A salve for any sore that may betide. <span class="sd-verseend">[<i>Exeunt all but Somerset, Richmond, and Oxford.</i></span></div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 My lord, I like not of this flight of Edward’s;</div>
<div class="dverse"><span class="lnum">90</span>
 For doubtless Burgundy will yield him help,</div>
<div class="dverse">And we shall have more wars before’t be long.</div>
<div class="dverse">As Henry’s late presaging prophecy</div>
<div class="dverse">Did glad my heart with hope of this young Richmond,</div>
<div class="dverse">So doth my heart misgive me, in these conflicts</div>
<div class="dverse"><span class="lnum">95</span>
 What may befall him, to his harm and ours:</div>
<div class="dverse">Therefore, Lord Oxford, to prevent the worst,</div>
<div class="dverse">Forthwith we’ll send him hence to Brittany,</div>
<div class="dverse">Till storms be past of civil enmity.</div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 Ay, for if Edward repossess the crown,</div>
<div class="dverse"><span class="lnum">100</span>
 ’Tis like that Richmond with the rest shall down.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 It shall be so; he shall to Brittany.</div>
<div class="dverse">Come, therefore, let’s about it speedily. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cdg</span>
<span class="smcaps">S<span>CENE</span></span> VII. <i>Before York</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">H<span>ASTINGS</span>,</span> <i>and</i> Soldiers.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg001" id="lnum-cdg001">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Now, brother Richard, Lord Hastings, and the rest,</div>
<div class="dverse">Yet thus far fortune maketh us amends,</div>
<div class="dverse">And says that once more I shall interchange</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg004" id="lnum-cdg004">♦</a>
 My waned state for Henry’s regal crown.</div>
<div class="dverse"><span class="lnum">5</span>
 Well have we pass’d and now repass’d the seas</div>
<div class="dverse">And brought desired help from Burgundy:</div>
<div class="dverse">What then remains, we being thus arrived</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg008" id="lnum-cdg008">♦</a>
 From Ravenspurgh haven before the gates of York,</div>
<div class="dverse">But that we enter, as into our dukedom?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg010" id="lnum-cdg010">10</a>
 <span class="sd-cn">Glou.</span>
  The gates made fast! Brother, I like not this;</div>
<div class="dverse">For many men that stumble at the threshold</div>
<div class="dverse">Are well foretold that danger lurks within.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Tush, man, abodements must not now affright us:</div>
<div class="dverse">By fair or foul means we must enter in,</div>
<div class="dverse"><span class="lnum">15</span>
 For hither will our friends repair to us.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg016" id="lnum-cdg016">♦</a>
 <span class="sd-cn">Hast.</span>
  My liege, I’ll knock once more to summon them.</div>

<div class="sd-entry"><i>Enter, on the walls, the</i> Mayor of York <i>and his Brethren</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg017" id="lnum-cdg017">♦</a>
 <span class="sd-cn">May.</span>
  My lords, we were forewarned of your coming,</div>
<div class="dverse">And shut the gates for safety of ourselves;</div>
<div class="dverse">For now we owe allegiance unto Henry.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">K. Edw.</span>
  But, master mayor, if Henry be your king,</div>
<div class="dverse">Yet Edward at the least is Duke of York.</div>

<div class="dverse1"><span class="sd-cn">May.</span>
 True, my good lord; I know you for no less.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Why, and I challenge nothing but my dukedom,</div>
<div class="dverse">As being well content with that alone.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg025" id="lnum-cdg025">25</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 But when the fox hath once got in his nose,</div>
<div class="dverse">He’ll soon find means to make the body follow.</div>

<div class="dverse1"><span class="sd-cn">Hast.</span>
 Why, master mayor, why stand you in a doubt?</div>
<div class="dverse">Open the gates; we are King Henry’s friends.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg029" id="lnum-cdg029">♦</a>
 <span class="sd-cn">May.</span>
 Ay, say you so? the gates shall then be open’d. <span class="sd-verseend">[<i>They descend.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg030" id="lnum-cdg030">30</a>
 <span class="sd-cn">Glou.</span>
  A wise stout captain, and soon persuaded!</div>

<div class="dverse1"><span class="sd-cn">Hast.</span>
 The good old man would fain that all were well,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg032" id="lnum-cdg032">♦</a>
 So ’twere not ’long of him; but being enter’d,</div>
<div class="dverse">I doubt not, I, but we shall soon persuade</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg034" id="lnum-cdg034">♦</a>
 Both him and all his brothers unto reason.</div>

<div class="sd-entry"><i>Enter the</i> Mayor <i>and two</i> Aldermen, <i>below</i>.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">K. Edw.</span>
  So, master mayor: these gates must not be shut</div>
<div class="dverse">But in the night or in the time of war.</div>
<div class="dverse">What! fear not, man, but yield me up the keys; <span class="sd-verseend">[<i>Takes his keys.</i></span></div>
<div class="dverse">For Edward will defend the town and thee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg039" id="lnum-cdg039">♦</a>
 And all those friends that deign to follow me.</div>

<div class="sd-entry"><i>March. Enter</i> <span class="smcaps">M<span>ONTGOMERY</span>,</span> <i>with drum and soldiers</i>.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Glou.</span>
  Brother, this is Sir John Montgomery,</div>
<div class="dverse">Our trusty friend, unless I be deceived.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Welcome, Sir John! But why come you in arms?</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 To help King Edward in his time of storm,</div>
<div class="dverse">As every loyal subject ought to do.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg045" id="lnum-cdg045">45</a>
 <span class="sd-cn">K. Edw.</span>
  Thanks, good Montgomery; but we now forget</div>
<div class="dverse">Our title to the crown and only claim</div>
<div class="dverse">Our dukedom till God please to send the rest.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 Then fare you well, for I will hence again:</div>
<div class="dverse">I came to serve a king and not a duke.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg050" id="lnum-cdg050">50</a>
 Drummer, strike up, and let us march away. <span class="sd-verseend">[<i>The drum begins to march.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Nay, stay, Sir John, awhile, and we’ll debate</div>
<div class="dverse">By what safe means the crown may be recover’d.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 What talk you of debating? in few words,</div>
<div class="dverse">If you’ll not here proclaim yourself our king,</div>
<div class="dverse"><span class="lnum">55</span>
 I’ll leave you to your fortune and be gone</div>
<div class="dverse">To keep them back that come to succour you:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg057" id="lnum-cdg057">♦</a>
 Why shall we fight, if you pretend no title?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Why, brother, wherefore stand you on nice points?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg059" id="lnum-cdg059">♦</a>
 <span class="sd-cn">K. Edw.</span>
  When we grow stronger, then we’ll make our claim:</div>
<div class="dverse"><span class="lnum">60</span>
 Till then, ’tis wisdom to conceal our meaning.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg061" id="lnum-cdg061">♦</a>
 <span class="sd-cn">Hast.</span>
  Away with scrupulous wit! now arms must rule.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 And fearless minds climb soonest unto crowns.</div>
<div class="dverse">Brother, we will proclaim you out of hand;</div>
<div class="dverse">The bruit thereof will bring you many friends.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">K. Edw.</span>
  Then be it as you will; for ’tis my right,</div>
<div class="dverse">And Henry but usurps the diadem.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 Ay, now my sovereign speaketh like himself;</div>
<div class="dverse">And now will I be Edward’s champion.</div>

<div class="dverse1"><span class="sd-cn">Hast.</span>
 Sound trumpet; Edward shall be here proclaim’d:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg070" id="lnum-cdg070">70</a>
 Come, fellow-soldier, make thou proclamation. <span class="sd-verseend">[<i>Flourish.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg071" id="lnum-cdg071">♦</a>
 <span class="sd-cn">Sold.</span>
  Edward the Fourth, by the grace of God, king</div>
<div class="dverse">of England and France, and lord of Ireland, &amp;c.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 And whosoe’er gainsays King Edward’s right,</div>
<div class="dverse">By this I challenge him to single fight. <span class="sd-verseend">[<i>Throws down his gauntlet.</i></span></div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">All.</span>
  Long live Edward the Fourth!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdg076" id="lnum-cdg076">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Thanks, brave Montgomery; and thanks unto you all:</div>
<div class="dverse">If fortune serve me, I’ll requite this kindness.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg078" id="lnum-cdg078">♦</a>
 Now, for this night, let’s harbour here in York;</div>
<div class="dverse">And when the morning sun shall raise his car</div>
<div class="dverse"><span class="lnum">80</span>
 Above the border of this horizon,</div>
<div class="dverse">We’ll forward towards Warwick and his mates;</div>
<div class="dverse">For well I wot that Henry is no soldier.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdg083" id="lnum-cdg083">♦</a>
 Ah, froward Clarence! how evil it beseems thee,</div>
<div class="dverse">To flatter Henry and forsake thy brother!</div>
<div class="dverse"><span class="lnum">85</span>
 Yet, as we may, we’ll meet both thee and Warwick.</div>
<div class="dverse">Come on, brave soldiers: doubt not of the day,</div>
<div class="dverse">And, that once gotten, doubt not of large pay. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cdh</span>
<span class="smcaps">S<span>CENE</span></span> VIII. <i>London. The palace</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span>,</span> <span class="smcaps">W<span>ARWICK</span>,</span> <span class="smcaps">M<span>ONTAGUE</span>,</span> <span class="smcaps">C<span>LARENCE</span>,</span> <span class="smcaps">E<span>XETER</span>,</span> <i>and</i> <span class="smcaps">O<span>XFORD</span>.</span></div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdh001" id="lnum-cdh001">♦</a>
 <span class="sd-cn">War.</span>
  What counsel, lords? Edward from Belgia,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh002" id="lnum-cdh002">♦</a>
 With hasty Germans and blunt Hollanders,</div>
<div class="dverse">Hath pass’d in safety through the narrow seas,</div>
<div class="dverse">And with his troops doth march amain to London;</div>
<div class="dverse"><span class="lnum">5</span>
 And many giddy people flock to him.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Let’s levy men, and beat him back again.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 A little fire is quickly trodden out;</div>
<div class="dverse">Which, being suffer’d, rivers cannot quench.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 In Warwickshire I have true-hearted friends,</div>
<div class="dverse"><span class="lnum">10</span>
 Not mutinous in peace, yet bold in war;</div>
<div class="dverse">Those will I muster up: and thou, son Clarence,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh012" id="lnum-cdh012">♦</a>
 Shalt stir up in Suffolk, Norfolk and in Kent,</div>
<div class="dverse">The knights and gentlemen to come with thee:</div>
<div class="dverse">Thou, brother Montague, in Buckingham,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh015" id="lnum-cdh015">15</a>
 Northampton and in Leicestershire, shalt find</div>
<div class="dverse">Men well inclined to hear what thou command’st:</div>
<div class="dverse">And thou, brave Oxford, wondrous well beloved,</div>
<div class="dverse">In Oxfordshire shalt muster up thy friends.</div>
<div class="dverse">My sovereign, with the loving citizens,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh020" id="lnum-cdh020">20</a>
 Like to his island girt in with the ocean,</div>
<div class="dverse">Or modest Dian circled with her nymphs,</div>
<div class="dverse">Shall rest in London till we come to him.</div>
<div class="dverse">Fair lords, take leave and stand not to reply.</div>
<div class="dverse">Farewell, my sovereign.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">K. Hen.</span>
  Farewell, my Hector, and my Troy’s true hope.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 In sign of truth, I kiss your highness’ hand.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Well-minded Clarence, be thou fortunate!</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 Comfort, my lord; and so I take my leave.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdh029" id="lnum-cdh029">♦</a>
 <span class="sd-cn">Oxf.</span>
  And thus I seal my truth, and bid adieu.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">K. Hen.</span>
  Sweet Oxford, and my loving Montague,</div>
<div class="dverse">And all at once, once more a happy farewell.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdh032" id="lnum-cdh032">♦</a>
 <span class="sd-cn">War.</span>
 Farewell, sweet lords: let’s meet at Coventry. <span class="sd-verseend">[<i>Exeunt all but King Henry and Exeter.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Here at the palace will I rest awhile.</div>
<div class="dverse">Cousin of Exeter, what thinks your lordship?</div>
<div class="dverse"><span class="lnum">35</span>
 Methinks the power that Edward hath in field</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh036" id="lnum-cdh036">♦</a>
 Should not be able to encounter mine.</div>

<div class="dverse1"><span class="sd-cn">Exe.</span>
 The doubt is that he will seduce the rest.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdh038" id="lnum-cdh038">♦</a>
 <span class="sd-cn">K. Hen.</span>
  That’s not my fear; my meed hath got me fame:</div>
<div class="dverse">I have not stopp’d mine ears to their demands,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh040" id="lnum-cdh040">40</a>
 Nor posted off their suits with slow delays;</div>
<div class="dverse">My pity hath been balm to heal their wounds,</div>
<div class="dverse">My mildness hath allay’d their swelling griefs,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh043" id="lnum-cdh043">♦</a>
 My mercy dried their water-flowing tears;</div>
<div class="dverse">I have not been desirous of their wealth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh045" id="lnum-cdh045">45</a>
 Nor much oppress’d them with great subsidies,</div>
<div class="dverse">Nor forward of revenge, though they much err’d:</div>
<div class="dverse">Then why should they love Edward more than me?</div>
<div class="dverse">No, Exeter, these graces challenge grace:</div>
<div class="dverse">And when the lion fawns upon the lamb,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh050" id="lnum-cdh050">50</a>
 The lamb will never cease to follow him.
 <span class="sd-verseend">[<i>Shout within</i>, ‘A Lancaster! A Lancaster!’</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cdh051" id="lnum-cdh051">♦</a>
 <span class="sd-cn">Exe.</span>
  Hark, hark, my lord! what shouts are these?</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <i>and</i> Soldiers.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Seize on the shame-faced Henry, bear him hence;</div>
<div class="dverse">And once again proclaim us king of England.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh054" id="lnum-cdh054">♦</a>
 You are the fount that makes small brooks to flow:</div>
<div class="dverse"><span class="lnum">55</span>
 Now stops thy spring; my sea shall suck them dry,</div>
<div class="dverse">And swell so much the higher by their ebb.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh057" id="lnum-cdh057">♦</a>
 Hence with him to the Tower; let him not speak. <span class="sd-verseend">[<i>Exeunt some with King Henry.</i></span></div>
<div class="dverse">And, lords, towards Coventry bend we our course,</div>
<div class="dverse">Where peremptory Warwick now remains:</div>
<div class="dverse"><span class="lnum">60</span>
 The sun shines hot; and, if we use delay,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cdh061" id="lnum-cdh061">♦</a>
 Cold biting winter mars our hoped-for hay.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Away betimes, before his forces join,</div>
<div class="dverse">And take the great-grown traitor unawares:</div>
<div class="dverse">Brave warriors, march amain towards Coventry. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h3 class="h3main">ACT V.</h3>

<h4 class="h4main"><span class="dnavigate">cea</span>
<span class="smcaps">S<span>CENE</span></span> I. <i>Coventry</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">W<span>ARWICK</span>,</span> <i>the</i> Mayor of Coventry,
<i>two</i> Messengers, <i>and others upon the walls</i>.</div></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea001" id="lnum-cea001">♦</a>
 <span class="sd-cn">War.</span>
  Where is the post that came from valiant Oxford?</div>
<div class="dverse">How far hence is thy lord, mine honest fellow?</div>

<div class="dverse1"><span class="sd-cn">First Mess.</span>
 By this at Dunsmore, marching hitherward.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 How far off is our brother Montague?</div>
<div class="dverse"><span class="lnum">5</span>
 Where is the post that came from Montague?</div>

<div class="dverse1"><span class="sd-cn">Second Mess.</span>
 By this at Daintry, with a puissant troop.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">S<span>IR</span></span> <span class="smcaps">J<span>OHN</span></span> <span class="smcaps">S<span>OMERVILE</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea007" id="lnum-cea007">♦</a>
 <span class="sd-cn">War.</span>
  Say, Somervile, what says my loving son?</div>
<div class="dverse">And, by thy guess, how nigh is Clarence now?</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 At Southam I did leave him with his forces,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea010" id="lnum-cea010">10</a>
 And do expect him here some two hours hence.
 <span class="sd-verseend">[<i>Drum heard.</i></span></div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then Clarence is at hand; I hear his drum.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea012" id="lnum-cea012">♦</a>
 <span class="sd-cn">Som.</span>
  It is not his, my lord; here Southam lies:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea013" id="lnum-cea013">♦</a>
 The drum your honour hears marcheth from Warwick.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Who should that be? belike, unlook’d-for friends.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Som.</span>
  They are at hand, and you shall quickly know.</div>

<div class="sd-entry"><i>March: flourish. Enter</i>
<span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <i>and soldiers</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea016" id="lnum-cea016">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Go, trumpet, to the walls, and sound a parle.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 See how the surly Warwick mans the wall!</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 O unbid spite! is sportful Edward come?</div>
<div class="dverse">Where slept our scouts, or how are they seduced,</div>
<div class="dverse"><span class="lnum">20</span>
 That we could hear no news of his repair?</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Now, Warwick, wilt thou ope the city gates,</div>
<div class="dverse">Speak gentle words and humbly bend thy knee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea023" id="lnum-cea023">♦</a>
 Call Edward king and at his hands beg mercy?</div>
<div class="dverse">And he shall pardon thee these outrages.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">War.</span>
  Nay, rather, wilt thou draw thy forces hence,</div>
<div class="dverse">Confess who set thee up and pluck’d thee down,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea027" id="lnum-cea027">♦</a>
 Call Warwick patron and be penitent?</div>
<div class="dverse">And thou shalt still remain the Duke of York.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 I thought, at least, he would have said the king;</div>
<div class="dverse"><span class="lnum">30</span>
 Or did he make the jest against his will?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Is not a dukedom, sir, a goodly gift?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Ay, by my faith, for a poor earl to give:</div>
<div class="dverse">I’ll do thee service for so good a gift.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 ’Twas I that gave the kingdom to thy brother.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">K. Edw.</span>
  Why then ’tis mine, if but by Warwick’s gift.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Thou art no Atlas for so great a weight:</div>
<div class="dverse">And, weakling, Warwick takes his gift again;</div>
<div class="dverse">And Henry is my king, Warwick his subject.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 But Warwick’s king is Edward’s prisoner:</div>
<div class="dverse"><span class="lnum">40</span>
 And, gallant Warwick, do but answer this:</div>
<div class="dverse">What is the body when the head is off?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Alas, that Warwick had no more forecast,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea043" id="lnum-cea043">♦</a>
 But, whiles he thought to steal the single ten,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea044" id="lnum-cea044">♦</a>
 The king was slily finger’d from the deck!</div>
<div class="dverse"><span class="lnum">45</span>
 You left poor Henry at the Bishop’s palace,</div>
<div class="dverse">And, ten to one, you’ll meet him in the Tower.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 ’Tis even so; yet you are Warwick still.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea048" id="lnum-cea048">♦</a>
 <span class="sd-cn">Glou.</span>
  Come, Warwick, take the time; kneel down, kneel down:</div>
<div class="dverse">Nay, when? strike now, or else the iron cools.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea050" id="lnum-cea050">50</a>
 <span class="sd-cn">War.</span>
  I had rather chop this hand off at a blow,</div>
<div class="dverse">And with the other fling it at thy face,</div>
<div class="dverse">Than bear so low a sail, to strike to thee.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Sail how thou canst, have wind and tide thy friend,</div>
<div class="dverse">This hand, fast wound about thy coal-black hair,</div>
<div class="dverse"><span class="lnum">55</span>
 Shall, whiles thy head is warm and new cut off,</div>
<div class="dverse">Write in the dust this sentence with thy blood,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea057" id="lnum-cea057">♦</a>
 ‘Wind-changing Warwick now can change no more.’</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">O<span>XFORD</span>,</span> <i>with drum and colours</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea058" id="lnum-cea058">♦</a>
 <span class="sd-cn">War.</span>
  O cheerful colours! see where Oxford comes!</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea059" id="lnum-cea059">♦</a>
 <span class="sd-cn">Oxf.</span>
 Oxford, Oxford, for Lancaster! <span class="sd-verseend">[<i>He and his forces enter the city.</i></span></div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">Glou.</span>
  The gates are open, let us enter too.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 So other foes may set upon our backs.</div>
<div class="dverse">Stand we in good array; for they no doubt</div>
<div class="dverse">Will issue out again and bid us battle:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea064" id="lnum-cea064">♦</a>
 If not, the city being but of small defence,</div>
<div class="dverse"><span class="lnum">65</span>
 We’ll quickly rouse the traitors in the same.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 O, welcome, Oxford! for we want thy help.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">M<span>ONTAGUE</span>,</span> <i>with drum and colours</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea067" id="lnum-cea067">♦</a>
 <span class="sd-cn">Mont.</span>
 Montague, Montague, for Lancaster! <span class="sd-verseend">[<i>He and his forces enter the city.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea068" id="lnum-cea068">♦</a>
 <span class="sd-cn">Glou.</span>
  Thou and thy brother both shall buy this treason</div>
<div class="dverse">Even with the dearest blood your bodies bear.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">K. Edw.</span>
  The harder match’d, the greater victory:</div>
<div class="dverse">My mind presageth happy gain and conquest.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">S<span>OMERSET</span>,</span> <i>with drum and colours</i>.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Somerset, Somerset, for Lancaster! <span class="sd-verseend">[<i>He and his forces enter the city.</i></span></div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Two of thy name, both Dukes of Somerset,</div>
<div class="dverse">Have sold their lives unto the house of York;</div>
<div class="dverse"><span class="lnum">75</span>
 And thou shalt be the third, if this sword hold.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">C<span>LARENCE</span>,</span> <i>with drum and colours</i>.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And lo, where George of Clarence sweeps along,</div>
<div class="dverse">Of force enough to bid his brother battle;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea078" id="lnum-cea078">♦</a>
 With whom an upright zeal to right prevails</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea079" id="lnum-cea079">♦</a>
 More than the nature of a brother’s love!</div>
<div class="dverse"><span class="lnum">80</span>
 Come, Clarence, come; thou wilt, if Warwick call.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cea081" id="lnum-cea081">♦</a>
 <span class="sd-cn">Clar.</span>
 Father of Warwick, know you what this means?
 <span class="sd-verseend">[<i>Taking his red rose out of his hat.</i></span></div>
<div class="dverse">Look here, I throw my infamy at thee:</div>
<div class="dverse">I will not ruinate my father’s house,</div>
<div class="dverse">Who gave his blood to lime the stones together,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea085" id="lnum-cea085">85</a>
 And set up Lancaster. Why, trow’st thou, Warwick,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea086" id="lnum-cea086">♦</a>
 That Clarence is so harsh, so blunt, unnatural,</div>
<div class="dverse">To bend the fatal instruments of war</div>
<div class="dverse">Against his brother and his lawful king?</div>
<div class="dverse">Perhaps thou wilt object my holy oath:</div>
<div class="dverse"><span class="lnum">90</span>
 To keep that oath were more impiety</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea091" id="lnum-cea091">♦</a>
 Than Jephthah’s, when he sacrificed his daughter.</div>
<div class="dverse">I am so sorry for my trespass made</div>
<div class="dverse">That, to deserve well at my brother’s hands,</div>
<div class="dverse">I here proclaim myself thy mortal foe,</div>
<div class="dverse"><span class="lnum">95</span>
 With resolution, wheresoe’er I meet thee—</div>
<div class="dverse">As I will meet thee, if thou stir abroad—</div>
<div class="dverse">To plague thee for thy foul misleading me.</div>
<div class="dverse">And so, proud-hearted Warwick, I defy thee,</div>
<div class="dverse">And to my brother turn my blushing cheeks.</div>
<div class="dverse"><span class="lnum">100</span>
 Pardon me, Edward, I will make amends:</div>
<div class="dverse">And, Richard, do not frown upon my faults,</div>
<div class="dverse">For I will henceforth be no more unconstant.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Now welcome more, and ten times more beloved,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cea104" id="lnum-cea104">♦</a>
 Than if thou never hadst deserved our hate.</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">Glo.</span>
  Welcome, good Clarence; this is brother-like.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 O passing traitor, perjured and unjust!</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 What, Warwick, wilt thou leave the town, and fight?</div>
<div class="dverse">Or shall we beat the stones about thine ears?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Alas, I am not coop’d here for defence!</div>
<div class="dverse"><span class="lnum">110</span>
 I will away towards Barnet presently,</div>
<div class="dverse">And bid thee battle, Edward, if thou darest.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Yes, Warwick, Edward dares, and leads the way.</div>
<div class="dverse">Lords, to the field; Saint George and victory! <span class="sd-verseend">[<i>Exeunt King Edward and his company. March. Warwick and his company follow.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">ceb</span>
<span class="smcaps">S<span>CENE</span></span> II. <i>A field of battle near Barnet</i>.</h4>

<div class="sd-schg"><i>Alarum and excursions. Enter</i>
<span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <i>bringing forth</i> <span class="smcaps">W<span>ARWICK</span></span> <i>wounded</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ceb001" id="lnum-ceb001">♦</a>
 <span class="sd-cn">K. Edw.</span>
  So, lie thou there: die thou, and die our fear;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceb002" id="lnum-ceb002">♦</a>
 For Warwick was a bug that fear’d us all.</div>
<div class="dverse">Now, Montague, sit fast; I seek for thee,</div>
<div class="dverse">That Warwick’s bones may keep thine company. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">War.</span>
  Ah, who is nigh? come to me, friend or foe,</div>
<div class="dverse">And tell me who is victor, York or Warwick?</div>
<div class="dverse">Why ask I that? my mangled body shows,</div>
<div class="dverse">My blood, my want of strength, my sick heart shows,</div>
<div class="dverse">That I must yield my body to the earth</div>
<div class="dverse"><span class="lnum">10</span>
 And, by my fall, the conquest to my foe.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceb011" id="lnum-ceb011">♦</a>
 Thus yields the cedar to the axe’s edge,</div>
<div class="dverse">Whose arms gave shelter to the princely eagle,</div>
<div class="dverse">Under whose shade the ramping lion slept,</div>
<div class="dverse">Whose top-branch overpeer’d Jove’s spreading tree</div>
<div class="dverse"><span class="lnum">15</span>
 And kept low shrubs from winter’s powerful wind.</div>
<div class="dverse">These eyes, that now are dimm’d with death’s black veil,</div>
<div class="dverse">Have been as piercing as the mid-day sun,</div>
<div class="dverse">To search the secret treasons of the world:</div>
<div class="dverse">The wrinkles in my brows, now fill’d with blood,</div>
<div class="dverse"><span class="lnum">20</span>
 Were liken’d oft to kingly sepulchres;</div>
<div class="dverse">For who lived king, but I could dig his grave?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceb022" id="lnum-ceb022">♦</a>
 And who durst smile when Warwick bent his brow?</div>
<div class="dverse">Lo, now my glory smear’d in dust and blood!</div>
<div class="dverse">My parks, my walks, my manors that I had,</div>
<div class="dverse"><span class="lnum">25</span>
 Even now forsake me, and of all my lands</div>
<div class="dverse">Is nothing left me but my body’s length.</div>
<div class="dverse">Why, what is pomp, rule, reign, but earth and dust?</div>
<div class="dverse">And, live we how we can, yet die we must.</div>

<div class="sd-entry"><i>Enter</i> <span class="smcaps">O<span>XFORD</span></span> <i>and</i> <span class="smcaps">S<span>OMERSET</span></span>.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Ah, Warwick, Warwick! wert thou as we are,</div>
<div class="dverse"><span class="lnum">30</span>
 We might recover all our loss again:</div>
<div class="dverse">The queen from France hath brought a puissant power:</div>
<div class="dverse">Even now we heard the news: ah, couldst thou fly!</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Why, then I would not fly. Ah, Montague,</div>
<div class="dverse">If thou be there, sweet brother, take my hand,</div>
<div class="dverse"><span class="lnum">35</span>
 And with thy lips keep in my soul awhile!</div>
<div class="dverse">Thou lovest me not; for, brother, if thou didst,</div>
<div class="dverse">Thy tears would wash this cold congealed blood</div>
<div class="dverse">That glues my lips and will not let me speak.</div>
<div class="dverse">Come quickly, Montague, or I am dead.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Som.</span>
  Ah, Warwick! Montague hath breathed his last;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceb041" id="lnum-ceb041">♦</a>
 And to the latest gasp cried out for Warwick</div>
<div class="dverse">And said ‘Commend me to my valiant brother.’</div>
<div class="dverse">And more he would have said, and more he spoke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceb044" id="lnum-ceb044">♦</a>
 Which sounded like a clamour in a vault,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceb045" id="lnum-ceb045">45</a>
 That mought not be distinguish’d; but at last</div>
<div class="dverse">I well might hear, deliver’d with a groan,</div>
<div class="dverse">‘O, farewell, Warwick!’</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ceb048" id="lnum-ceb048">♦</a>
 <span class="sd-cn">War.</span>
  Sweet rest his soul! Fly, lords, and save yourselves;</div>

<div class="dverse">For Warwick bids you all farewell, to meet in heaven. <span class="sd-verseend">[<i>Dies.</i></span></div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Oxf.</span>
  Away, away, to meet the queen’s great power!
 <span class="sd-verseend">[<i>Here they bear away his body. Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cec</span>
<span class="smcaps">S<span>CENE</span></span> III. <i>Another part of the field</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span></span> <i>in triumph; with</i>
<span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">C<span>LARENCE</span>,</span> <i>and the rest</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cec001" id="lnum-cec001">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Thus far our fortune keeps an upward course,</div>
<div class="dverse">And we are graced with wreaths of victory.</div>
<div class="dverse">But, in the midst of this bright-shining day,</div>
<div class="dverse">I spy a black, suspicious, threatening cloud,</div>
<div class="dverse"><span class="lnum">5</span>
 That will encounter with our glorious sun,</div>
<div class="dverse">Ere he attain his easeful western bed:</div>
<div class="dverse">I mean, my lords, those powers that the queen</div>
<div class="dverse">Hath raised in Gallia have arrived our coast</div>
<div class="dverse">And, as we hear, march on to fight with us.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Clar.</span>
  A little gale will soon disperse that cloud</div>
<div class="dverse">And blow it to the source from whence it came:</div>
<div class="dverse">The very beams will dry those vapours up,</div>
<div class="dverse">For every cloud engenders not a storm.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 The queen is valued thirty thousand strong,</div>
<div class="dverse"><span class="lnum">15</span>
 And Somerset, with Oxford, fled to her:</div>
<div class="dverse">If she have time to breathe, be well assured</div>
<div class="dverse">Her faction will be full as strong as ours.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 We are advertised by our loving friends</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cec019" id="lnum-cec019">♦</a>
 That they do hold their course toward Tewksbury:</div>
<div class="dverse"><span class="lnum">20</span>
 We, having now the best at Barnet field,</div>
<div class="dverse">Will thither straight, for willingness rids way;</div>
<div class="dverse">And, as we march, our strength will be augmented</div>
<div class="dverse">In every county as we go along.</div>
<div class="dverse">Strike up the drum; cry ‘Courage!’ and away. <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">ced</span>
<span class="smcaps">S<span>CENE</span></span> IV. <i>Plains near Tewksbury</i>.</h4>

<div class="sd-schg"><i>March. Enter</i> <span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">M<span>ARGARET</span>,</span> <span class="smcaps">P<span>RINCE</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">S<span>OMERSET</span>,</span> <span class="smcaps">O<span>XFORD</span>,</span> <i>and</i> Soldiers.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ced001" id="lnum-ced001">♦</a>
 <span class="sd-cn">Q. Mar.</span>
  Great lords, wise men ne’er sit and wail their loss,</div>
<div class="dverse">But cheerly seek how to redress their harms.</div>
<div class="dverse">What though the mast be now blown overboard,</div>
<div class="dverse">The cable broke, the holding-anchor lost,</div>
<div class="dverse"><span class="lnum">5</span>
 And half our sailors swallow’d in the flood?</div>
<div class="dverse">Yet lives our pilot still. Is’t meet that he</div>
<div class="dverse">Should leave the helm and like a fearful lad</div>
<div class="dverse">With tearful eyes add water to the sea</div>
<div class="dverse">And give more strength to that which hath too much,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced010" id="lnum-ced010">10</a>
 Whiles, in his moan, the ship splits on the rock,</div>
<div class="dverse">Which industry and courage might have saved?</div>
<div class="dverse">Ah, what a shame! ah, what a fault were this!</div>
<div class="dverse">Say Warwick was our anchor; what of that?</div>
<div class="dverse">And Montague our topmast; what of him?</div>
<div class="dverse"><span class="lnum">15</span>
 Our slaughter’d friends the tackles; what of these?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced016" id="lnum-ced016">♦</a>
 Why, is not Oxford here another anchor?</div>
<div class="dverse">And Somerset another goodly mast?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced018" id="lnum-ced018">♦</a>
 The friends of France our shrouds and tacklings?</div>
<div class="dverse">And, though unskilful, why not Ned and I</div>
<div class="dverse"><span class="lnum">20</span>
 For once allow’d the skilful pilot’s charge?</div>
<div class="dverse">We will not from the helm to sit and weep,</div>
<div class="dverse">But keep our course, though the rough wind say no,</div>
<div class="dverse">From shelves and rocks that threaten us with wreck.</div>
<div class="dverse">As good to chide the waves as speak them fair.</div>
<div class="dverse"><span class="lnum">25</span>
 And what is Edward but a ruthless sea?</div>
<div class="dverse">What Clarence but a quicksand of deceit?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced027" id="lnum-ced027">♦</a>
 And Richard but a ragged fatal rock?</div>
<div class="dverse">All these the enemies to our poor bark.</div>
<div class="dverse">Say you can swim; alas, ’tis but a while!</div>
<div class="dverse"><span class="lnum">30</span>
 Tread on the sand; why, there you quickly sink:</div>
<div class="dverse">Bestride the rock; the tide will wash you off,</div>
<div class="dverse">Or else you famish; that’s a threefold death.</div>
<div class="dverse">This speak I, lords, to let you understand,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced034" id="lnum-ced034">♦</a>
 If case some one of you would fly from us,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced035" id="lnum-ced035">35</a>
 That there’s no hoped-for mercy with the brothers</div>
<div class="dverse">More than with ruthless waves, with sands and rocks.</div>
<div class="dverse">Why, courage then! what cannot be avoided</div>
<div class="dverse">’Twere childish weakness to lament or fear.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 Methinks a woman of this valiant spirit</div>
<div class="dverse"><span class="lnum">40</span>
 Should, if a coward heard her speak these words,</div>
<div class="dverse">Infuse his breast with magnanimity</div>
<div class="dverse">And make him, naked, foil a man at arms.</div>
<div class="dverse">I speak not this as doubting any here;</div>
<div class="dverse">For did I but suspect a fearful man,</div>
<div class="dverse"><span class="lnum">45</span>
 He should have leave to go away betimes,</div>
<div class="dverse">Lest in our need he might infect another</div>
<div class="dverse">And make him of like spirit to himself.</div>
<div class="dverse">If any such be here—as God forbid!—</div>
<div class="dverse">Let him depart before we need his help.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Oxf.</span>
  Women and children of so high a courage,</div>
<div class="dverse">And warriors faint! why, ’twere perpetual shame.</div>
<div class="dverse">O brave young prince! thy famous grandfather</div>
<div class="dverse">Doth live again in thee: long mayst thou live</div>
<div class="dverse">To bear his image and renew his glories!</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">Som.</span>
  And he that will not fight for such a hope,</div>
<div class="dverse">Go home to bed, and like the owl by day,</div>
<div class="dverse">If he arise, be mock’d and wonder’d at.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Thanks, gentle Somerset; sweet Oxford, thanks.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 And take his thanks that yet hath nothing else.</div>

<div class="sd-entry"><i>Enter a</i> Messenger.</div>

<div class="dverse1"><span class="lnum">60</span>
 <span class="sd-cn">Mess.</span>
  Prepare you, lords, for Edward is at hand,</div>
<div class="dverse">Ready to fight; therefore be resolute.</div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 I thought no less: it is his policy</div>
<div class="dverse">To haste thus fast, to find us unprovided.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 But he’s deceived; we are in readiness.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">Q. Mar.</span>
  This cheers my heart, to see your forwardness.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ced066" id="lnum-ced066">♦</a>
 <span class="sd-cn">Oxf.</span>
  Here pitch our battle; hence we will not budge.</div>

<div class="sd-entry"><i>Flourish and March. Enter</i>
<span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">C<span>LARENCE</span>,</span> <i>and soldiers</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ced067" id="lnum-ced067">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Brave followers, yonder stands the thorny wood,</div>
<div class="dverse">Which, by the heavens’ assistance and your strength,</div>
<div class="dverse">Must by the roots be hewn up yet ere night.</div>
<div class="dverse"><span class="lnum">70</span>
 I need not add more fuel to your fire,</div>
<div class="dverse">For well I wot ye blaze to burn them out:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced072" id="lnum-ced072">♦</a>
 Give signal to the fight, and to it, lords!</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Lords, knights, and gentlemen, what I should say</div>
<div class="dverse">My tears gainsay; for every word I speak,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced075" id="lnum-ced075">75</a>
 Ye see, I drink the water of mine eyes.</div>
<div class="dverse">Therefore, no more but this: Henry, your sovereign,</div>
<div class="dverse">Is prisoner to the foe; his state usurp’d,</div>
<div class="dverse">His realm a slaughter-house, his subjects slain,</div>
<div class="dverse">His statutes cancell’d and his treasure spent;</div>
<div class="dverse"><span class="lnum">80</span>
 And yonder is the wolf that makes this spoil.</div>
<div class="dverse">You fight in justice: then, in God’s name, lords,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ced082" id="lnum-ced082">♦</a>
 Be valiant, and give signal to the fight. <span class="sd-verseend">[<i>Alarum: Retreat: Excursions. Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cee</span>
<span class="smcaps">S<span>CENE</span></span> V. <i>Another part of the field</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">C<span>LARENCE</span>,</span> <i>and soldiers; with</i> <span class="smcaps">Q<span>UEEN</span></span>
<span class="smcaps">M<span>ARGARET</span>,</span> <span class="smcaps">O<span>XFORD</span>,</span> <i>and</i> <span class="smcaps">S<span>OMERSET</span>,</span> <i>prisoners</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee001" id="lnum-cee001">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Now here a period of tumultuous broils.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cee002" id="lnum-cee002">♦</a>
 Away with Oxford to Hames Castle straight:</div>
<div class="dverse">For Somerset, off with his guilty head.</div>
<div class="dverse">Go, bear them hence; I will not hear them speak.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">Oxf.</span>
  For my part, I’ll not trouble thee with words.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee006" id="lnum-cee006">♦</a>
 <span class="sd-cn">Som.</span>
 Nor I, but stoop with patience to my fortune. <span class="sd-verseend">[<i>Exeunt Oxford and Somerset, guarded.</i></span></div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 So part we sadly in this troublous world,</div>
<div class="dverse">To meet with joy in sweet Jerusalem.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Is proclamation made, that who finds Edward</div>
<div class="dverse"><span class="lnum">10</span>
 Shall have a high reward, and he his life?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee011" id="lnum-cee011">♦</a>
 <span class="sd-cn">Glo.</span>
  It is: and lo, where youthful Edward comes!</div>

<div class="sd-entry"><i>Enter</i> Soldiers, <i>with</i> <span class="smcaps">P<span>RINCE</span></span> <span class="smcaps">E<span>DWARD</span></span>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee012" id="lnum-cee012">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Bring forth the gallant, let us hear him speak.</div>
<div class="dverse">What! can so young a thorn begin to prick?</div>
<div class="dverse">Edward, what satisfaction canst thou make</div>
<div class="dverse"><span class="lnum">15</span>
 For bearing arms, for stirring up my subjects,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cee016" id="lnum-cee016">♦</a>
 And all the trouble thou hast turn’d me to?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee017" id="lnum-cee017">♦</a>
 <span class="sd-cn">Prince.</span>
  Speak like a subject, proud ambitious York!</div>
<div class="dverse">Suppose that I am now my father’s mouth;</div>
<div class="dverse">Resign thy chair, and where I stand kneel thou,</div>
<div class="dverse"><span class="lnum">20</span>
 Whilst I propose the selfsame words to thee,</div>
<div class="dverse">Which, traitor, thou wouldst have me answer to.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Ah, that thy father had been so resolved!</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 That you might still have worn the petticoat,</div>
<div class="dverse">And ne’er have stol’n the breech from Lancaster.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Prince.</span>
  Let Æsop fable in a winter’s night;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cee026" id="lnum-cee026">♦</a>
 His currish riddles sort not with this place.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee027" id="lnum-cee027">♦</a>
 <span class="sd-cn">Glou.</span>
  By heaven, brat, I’ll plague ye for that word.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Ay, thou wast born to be a plague to men.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 For God’s sake, take away this captive scold.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Prince.</span>
  Nay, take away this scolding crook-back rather.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Peace, wilful boy, or I will charm your tongue.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 Untutor’d lad, thou art too malapert.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee033" id="lnum-cee033">♦</a>
 <span class="sd-cn">Prince.</span>
  I know my duty; you are all undutiful:</div>
<div class="dverse">Lascivious Edward, and thou perjured George,</div>
<div class="dverse"><span class="lnum">35</span>
 And thou mis-shapen Dick, I tell ye all</div>
<div class="dverse">I am your better, traitors as ye are:</div>
<div class="dverse">And thou usurp’st my father’s right and mine.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee038" id="lnum-cee038">♦</a>
 <span class="sd-cn">K. Edw.</span>
 Take that, thou likeness of this railer here. <span class="sd-verseend">[<i>Stabs him.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee039" id="lnum-cee039">♦</a>
 <span class="sd-cn">Glou.</span>
 Sprawl’st thou? take that, to end thy agony. <span class="sd-verseend">[<i>Stabs him.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee040" id="lnum-cee040">40</a>
 <span class="sd-cn">Clar.</span>
 And there’s for twitting me with perjury. <span class="sd-verseend">[<i>Stabs him.</i></span></div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 O, kill me too!</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Marry, and shall. <span class="sd-verseend">[<i>Offers to kill her.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Hold, Richard, hold; for we have done too much.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee044" id="lnum-cee044">♦</a>
 <span class="sd-cn">Glou.</span>
  Why should she live, to fill the world with words?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee045" id="lnum-cee045">45</a>
 <span class="sd-cn">K. Edw.</span>
  What, doth she swoon? use means for her recovery.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Clarence, excuse me to the king my brother;</div>
<div class="dverse">I’ll hence to London on a serious matter:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cee048" id="lnum-cee048">♦</a>
 Ere ye come there, be sure to hear some news.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 What? what?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee050" id="lnum-cee050">50</a>
 <span class="sd-cn">Glou.</span>
 The Tower, the Tower. <span class="sd-verseend">[<i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 O Ned, sweet Ned! speak to thy mother, boy!</div>
<div class="dverse">Canst thou not speak? O traitors! murderers!</div>
<div class="dverse">They that stabb’d Cæsar shed no blood at all,</div>
<div class="dverse">Did not offend, nor were not worthy blame,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cee055" id="lnum-cee055">55</a>
 If this foul deed were by to equal it:</div>
<div class="dverse">He was a man; this, in respect, a child:</div>
<div class="dverse">And men ne’er spend their fury on a child.</div>
<div class="dverse">What’s worse than murderer, that I may name it?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cee059" id="lnum-cee059">♦</a>
 No, no, my heart will burst, an if I speak:</div>
<div class="dverse"><span class="lnum">60</span>
 And I will speak, that so my heart may burst.</div>
<div class="dverse">Butchers and villains! bloody cannibals!</div>
<div class="dverse">How sweet a plant have you untimely cropp’d!</div>
<div class="dverse">You have no children, butchers! if you had,</div>
<div class="dverse">The thought of them would have stirr’d up remorse:</div>
<div class="dverse"><span class="lnum">65</span>
 But if you ever chance to have a child,</div>
<div class="dverse">Look in his youth to have him so cut off</div>
<div class="dverse">As, deathsmen, you have rid this sweet young prince!</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Away with her; go, bear her hence perforce.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Nay, never bear me hence, dispatch me here;</div>
<div class="dverse"><span class="lnum">70</span>
 Here sheathe thy sword, I’ll pardon thee my death:</div>
<div class="dverse">What, wilt thou not? then, Clarence, do it thou.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 By heaven, I will not do thee so much ease.</div>

<div class="dverse1"><span class="sd-cn">Q. Mar.</span>
 Good Clarence, do; sweet Clarence, do thou do it.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 Didst thou not hear me swear I would not do it?</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Q. Mar.</span>
  Ay, but thou usest to forswear thyself:</div>
<div class="dverse">’Twas sin before, but now ’tis charity.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cee077" id="lnum-cee077">♦</a>
 What, wilt thou not? Where is that devil’s butcher,</div>
<div class="dverse">Hard-favour’d Richard? Richard, where art thou?</div>
<div class="dverse">Thou art not here: murder is thy alms-deed;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cee080" id="lnum-cee080">80</a>
 Petitioners for blood thou ne’er put’st back.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Away, I say; I charge ye, bear her hence.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cee082" id="lnum-cee082">♦</a>
 <span class="sd-cn">Q. Mar.</span>
 So come to you and yours, as to this prince! <span class="sd-verseend">[<i>Exit, led out forcibly.</i></span></div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Where’s Richard gone?</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 To London, all in post; and, as I guess,</div>
<div class="dverse"><span class="lnum">85</span>
 To make a bloody supper in the Tower.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 He’s sudden, if a thing comes in his head.</div>
<div class="dverse">Now march we hence: discharge the common sort</div>
<div class="dverse">With pay and thanks, and let’s away to London,</div>
<div class="dverse">And see our gentle queen how well she fares:</div>
<div class="dverse"><span class="lnum">90</span>
 By this, I hope, she hath a son for me.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">cef</span>
<span class="smcaps">S<span>CENE</span></span> VI. <i>London. The Tower</i>.</h4>

<div class="sd-schg"><i>Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">H<span>ENRY</span></span> <i>and</i> <span class="smcaps">G<span>LOUCESTER</span>,</span> <i>with the</i> Lieutenant, <i>on the walls</i>.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cef001" id="lnum-cef001">♦</a>
 <span class="sd-cn">Glou.</span>
  Good day, my lord. What, at your book so hard?</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Ay, my good lord:—my lord, I should say rather;</div>
<div class="dverse">’Tis sin to flatter; ‘good’ was little better:</div>
<div class="dverse">‘Good Gloucester’ and ‘good devil’ were alike,</div>
<div class="dverse"><span class="lnum">5</span>
 And both preposterous; therefore, not ‘good lord.’</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cef006" id="lnum-cef006">♦</a>
 <span class="sd-cn">Glou.</span>
 Sirrah, leave us to ourselves: we must confer. <span class="sd-verseend">[<i>Exit Lieutenant.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cef007" id="lnum-cef007">♦</a>
 <span class="sd-cn">K. Hen.</span>
  So flies the reckless shepherd from the wolf;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef008" id="lnum-cef008">♦</a>
 So first the harmless sheep doth yield his fleece,</div>
<div class="dverse">And next his throat unto the butcher’s knife.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef010" id="lnum-cef010">10</a>
 What scene of death hath Roscius now to act?</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Suspicion always haunts the guilty mind;</div>
<div class="dverse">The thief doth fear each bush an officer.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 The bird that hath been limed in a bush,</div>
<div class="dverse">With trembling wings misdoubteth every bush;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef015" id="lnum-cef015">15</a>
 And I, the hapless male to one sweet bird,</div>
<div class="dverse">Have now the fatal object in my eye</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef017" id="lnum-cef017">♦</a>
 Where my poor young was limed, was caught and kill’d.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Why, what a peevish fool was that of Crete,</div>
<div class="dverse">That taught his son the office of a fowl!</div>
<div class="dverse"><span class="lnum">20</span>
 And yet, for all his wings, the fool was drown’d.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cef021" id="lnum-cef021">♦</a>
 <span class="sd-cn">K. Hen.</span>
  I, Dædalus; my poor boy, Icarus;</div>
<div class="dverse">Thy father, Minos, that denied our course;</div>
<div class="dverse">The sun that sear’d the wings of my sweet boy</div>
<div class="dverse">Thy brother Edward, and thyself the sea</div>
<div class="dverse"><span class="lnum">25</span>
 Whose envious gulf did swallow up his life.</div>
<div class="dverse">Ah, kill me with thy weapon, not with words!</div>
<div class="dverse">My breast can better brook thy dagger’s point</div>
<div class="dverse">Than can my ears that tragic history.</div>
<div class="dverse">But wherefore dost thou come? is’t for my life?</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Glou.</span>
  Think’st thou I am an executioner?</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 A persecutor, I am sure, thou art:</div>
<div class="dverse">If murdering innocents be executing,</div>
<div class="dverse">Why, then thou art an executioner.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 Thy son I kill’d for his presumption.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cef035" id="lnum-cef035">35</a>
 <span class="sd-cn">K. Hen.</span>
  Hadst thou been kill’d when first thou didst presume,</div>
<div class="dverse">Thou hadst not lived to kill a son of mine.</div>
<div class="dverse">And thus I prophesy, that many a thousand,</div>
<div class="dverse">Which now mistrust no parcel of my fear,</div>
<div class="dverse">And many an old man’s sigh and many a widow’s,</div>
<div class="dverse"><span class="lnum">40</span>
 And many an orphan’s water-standing eye—</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef041" id="lnum-cef041">♦</a>
 Men for their sons, wives for their husbands,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef042" id="lnum-cef042">♦</a>
 And orphans for their parents’ timeless death—</div>
<div class="dverse">Shall rue the hour that ever thou wast born.</div>
<div class="dverse">The owl shriek’d at thy birth,—an evil sign;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef045" id="lnum-cef045">45</a>
 The night-crow cried, aboding luckless time;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef046" id="lnum-cef046">♦</a>
 Dogs howl’d, and hideous tempest shook down trees;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef047" id="lnum-cef047">♦</a>
 The raven rook’d her on the chimney’s top,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef048" id="lnum-cef048">♦</a>
 And chattering pies in dismal discords sung.</div>
<div class="dverse">Thy mother felt more than a mother’s pain,</div>
<div class="dverse"><span class="lnum">50</span>
 And yet brought forth less than a mother’s hope,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef051" id="lnum-cef051">♦</a>
 To wit, an indigested and deformed lump,</div>
<div class="dverse">Not like the fruit of such a goodly tree.</div>
<div class="dverse">Teeth hadst thou in thy head when thou wast born,</div>
<div class="dverse">To signify thou camest to bite the world:</div>
<div class="dverse"><span class="lnum">55</span>
 And, if the rest be true which I have heard,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef056" id="lnum-cef056">♦</a>
 Thou camest—</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-cef057" id="lnum-cef057">♦</a>
 <span class="sd-cn">Glou.</span>
 I’ll hear no more: die, prophet, in thy speech: <span class="sd-verseend">[<i>Stabs him.</i></span></div>
<div class="dverse">For this, amongst the rest, was I ordain’d.</div>

<div class="dverse1"><span class="sd-cn">K. Hen.</span>
 Ay, and for much more slaughter after this.</div>
<div class="dverse"><span class="lnum">60</span>
 O, God forgive my sins, and pardon thee!
 <span class="sd-verseend">[<i>Dies.</i></span></div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 What, will the aspiring blood of Lancaster</div>
<div class="dverse">Sink in the ground? I thought it would have mounted.</div>
<div class="dverse">See how my sword weeps for the poor king’s death!</div>
<div class="dverse">O, may such purple tears be alway shed</div>
<div class="dverse"><span class="lnum">65</span>
 From those that wish the downfall of our house!</div>
<div class="dverse">If any spark of life be yet remaining,</div>
<div class="dverse">Down, down to hell; and say I sent thee thither: <span class="sd-verseend">[<i>Stabs him again.</i></span></div>
<div class="dverse">I, that have neither pity, love, nor fear.</div>
<div class="dverse">Indeed, ’tis true that Henry told me of;</div>
<div class="dverse"><span class="lnum">70</span>
 For I have often heard my mother say</div>
<div class="dverse">I came into the world with my legs forward:</div>
<div class="dverse">Had I not reason, think ye, to make haste,</div>
<div class="dverse">And seek their ruin that usurp’d our right?</div>
<div class="dverse">The midwife wonder’d and the women cried</div>
<div class="dverse"><span class="lnum">75</span>
 ‘O, Jesus bless us, he is born with teeth!’</div>
<div class="dverse">And so I was; which plainly signified</div>
<div class="dverse">That I should snarl and bite and play the dog.</div>
<div class="dverse">Then, since the heavens have shaped my body so,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef079" id="lnum-cef079">♦</a>
 Let hell make crook’d my mind to answer it.</div>
<div class="dverse"><span class="lnum">80</span>
 I have no brother, I am like no brother;</div>
<div class="dverse">And this word ‘love,’ which greybeards call divine,</div>
<div class="dverse">Be resident in men like one another</div>
<div class="dverse">And not in me: I am myself alone.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef084" id="lnum-cef084">♦</a>
 Clarence, beware; thou keep’st me from the light:</div>
<div class="dverse"><span class="lnum">85</span>
 But I will sort a pitchy day for thee;</div>
<div class="dverse">For I will buz abroad such prophecies</div>
<div class="dverse">That Edward shall be fearful of his life,</div>
<div class="dverse">And then, to purge his fear, I’ll be thy death.</div>
<div class="dverse">King Henry and the prince his son are gone:</div>
<div class="dverse"><span class="lnum">90</span>
 Clarence, thy turn is next, and then the rest,</div>
<div class="dverse">Counting myself but bad till I be best.</div>
<div class="dverse">I’ll throw thy body in another room</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-cef093" id="lnum-cef093">♦</a>
 And triumph, Henry, in thy day of doom. <span class="sd-verseend">[<i>Exit, with the body.</i></span></div>

<div class="section">
<h4 class="h4main"><span class="dnavigate">ceg</span>
<span class="smcaps">S<span>CENE</span></span> VII. <i>London. The palace</i>.</h4>

<div class="sd-schg"><i>Flourish. Enter</i> <span class="smcaps">K<span>ING</span></span> <span class="smcaps">E<span>DWARD</span>,</span> <span class="smcaps">Q<span>UEEN</span></span> <span class="smcaps">E<span>LIZABETH</span>,</span> <span class="smcaps">C<span>LARENCE</span>,</span> <span class="smcaps">G<span>LOUCESTER</span>,</span> <span class="smcaps">H<span>ASTINGS</span>,</span> <i>a</i> Nurse <i>with the young Prince, and</i> Attendants.</div>
</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ceg001" id="lnum-ceg001">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Once more we sit in England’s royal throne,</div>
<div class="dverse">Re-purchased with the blood of enemies.</div>
<div class="dverse">What valiant foemen, like to autumn’s corn,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg004" id="lnum-ceg004">♦</a>
 Have we mow’d down in tops of all their pride!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg005" id="lnum-ceg005">5</a>
 Three Dukes of Somerset, threefold renown’d</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg006" id="lnum-ceg006">♦</a>
 For hardy and undoubted champions;</div>
<div class="dverse">Two Cliffords, as the father and the son,</div>
<div class="dverse">And two Northumberlands; two braver men</div>
<div class="dverse">Ne’er spurr’d their coursers at the trumpet’s sound;</div>
<div class="dverse"><span class="lnum">10</span>
 With them, the two brave bears, Warwick and Montague,</div>
<div class="dverse">That in their chains fetter’d the kingly lion</div>
<div class="dverse">And made the forest tremble when they roar’d.</div>
<div class="dverse">Thus have we swept suspicion from our seat</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg014" id="lnum-ceg014">♦</a>
 And made our footstool of security.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg015" id="lnum-ceg015">15</a>
 Come hither, Bess, and let me kiss my boy.</div>
<div class="dverse">Young Ned, for thee, thine uncles and myself</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg017" id="lnum-ceg017">♦</a>
 Have in our armours watch’d the winter’s night,</div>
<div class="dverse">Went all afoot in summer’s scalding heat,</div>
<div class="dverse">That thou mightst repossess the crown in peace:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg020" id="lnum-ceg020">20</a>
 And of our labours thou shalt reap the gain.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ceg021" id="lnum-ceg021">♦</a>
 <span class="sd-cn">Glou.</span>
 <span class="sd-inline">[<i>Aside</i>]</span>
 I’ll blast his harvest, if your head were laid;</div>
<div class="dverse">For yet I am not look’d on in the world.</div>
<div class="dverse">This shoulder was ordain’d so thick to heave;</div>
<div class="dverse">And heave it shall some weight, or break my back:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg025" id="lnum-ceg025">25</a>
 Work thou the way,—and thou shalt execute.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Clarence and Gloucester, love my lovely queen;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg027" id="lnum-ceg027">♦</a>
 And kiss your princely nephew, brothers both.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ceg028" id="lnum-ceg028">♦</a>
 <span class="sd-cn">Clar.</span>
  The duty that I owe unto your majesty</div>
<div class="dverse">I seal upon the lips of this sweet babe.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ceg030" id="lnum-ceg030">30</a>
 <span class="sd-cn">Q. Eliz.</span>
  Thanks, noble Clarence; worthy brother, thanks.</div>

<div class="dverse1"><span class="sd-cn">Glou.</span>
 And, that I love the tree from whence thou sprang’st,</div>
<div class="dverse">Witness the loving kiss I give the fruit.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg033" id="lnum-ceg033">♦</a>
 <span class="sd-inline">[<i>Aside.</i>]</span>
 To say the truth, so Judas kiss’d his master,</div>
<div class="dverse">And cried, ‘all hail!’ when as he meant all harm.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">K. Edw.</span>
  Now am I seated as my soul delights,</div>
<div class="dverse">Having my country’s peace and brothers’ loves.</div>

<div class="dverse1"><span class="sd-cn">Clar.</span>
 What will your grace have done with Margaret?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg038" id="lnum-ceg038">♦</a>
 Reignier, her father, to the king of France</div>
<div class="dverse">Hath pawn’d the Sicils and Jerusalem,</div>
<div class="dverse"><span class="lnum">40</span>
 And hither have they sent it for her ransom.</div>

<div class="dverse1"><span class="sd-cn">K. Edw.</span>
 Away with her, and waft her hence to France.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg042" id="lnum-ceg042">♦</a>
 And now what rests but that we spend the time</div>
<div class="dverse">With stately triumphs, mirthful comic shows,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg044" id="lnum-ceg044">♦</a>
 Such as befits the pleasure of the court?</div>
<div class="dverse"><span class="lnum">45</span>
 Sound drums and trumpets! farewell sour annoy!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ceg046" id="lnum-ceg046">♦</a>
 For here, I hope, begins our lasting joy.
 <span class="sd-verseend">[<i>Exeunt.</i></span></div>

<div class="right toppada">
<a href="#idtoc" class="pginternal">toc</a></div>

<ul>
<li><h3 class="h3main" title="LINENOTES to III King Henry VI." id="idcln">
LINENOTES TO III KING HENRY VI.</h3></li>

<li><a class="fnlabel pginternal" href="#lnum-caa001" id="lnote-caa001">caa001</a>
<span class="smcaps">A<span>CT</span></span> <span class="smmaj">I.</span> <span class="smcaps">S<span>CENE</span></span> <span class="smmaj">I.</span>] Actus Primus. Scæna Prima. Ff. ¶ London.] Theobald. ¶ The Parliament-house.] Capell. Before the Parliament-House. Hanmer. ¶ Alarum. Enter the Duke of York......] Alarum. Enter Plantagenet...... Ff. Drums. Enter Soldiers of York’s Party, as breaking in. Then, Enter the Duke of York...and others, with white roses in their Hats. Capell, partly following (Qq). ¶ <i>hands.</i>] <i>hands!</i> Theobald. <i>hands?</i> Ff.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa011" id="lnote-caa011">caa011</a>
<i>dangerously</i>] (Qq) Theobald. <i>dangerous</i> Ff.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa013" id="lnote-caa013">caa013</a>
[Showing his bloody sword. Capell.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa014" id="lnote-caa014">caa014</a>
[To Warwick, showing his. Capell. To York, showing his. Malone.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa016" id="lnote-caa016">caa016</a>
[Throwing down......head.] Theobald. Shewing...head. Hanmer.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa018" id="lnote-caa018">caa018</a>
<i>But is your</i>] <i>Is his</i> Pope. <i>Is your</i> Capell. <i>What, is your</i> Malone, from (Qq). <i>What, ’s your</i> Steevens conj. ¶ caa018, caa019: <i>But is your......Gaunt</i>] Norf. <i>Is his...Gaunt</i> Hanmer.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa019" id="lnote-caa019">caa019</a>
<i>hope</i>] <i>end</i> Capell. <i>hap</i> Anon. apud Rann conj. ¶ <i>Gaunt!</i>] Theobald. <i>Gaunt</i> Ff.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa020" id="lnote-caa020">caa020</a>
<i>shake</i>] Ff. <i>shape</i> (Qq).</li>

<li><a class="fnlabel pginternal" href="#lnum-caa021" id="lnote-caa021">caa021</a>
<i>I. Victorious...York,</i>] Theobald. <i>I, victorious...Yorke.</i> Ff.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa022" id="lnote-caa022">caa022</a>
<i>that</i>] <span class="nowrap">F<sub>1</sub></span> <span class="nowrap">F<sub>2</sub>.</span> <i>the</i> <span class="nowrap">F<sub>3</sub></span> <span class="nowrap">F<sub>4</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-caa027" id="lnote-caa027">caa027</a>
<i>this is</i>] <i>it is</i> Capell. ¶ <i>heirs’</i>] Warburton. <i>Heires</i> <span class="nowrap">F<sub>1</sub></span>
<span class="nowrap">F<sub>2</sub>.</span> <i>Heirs</i> <span class="nowrap">F<sub>3</sub></span> <span class="nowrap">F<sub>4</sub>.</span> <i>heir’s</i> Hanmer.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa029" id="lnote-caa029">caa029</a>
<i>we have</i>] <i>are we</i> Capell, from (Qq).</li>

<li><a class="fnlabel pginternal" href="#lnum-caa032" id="lnote-caa032">caa032</a>
[They go up.] Omitted by Capell.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa034" id="lnote-caa034">caa034</a>
<i>thrust you out perforce</i>] <i>thrust you out by force</i> Rowe. <i>put us out by force</i> Capell, from (Qq). ¶ [To the Soldiers, who retire. Capell.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa036" id="lnote-caa036">caa036</a>
<i>council</i>] Pope. <i>counsaile</i> <span class="nowrap">F<sub>1</sub></span> <span class="nowrap">F<sub>2</sub>.</span> <i>counsell</i> <span class="nowrap">F<sub>3</sub>.</span>
<i>Counsel</i> <span class="nowrap">F<sub>4</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-caa041" id="lnote-caa041">caa041</a>
<i>Henry</i>] <i>Harry</i> Hanmer. ¶ <i>deposed</i>] <i>be deposde</i> (Qq).</li>

<li><a class="fnlabel pginternal" href="#lnum-caa043" id="lnote-caa043">caa043</a>
<i>not, my lords; be</i>] <i>not, my lords, be</i> Rowe. <i>not, my lords be</i> Ff.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa048" id="lnote-caa048">caa048</a>
<i>dares</i>] <i>dare</i> Rowe. ¶ [putting him in the Throne. Capell.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa049" id="lnote-caa049">caa049</a>
[Warwick leads York to the throne, who seats him. Johnson. ¶ Flourish.] <span class="nowrap">F<sub>1</sub>.</span> om. <span class="nowrap">F<sub>2</sub></span> <span class="nowrap">F<sub>3</sub></span> <span class="nowrap">F<sub>4</sub>.</span> ¶ Enter...and the rest.] Ff. Enter...and others, at the further end of the stage. Johnson. Flourish. Enter...and others, with red Roses in their Hats. Capell, partly following (Qq).</li>

<li><a class="fnlabel pginternal" href="#lnum-caa050" id="lnote-caa050">caa050</a>
<span class="smcaps">S<span>CENE</span></span> <span class="smmaj">II.</span> Pope.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa055" id="lnote-caa055">caa055</a>
<i>you both have vow’d</i>] <i>you have both vow’d</i> <span class="nowrap">F<sub>4</sub>.</span> <i>you vow’d</i>
Pope. <i>you have vow’d</i> Collier MS. <i>both have vow’d</i> Collier conj. ¶ caa055, caa056: <i>vow’d revenge On...favourites and his friends.</i>] <i>vow’d Revenge on...his favourers.</i> Capell. <i>vow’d Revenge on him, his favourers, and his friends.</i> Rann.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa057" id="lnote-caa057">caa057</a>
<i>heavens be</i>] <i>heavens, be</i> Capell.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa062" id="lnote-caa062">caa062</a>
<i>poltroons, such as he</i>] <i>poultroones, such as he</i> <span class="nowrap">F<sub>1</sub>.</span>
<i>poultroones, and such is he</i> <span class="nowrap">F<sub>2</sub></span> <span class="nowrap">F<sub>3</sub>.</span> <i>poltroons, and such is he</i> <span class="nowrap">F<sub>4</sub>.</span>
<i>poltroons, and such as he</i> Capell.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa066" id="lnote-caa066">caa066</a>
<i>spoken, cousin: be</i>] <i>spoken, cousin, be</i> Theobald. <i>spoken, cousin be</i> Ff.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa069" id="lnote-caa069">caa069</a>
Exe.] Theobald, from (Qq). Westm. Ff.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa070" id="lnote-caa070">caa070</a>
<i>the thought of this from</i>] <i>it from the thoughts of</i> (Qq) Capell.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa073" id="lnote-caa073">caa073</a>
[To the Duke. Rowe (ed. 2). They advance to the Duke. Johnson.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa076" id="lnote-caa076">caa076</a>
<i>thy</i>] <i>my</i> <span class="nowrap">F<sub>2</sub>.</span> ¶ <i>I am thine</i>] <i>Henry, I am thine</i> Rowe. <i>Thou ’rt deceiv’d, I’m thine</i> Theobald, from (Qq).</li>

<li><a class="fnlabel pginternal" href="#lnum-caa078" id="lnote-caa078">caa078</a>
<i>’Twas</i>] (Qq) Pope. <i>It was</i> Ff. ¶ <i>earldom was</i>] <i>kingdom is</i>
(Qq) Theobald.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa083" id="lnote-caa083">caa083</a>
<i>and that’s</i>] <span class="nowrap">F<sub>2</sub></span> <span class="nowrap">F<sub>3</sub></span> <span class="nowrap">F<sub>4</sub>.</span> <i>that’s</i> <span class="nowrap">F<sub>1</sub>.</span> <i>and that is</i> (Qq). <i>that is</i> Collier.</li>

<li><a class="fnlabel pginternal" href="#lnum-caa093" id="lnote-caa093">caa093</a>
